window.__CH("c32",["<div class=\"hw\">V, v</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\"><num>①</num> ラテン語アルファベットの第20字;本来, この字母は半母音 [w] と母音 [u] の両方を表わしたが, 本辞書では, 母音 [u] には中世につくられた字母 U, u を用いるので, V, v は半母音 [w] のみを表わす.</div><div class=\"def\"><num>②</num> (ローマ数字)=5.</div>\r\n","<div class=\"hw\">Vacalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Vahalis\">Vahalis</a>.</div>\r\n","<div class=\"hw\">vacanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vaco]</div><div class=\"def\">余計に, むだに.</div>\r\n","<div class=\"hw\">vacantīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vaco]</div><div class=\"def\">定員外の, 余分な.</div>\r\n","<div class=\"hw\">vacca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">雌牛.</div>\r\n","<div class=\"hw\">Vaccaeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウァッカエイー《Hispania Tarraconensis の Durius 川(現 Duero, Douro)中流域にいた一部族》.</div>\r\n","<div class=\"hw\">vaccillō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">=<a href=\"entry://vacillō\">vacillo</a>.</div>\r\n","<div class=\"hw\">vaccula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vacca]</div><div class=\"def\">若い雌牛.</div>\r\n","<div class=\"hw\">vaccīna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vaccinus]</div><div class=\"def\">〘医〙</div><div class=\"def\"><num>①</num> 牛痘瘡.</div><div class=\"def\"><num>②</num> 痘苗;ワクチン.</div>\r\n","<div class=\"hw\">vaccīnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> ヒヤシンス.</div><div class=\"def\"><num>②</num> コケモモ(の実).</div>\r\n","<div class=\"hw\">vaccīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vacca]</div><div class=\"def\">雌牛の.</div>\r\n","<div class=\"hw\">vaccīnātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙ワクチン接種;種痘.</div>\r\n","<div class=\"hw\">vacerra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 杭<SUB>くい</SUB>.</div><div class=\"def\"><num>②</num> 杭で作った柵<SUB>さく</SUB>.</div><div class=\"def\"><num>③</num> ばか, でくの棒.</div>\r\n","<div class=\"hw\">vacerrōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vacerra\">vacerra</a>]</div><div class=\"def\">頭のおかしい, 気のふれた(=<a href=\"entry://cerrītus\">cerritus</a>).</div>\r\n","<div class=\"hw\">vacillātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vacillo]</div><div class=\"def\">身体を左右にゆすること;よろめくこと.</div>\r\n","<div class=\"hw\">vacillātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://vacillō\">vacillō</a>]</div><div class=\"def\">詐欺[ぺてん]師.</div>\r\n","<div class=\"hw\">vacillō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> よろめく, ふらふらする.</div><div class=\"def\"><num>②</num> 不安定な[危なっかしい]状態にある</div><div class=\"ex\"><i>in aere alieno vacillare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">借金漬けになっている.</span></div><div class=\"def\"><num>③</num> ためらう.</div>\r\n","<div class=\"hw\">vacuitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vacuus]</div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>であること;何もない空間.</div><div class=\"def\"><num>②</num> 免れていること;余暇.</div>\r\n","<div class=\"hw\">vacuolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://vacuum\">vacuum</a>]</div><div class=\"def\">〘生物〙空胞, 液胞.</div>\r\n","<div class=\"hw\">vacuum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vacuus\">vacuus</a>]</div><div class=\"def\"><num>①</num> 空虚;空間.</div><div class=\"def\"><num>②</num> 無人[無防備]の地.</div><div class=\"def\"><num>③</num> 暇.</div><div class=\"def\"><num>④</num> 空位, 空席.</div>\r\n","<div class=\"hw\">vacuus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vaco]</div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>の;うつろな, 実体のない.</div><div class=\"def\"><num>②</num> (...を)欠いた, (...を)免れた 〈(a)re;+<i>gen</i>〉</div><div class=\"ex\"><i>consilium periculo vacuum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">危険のない計画</span></div><div class=\"ex\"><i>oppidum vacuum a bello</i> (<author>C<small>IC</small></author>)<span class=\"ext\">戦争の心配のない町</span></div><div class=\"ex\"><i>litterae rerum vacuae</i> (<author>T<small>AC</small></author>)<span class=\"ext\">実質のない書簡.</span></div><div class=\"def\"><num>③</num> 無人の, 人気<SUB>ひとけ</SUB>のない.</div><div class=\"def\"><num>④</num> 無防備の.</div><div class=\"def\"><num>⑤</num> 空位の;統治者のいない.</div><div class=\"def\"><num>⑥</num> (女性が)未婚の, 独身の.</div><div class=\"def\"><num>⑦</num> 暇な;心配事のない, 落ちついた.</div><div class=\"def\"><num>⑧</num> (...に)開かれている 〈+<i>dat</i>〉</div><div class=\"ex\"><i>necato filio vacuam domum scelestis nuptiis fecisse</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">息子を殺して邪悪な結婚に好都合な家にした.</span></div><div class=\"def\"><num>⑨</num> 余計な, むだな.</div>\r\n","<div class=\"hw\">vacuātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vacuō\">vacuo</a>.</div>\r\n","<div class=\"hw\">vacuē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[vacuus]</div><div class=\"def\">むなしく, いたずらに.</div>\r\n","<div class=\"hw\">vacuēfacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://vacuēfaciō\">vacuefacio</a>.</div>\r\n","<div class=\"hw\">vacuēfaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[vacuus/facio]</div><div class=\"def\"><num>①</num> (ある場所を)空<SUB>から</SUB>にする, 無人にする;(中身などを)取り除く.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 廃止する.</div>\r\n","<div class=\"hw\">vacuēfactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vacuēfaciō\">vacuefacio</a>.</div>\r\n","<div class=\"hw\">vacuēfēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vacuēfaciō\">vacuefacio</a>.</div>\r\n","<div class=\"hw\">vacuō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vacuus]</div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>にする, (中身を)なくさせる.</div><div class=\"def\"><num>②</num> (ある場所を)無人にする.</div>\r\n","<div class=\"hw\">vacātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vaco]</div><div class=\"def\"><num>①</num> (義務・仕事・兵役などから)免れていること, 免役, 自由 〈+<i>gen</i>;a re〉</div><div class=\"ex\">～ <i>militiae</i> (<author>C<small>AES</small></author>)<span class=\"ext\">兵役の免除</span></div><div class=\"ex\">(+免役の理由を表わす <i>gen</i>)<i>rerum gestarum</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">(これまでの)業績に免じて与えられる休暇</span></div><div class=\"ex\"><i>a causis</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">法廷での弁護活動から(一時的に身を引いて)休息すること.</span></div><div class=\"def\"><num>②</num> 兵士が休暇をもらうために百人隊長に支払う金銭.</div>\r\n","<div class=\"hw\">vacēfierī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://vacēfīō\">vacefio</a>.</div>\r\n","<div class=\"hw\">vacēfīō</div><div class=\"pos\">-fierī, <i>intr</i></div><div class=\"ori\">[vacuus/fio]</div><div class=\"def\">空虚になる.</div>\r\n","<div class=\"hw\">vacīvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vacīvus\">vacīvus, vocīvus</a>]</div><div class=\"def\">欠如, 欠乏.</div>\r\n","<div class=\"hw\">vacīvus, vocīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vacō\">vacō</a>]</div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>の, (...の)欠乏した 〈+<i>gen</i>〉</div><div class=\"ex\">～ <i>virium</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">力の抜けた, 無力な.</span></div><div class=\"def\"><num>②</num> 余計な, むだな.</div>\r\n","<div class=\"hw\">vacīvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vacivus]</div><div class=\"def\">ゆっくりと, くつろいで.</div>\r\n","<div class=\"hw\">vacō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>である, 空虚である;空間[隙間]がある.</div><div class=\"def\"><num>②</num> 無人である, 所有者がない.</div><div class=\"def\"><num>③</num> (女性が)未婚である.</div><div class=\"def\"><num>④</num> (...を)欠いている, (...から)免れている[自由である] 〈(a)re〉</div><div class=\"ex\"><i>domus igne vacat</i> (<author>O<small>V</small></author>)<span class=\"ext\">その家には火の気がない</span></div><div class=\"ex\"><i>a metu ac periculis vacare</i> (<author>L<small>IV</small></author>)<span class=\"ext\">恐怖と危険を免れている.</span></div><div class=\"def\"><num>⑤</num> 暇である, (...に)ふり向ける時間[ゆとり]がある 〈+<i>dat</i>〉</div><div class=\"ex\"><i>philosophiae semper vaco</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は哲学に専念している.</span></div><div class=\"def\"><num>⑥</num> (<i>impers</i>)余地[機会]がある 〈+<i>inf</i>〉</div><div class=\"ex\"><i>tibi vacat me excipere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなたには私を受け入れる余地がある.</span></div>\r\n","<div class=\"hw\">Vacūna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vacuus]</div><div class=\"def\">ウァクーナ《Sabini 族の女神;その職能等は不明》.</div>\r\n","<div class=\"hw\">Vacūnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Vacuna の.</div>\r\n","<div class=\"hw\">Vada<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウァダ《Gallia Belgica の町》.</div><hr><div class=\"hw\">Vada<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">ウァダ《 (1) Liguria の港町;Vada Sabatia とも呼ばれた;現 Vado Ligure.(2) Etruria の Pisae 南方の港町;Vada Volaterrana と呼ばれることが多い;現 Torre di Vado》.</div>\r\n","<div class=\"hw\">Vadimōnis lacus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">ウァディモーニス湖《Etruria の小湖;Ameria の南西にある;現 Laghetto di Bassano》.</div>\r\n","<div class=\"hw\">vadimōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vas<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 被告が所定の日時に出廷する旨の誓約(書);出廷, 法廷への召喚</div><div class=\"ex\">～ <i>facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">出廷誓約書を作成する</span></div><div class=\"ex\">～ <i>promittere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">出廷を保証する</span></div><div class=\"ex\">～ <i>sistere [obire</i>] =<i>ad ～ venire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">所定の日時に出廷する.</span></div><div class=\"def\"><num>②</num> 保釈(金).</div><div class=\"def\"><num>③</num> 契約(の履行), 約束(の実行).</div>\r\n","<div class=\"hw\">vador</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[vas<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (相手側から)所定の日時の出廷を担保する保証(金)を受け取る;法廷に召喚する</div><div class=\"ex\"><i>tot vadibus accusator vadatus est reum</i> (<author>L<small>IV</small></author>)<span class=\"ext\">その人数の保証人がそろうと告発者は被告を保釈させた</span></div><div class=\"ex\">(<i>pp</i> を名詞的に用いて)<i>vadato respondere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">被告の出廷を保証させた者(=原告)に答弁する.</span></div><div class=\"def\"><num>②</num> (<i>pass</i> の意味で)束縛される.</div>\r\n","<div class=\"hw\">vadum</div><div class=\"pos\">-ī, <i>n</i>, <B>vadus</B> -ī, <i>m</i></div><div class=\"def\"><num>①</num> 徒渉できる場所, 浅瀬;安全な(または危険な)場所.</div><div class=\"def\"><num>②</num> (川・海・井戸の)底.</div><div class=\"def\"><num>③</num> 《詩》(<i>pl</i>)大量の水(=大海・大河).</div>\r\n","<div class=\"hw\">vadātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vador]</div><div class=\"def\"><num>①</num> 束縛された.</div><div class=\"def\"><num>②</num> 捧げられた.</div>\r\n","<div class=\"hw\">vadō<SUP>2</SUP></div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[vadum]</div><div class=\"def\">浅瀬を渡る, 徒渉する.</div>\r\n","<div class=\"hw\">vadōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vadum\">vadum</a>]</div><div class=\"def\">徒渉できる, 浅瀬の多い.</div>\r\n","<div class=\"hw\">vae<SUP>1</SUP></div><div class=\"pos\"><i>int</i></div><div class=\"def\">(悲嘆・苦痛・恐怖を表わす)ああ(悲しいかな), 災いなるかな 〈+<i>dat</i>〉</div><div class=\"ex\">～ <i>victis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">敗者どもに災いあれ《前390年, Allia 川の戦いでローマ軍を破ったガリア人の指導者 Brennus のことばとされる》.</span></div>\r\n","<div class=\"hw\">vae-</div><div class=\"pos\"><i>pref</i></div><div class=\"def\">=<a href=\"entry://vē-\">ve-</a>.</div>\r\n","<div class=\"hw\">vaesān-</div><div class=\"def\">⇒vesan-.</div>\r\n","<div class=\"hw\">vafellus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://vafer\">vafer</a>]</div><div class=\"def\">こずるい.</div>\r\n","<div class=\"hw\">vafer</div><div class=\"pos\">-fra -frum, <i>adj</i></div><div class=\"def\">巧妙な, 狡猾な, 悪賢い.</div>\r\n","<div class=\"hw\">vafritia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vafer]</div><div class=\"def\">狡猾, 悪賢さ.</div>\r\n","<div class=\"hw\">vafrāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://vafer\">vafer</a>]</div><div class=\"def\">奸計, 策略.</div>\r\n","<div class=\"hw\">vafrē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vafer]</div><div class=\"def\">策略を用いて, 狡猾に.</div>\r\n","<div class=\"hw\">Vaga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウァガ《 (1) Africa の Byzacium 地方の町.(2) Numidia の町;現 Bajah》.</div>\r\n","<div class=\"hw\">vagabundus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vagor<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 放浪する, さすらいの.</div><div class=\"def\"><num>②</num> (炎が)広がってゆく.</div>\r\n","<div class=\"hw\">Vagensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Vaga (1)  (2) の.</div><div class=\"hw2\"><b>Vagensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Vaga (2) の住民.</div>\r\n","<div class=\"hw\">Vagia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウァギア《Lusitania の川;現 Vouga》.</div>\r\n","<div class=\"hw\">vagor<SUP>1</SUP></div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[vagus]</div><div class=\"def\"><num>①</num> さまよう, 放浪する, 動き[飛び]回る.</div><div class=\"def\"><num>②</num> (天体が)動く</div><div class=\"ex\"><i>stella vagantes</i> (<author>A<small>PUL</small></author>)<span class=\"ext\">惑星.</span></div><div class=\"def\"><num>③</num> (船・船乗りが)巡航する.</div><div class=\"def\"><num>④</num> 広まる, 広く行きわたる.</div><div class=\"def\"><num>⑤</num> 不安定である;変動[変化]する.</div><div class=\"def\"><num>⑥</num> (演説・文章が)散漫である;本題を逸脱する.</div>\r\n","<div class=\"hw\">vagulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://vagus\">vagus<SUP>1</SUP></a>]</div><div class=\"def\">さまよう.</div>\r\n","<div class=\"hw\">vagus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> vacillo]</div><div class=\"def\"><num>①</num> さまよう, うろつき回る.</div><div class=\"def\"><num>②</num> 移動する, 動く</div><div class=\"ex\"><i>vagi crines</i> (<author>O<small>V</small></author>)<span class=\"ext\">乱れ髪.</span></div><div class=\"def\"><num>③</num> 不安定な, ぐらつく;気まぐれな.</div><div class=\"def\"><num>④</num> 散漫な, 冗長な;回りくどい.</div><div class=\"def\"><num>⑤</num> 不明確な, 漠然とした</div><div class=\"ex\">～ <i>rumor</i> (<author>T<small>AC</small></author>)<span class=\"ext\">あいまいな噂.</span></div><hr><div class=\"hw\">vagus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\"><num>①</num> (中世の)さすらい人《詩人・楽人・学生・聖職者など》.</div><div class=\"def\"><num>②</num> 〘解〙迷走神経(=<a href=\"entry://nervus\">nervus vagus</a>).</div>\r\n","<div class=\"hw\">vagātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vagor<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 放浪, さすらい.</div><div class=\"def\"><num>②</num> 変化.</div>\r\n","<div class=\"hw\">vagātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vagor<SUP>1</SUP>]</div><div class=\"def\">放浪, さすらい.</div>\r\n","<div class=\"hw\">vagē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vagus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> あちらこちらへ.</div><div class=\"def\"><num>②</num> 雑然と, でたらめに.</div>\r\n","<div class=\"hw\">vagō</div><div class=\"pos\">-āre -āvī, <i>intr</i></div><div class=\"def\">=<a href=\"entry://vagor\">vagor<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Vahalis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ウァハリス《Rhenus 川の河口近くで南側に分かれる支流;現 Waal》.</div>\r\n","<div class=\"hw\">valdē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[validus]</div><div class=\"def\"><num>①</num> 力強く;大声で.</div><div class=\"def\"><num>②</num> 大いに, 著しく.</div><div class=\"def\"><num>③</num> (強い肯定の答えとして)全く[確かに](そうだ).</div>\r\n","<div class=\"hw\">vale</div><div class=\"pos\">2 <i>sg impr</i></div><div class=\"ori\">[valeo]</div><div class=\"def\">(別れの挨拶)お元気で, さようなら</div><div class=\"ex\"><i>supremum</i> ～ <i>dicere</i> (<author>O<small>V</small></author>)<span class=\"ext\">最後の 「さようなら」 を言う.</span></div>\r\n","<div class=\"hw\">valedictus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://valedīcō\">valedico</a>.</div>\r\n","<div class=\"hw\">valedixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://valedīcō\">valedico</a>.</div>\r\n","<div class=\"hw\">valedīcō</div><div class=\"pos\">-ere -dixī -dictum, <i>intr</i></div><div class=\"ori\">[↑<a href=\"entry://vale\">vale</a>/dico<SUP>2</SUP>]</div><div class=\"def\">さようならを言う, 別れを告げる 〈alci〉.</div>\r\n","<div class=\"hw\">valefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://valefaciō\">valefacio</a>.</div>\r\n","<div class=\"hw\">valefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>intr</i></div><div class=\"def\">=<a href=\"entry://valedīcō\">valedico</a>.</div>\r\n","<div class=\"hw\">valefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://valefaciō\">valefacio</a>.</div>\r\n","<div class=\"hw\">valens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[valeo]</div><div class=\"def\"><num>①</num> 力の強い, 頑丈な.</div><div class=\"def\"><num>②</num> 健康な, 壮健な.</div><div class=\"def\"><num>③</num> 影響力[勢力]のある, 有力な.</div><div class=\"def\"><num>④</num> 効果的な, 効き目のある.</div>\r\n","<div class=\"hw\">Valens</div><div class=\"pos\">-tis, <i>m</i></div><div class=\"def\">ウァレンス《 (1) 〘神話〙一説で Mercurius の父.(2) <SUP>◇</SUP><i>Flavius</i> ～, ローマ皇帝(在位364‐378)》.</div>\r\n","<div class=\"hw\">valenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[valens]</div><div class=\"def\"><num>①</num> 勢いよく, しっかりと.</div><div class=\"def\"><num>②</num> (演説が)表現力豊かに, 力強く.</div>\r\n","<div class=\"hw\">valentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[valens]</div><div class=\"def\"><num>①</num> 体力.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 勇気.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 能力, 才能.</div>\r\n","<div class=\"hw\">Valentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウァレンティア《 (1) Hispania Tarraconensis の町;現 Valencia.(2) Gallia Narbonensis の町;現 Valence.(3) Sardinia 島の町.(4) Bruttii の町;Vibo Valentia とも呼ばれた;現 Monteleone.(5) Mauritania の町.(6) <SUP>◇</SUP> 現スコットランドの南部地域.(7) <SUP>◇</SUP>(一説に)ローマの古名》.</div>\r\n","<div class=\"hw\">valentulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[valens]</div><div class=\"def\">(かなり)力が強い, たくましい.</div>\r\n","<div class=\"hw\">Valentīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↑<a href=\"entry://Valentia\">Valentia</a>]</div><div class=\"def\">Valentia (3)  (4) の住民.</div>\r\n","<div class=\"hw\">Valerius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァレリウス《ローマ人の氏族名;特に (1) <i>P</i>. ～, Brutus と協力して第7代の王 Tarquinius Superbus を追放した;共和政成立時の consul の一人(前509).(2) ～ <i>Antias</i>, 前1世紀の歴史家.(3) ～ <i>Maximus</i>, Tiberius 帝時代の著述家;<i>Facta et Dicta Memorabilia</i> 「故事著聞集」(9巻)を執筆した.(4) <i>C. ～ Flaccus</i>, 叙事詩人(前90頃没);<i>Argonautica</i> 「アルゴー船遠征譚」(8巻)を著わした》.</div>\r\n","<div class=\"hw\">Valeriānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Valerius の.</div>\r\n","<div class=\"hw\">valescō</div><div class=\"pos\">-ere -luī, <i>intr inch</i></div><div class=\"ori\">[valeo]</div><div class=\"def\"><num>①</num> 健康を回復する.</div><div class=\"def\"><num>②</num> 勢いを増す, 強大になる.</div>\r\n","<div class=\"hw\">valeō</div><div class=\"pos\">-ēre -luī -litum, <i>intr</i></div><div class=\"def\"><num>①</num> 体力がある, よい体格をしている.</div><div class=\"def\"><num>②</num> 健康[壮健]である</div><div class=\"ex\"><i>melius [minus] valere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">体調が戻っている[すぐれない]</span></div><div class=\"ex\">(手紙の書き出し)<i>si vales</i>, <i>bene est</i>(S. V. B. E. とも略記)(<author>C<small>IC</small></author>)<span class=\"ext\">あなたがお元気ならなによりです</span></div><div class=\"ex\"><i>ego(quoque)</i> ～(E. (Q.) V. とも略記)(<author>C<small>IC</small></author>)<span class=\"ext\">私は[も]元気です</span></div><div class=\"ex\">(手紙の結び)<i>vale</i> (<author>C<small>IC</small></author>)<span class=\"ext\">お元気で</span></div><div class=\"ex\">(一般に別れの挨拶)<span class=\"ext\">⇒ <a href=\"entry://vale\">vale</a>, <a href=\"entry://valēte\">valete</a></span></div><div class=\"def\">(<i>subj</i> で軽蔑・拒絶を表わす)行ってしまえ</div><div class=\"ex\"><i>si talis est deus</i>, <i>valeat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">もし神がそのような存在であるなら, 神なんかどうでもいい[知るものか].</span></div><div class=\"def\"><num>③</num> (政治的・軍事的に)勢力がある, 有力である 〈re〉</div><div class=\"ex\">(multum, plus, plurimum などと)<i>res publica minus valet</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">国家が弱体化している</span></div><div class=\"ex\"><i>equitate valere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">騎兵でまさっている</span></div><div class=\"ex\"><i>adversus Philippum valent Romani</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ローマ軍は Philippus に対して優勢である.</span></div><div class=\"def\"><num>④</num> (あること[物]に)力がある, 役立つ, 効果がある 〈ad alqd;+<i>inf</i>〉</div><div class=\"ex\"><i>alii velocitate ad cursum valent</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人々は足が速くて競走に強い</span></div><div class=\"ex\"><i>nec valuere manūs infixum educere telum</i> (<author>O<small>V</small></author>)<span class=\"ext\">両腕は突き刺さった剣を引き抜くことができなかった.</span></div><div class=\"def\"><num>⑤</num> (...に)相当する, (...の)値打ちがある 〈pro re〉</div><div class=\"ex\"><i>pro argenteis decem aureus unus valet</i> (<author>L<small>IV</small></author>)<span class=\"ext\">金貨1枚は銀貨10枚分にあたる.</span></div><div class=\"def\"><num>⑥</num> 通用する, 妥当する</div><div class=\"ex\"><i>definitio in omnes valet</i> (<author>C<small>IC</small></author>)<span class=\"ext\">その定義は万人にあてはまる.</span></div><div class=\"def\"><num>⑦</num> (語が)意味する.</div>\r\n","<div class=\"hw\">valgiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[valgus]</div><div class=\"def\">唇を突き出して.</div>\r\n","<div class=\"hw\">Valgius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァルギウス《ローマ人の氏族名;特に <i>C. ～ Rufus</i>, Augustus 帝時代の詩人》.</div>\r\n","<div class=\"hw\">valgus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">外反膝<SUB>しつ</SUB>の, X 脚の.</div>\r\n","<div class=\"hw\">validitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[validus]</div><div class=\"def\"><num>①</num> 体力.</div><div class=\"def\"><num>②</num> 頑丈なこと, 強固.</div>\r\n","<div class=\"hw\">validus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[valeo]</div><div class=\"def\"><num>①</num> 強い, たくましい;丈夫な.</div><div class=\"def\"><num>②</num> 健康[強壮]な.</div><div class=\"def\"><num>③</num> 激しい, 猛烈な</div><div class=\"ex\"><i>validā cupidine captus</i> (<author>O<small>V</small></author>)<span class=\"ext\">激しい恋心のとりことなって.</span></div><div class=\"def\"><num>④</num> 堅固[強固]な.</div><div class=\"def\"><num>⑤</num> 有効な, 効果的な.</div><div class=\"def\"><num>⑥</num> 影響力のある, 重きをなす 〈+<i>abl</i>〉</div><div class=\"ex\"><i>ingenium sapientiā validum</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">洞察力において卓越した天性.</span></div><div class=\"def\"><num>⑦</num> (演説が)表現力豊かな, 力強い.</div>\r\n","<div class=\"hw\">validē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[validus]</div><div class=\"def\"><num>①</num> 強力に, 精力的に.</div><div class=\"def\"><num>②</num> 大いに, 激しく.</div><div class=\"def\"><num>③</num> (話し方・表現が)力強く.</div><div class=\"def\"><num>④</num> (相手の意見に同意して)全く[確かに](そうだ).</div>\r\n","<div class=\"hw\">validō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://validus\">validus</a>]</div><div class=\"def\">(以前のように)強くする.</div>\r\n","<div class=\"hw\">valitūrus</div><div class=\"pos\">-a -um, <i>fut p</i></div><div class=\"def\">⇒<a href=\"entry://valeō\">valeo</a>.</div>\r\n","<div class=\"hw\">vallestris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vallēs\">vallēs, vallis</a>]</div><div class=\"def\">谷にある.</div>\r\n","<div class=\"hw\">vallicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[valles]</div><div class=\"def\"><num>①</num> 小さな谷.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 溝, 筋目;くぼみ.</div>\r\n","<div class=\"hw\">vallis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://vallēs\">valles</a>.</div>\r\n","<div class=\"hw\">vallum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 防柵;堡塁<SUB>ほうるい</SUB></div><div class=\"ex\"><i>aggerem ac ～ exstruere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">土塁を築き防柵を立てる</span></div><div class=\"ex\"><i>vallo fossāque munire</i> (<author>C<small>AES</small></author>)<span class=\"ext\">堡塁と壕で守りを固める.</span></div><div class=\"def\"><num>②</num> 守り, 防御(施設)</div><div class=\"ex\"><i>spica munitur vallo aristarum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(麦の)穂は芒<SUB>のぎ</SUB>で守りを固めている.</span></div><hr><div class=\"hw\">vallum<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://vallus\">vallus<SUP>2</SUP> 1</a>.</div>\r\n","<div class=\"hw\">vallus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> (ブドウの)支柱, 添え木.</div><div class=\"def\"><num>②</num> (防柵用の)杭<SUB>くい</SUB>;防柵;堡塁.</div><div class=\"def\"><num>③</num> 《詩》(櫛<SUB>くし</SUB>の)歯.</div><div class=\"def\"><num>④</num> (Gallia で用いられた)刈取り機の一種《歯がついている》.</div><hr><div class=\"hw\">vallus<SUP>2</SUP></div><div class=\"pos\">-ī [-ūs], <i>f dim</i></div><div class=\"ori\">[vannus]</div><div class=\"def\"><num>①</num> (小さな)唐箕<SUB>とうみ</SUB>.</div><div class=\"def\"><num>②</num> 半円筒状の溝瓦.</div>\r\n","<div class=\"hw\">vallāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vallum<SUP>1</SUP>]</div><div class=\"def\">堡塁の</div><div class=\"ex\"><i>corona ～</i> (<author>L<small>IV</small></author>)<span class=\"ext\">敵陣の堡塁を真っ先に乗り越えた兵士に与えられる冠.</span></div>\r\n","<div class=\"hw\">vallātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vallo]</div><div class=\"def\"><num>①</num> 防御柵.</div><div class=\"def\"><num>②</num> 防護.</div>\r\n","<div class=\"hw\">vallātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vallō\">vallo</a>.</div>\r\n","<div class=\"hw\">vallēcula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://vallēs\">vallēs, vallis</a>]</div><div class=\"def\"><num>①</num> 小さな谷.</div><div class=\"def\"><num>②</num> 〘解〙谷.</div><div class=\"def\"><num>③</num> 〘植〙果谷<SUB>かこく</SUB>.</div>\r\n","<div class=\"hw\">vallēs, vallis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 谷, 渓谷.</div><div class=\"def\"><num>②</num> くぼみ.</div>\r\n","<div class=\"hw\">vallō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vallum\">vallum<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 柵[堡塁]をめぐらして防備を施す.</div><div class=\"def\"><num>②</num> 防護する, 守る.</div>\r\n","<div class=\"hw\">valor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"def\"><num>①</num> 法的効力.</div><div class=\"def\"><num>②</num> 価値.</div><div class=\"def\"><num>③</num> 能力, 才能.</div>\r\n","<div class=\"hw\">valuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://valeō\">valeo</a>, <a href=\"entry://valescō\">valesco</a>.</div>\r\n","<div class=\"hw\">valvae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">(<i>sg</i> valva はまれ)両開き[観音<SUB>かんのん</SUB>開き]の戸.</div>\r\n","<div class=\"hw\">valvolī</div><div class=\"pos\">-orum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://valvulae\">valvulae</a>.</div>\r\n","<div class=\"hw\">valvulae</div><div class=\"pos\">-ārum, <i>f pl dim</i></div><div class=\"ori\">[valvae]</div><div class=\"def\">〘植〙(ソラマメのなど)莢<SUB>さや</SUB>.</div>\r\n","<div class=\"hw\">valvātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://valvae\">valvae</a>]</div><div class=\"def\">両開き戸の付いた;両開きの.</div>\r\n","<div class=\"hw\">valēn</div><div class=\"def\">(あなたは)お元気ですか(=valesne;⇒ <a href=\"entry://valeō\">valeo</a>, <a href=\"entry://-ne\">-ne</a>).</div>\r\n","<div class=\"hw\">valēte</div><div class=\"pos\">2 <i>pl impr</i></div><div class=\"ori\">[valeo]</div><div class=\"def\">(別れの挨拶)諸君[皆さん]ご機嫌よう, さようなら.</div>\r\n","<div class=\"hw\">valētūdinārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://valētūdinārius\">valētūdinārius</a>]</div><div class=\"def\">病院, 診療所.</div>\r\n","<div class=\"hw\">valētūdinārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://valētūdō\">valētūdō, valītūdō</a>]</div><div class=\"def\">病気の, 病床にある.</div>\r\n","<div class=\"hw\">valētūdō, valītūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[valeo]</div><div class=\"def\"><num>①</num> 健康(状態).</div><div class=\"def\"><num>②</num> (良い)健康, 壮健.</div><div class=\"def\"><num>③</num> 不健康, 病気.</div>\r\n","<div class=\"hw\">valītūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\">=<a href=\"entry://valētūdō\">valetudo</a>.</div>\r\n","<div class=\"hw\">Vandalī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">ウァンダリー, <SUP>∥</SUP>バンダル族《Tacitus の時代には Germania 北部にいた一部族(1世紀の文献では Vandil(i)i);5世紀にガリア・ヒスパニア・北アフリカに侵攻した》.</div>\r\n","<div class=\"hw\">Vandil(i)ī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">⇒<a href=\"entry://Vandalī\">Vandali</a>.</div>\r\n","<div class=\"hw\">vanga</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">鋤<SUB>すき</SUB>, つるはし.</div>\r\n","<div class=\"hw\">Vangionēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ウァンギオネース《Rhenus 川の中流域, 現 Worms あたりにいた Germania の一部族》.</div>\r\n","<div class=\"hw\">vannus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">唐箕<SUB>とうみ</SUB>《穀物から籾<SUB>もみ</SUB>などを風で吹き分ける農具》.</div>\r\n","<div class=\"hw\">vannō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vannus\">vannus</a>]</div><div class=\"def\">(穀物を)唐箕にかける, あおぎ分ける.</div>\r\n","<div class=\"hw\">vapidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vapor\">vapor</a>]</div><div class=\"def\"><num>①</num> (ぶどう酒が)気の抜けた.</div><div class=\"def\"><num>②</num> 腐敗した;だめになった.</div>\r\n","<div class=\"hw\">vapidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://vapidus\">vapidus</a>]</div><div class=\"def\">(気の抜けたぶどう酒のように)生気なく</div><div class=\"ex\"><i>～ se habere</i> (<author>S<small>UET</small></author>)<span class=\"ext\">気分がすっきりしない《Augustus 帝が male se habere の代わりに用いたという語句》.</span></div>\r\n","<div class=\"hw\">vapor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\"><num>①</num> 蒸気, 蒸発気.</div><div class=\"def\"><num>②</num> (太陽などの)熱, 熱気;(病気による)発熱.</div><div class=\"def\"><num>③</num> 火炎.</div><div class=\"def\"><num>④</num> (恋の)炎, 情熱.</div>\r\n","<div class=\"hw\">vappa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 気の抜けたぶどう酒.</div><div class=\"def\"><num>②</num> (<i>m</i>)取柄のない人, 役立たず.</div>\r\n","<div class=\"hw\">vapōrus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vapor]</div><div class=\"def\"><num>①</num> 芳香を放つ.</div><div class=\"def\"><num>②</num> 熱い.</div>\r\n","<div class=\"hw\">vapōrālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vapor\">vapor</a>]</div><div class=\"def\">蒸気のような.</div>\r\n","<div class=\"hw\">vapōrāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vapōrālis\">vapōrālis</a>]</div><div class=\"def\">蒸気のように.</div>\r\n","<div class=\"hw\">vapōrārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vaporo]</div><div class=\"def\">(浴場の)蒸気管.</div>\r\n","<div class=\"hw\">vapōrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vaporo]</div><div class=\"def\"><num>①</num> 蒸発.</div><div class=\"def\"><num>②</num> 蒸気</div><div class=\"ex\"><i>balnearum ～ </i>(<author>P<small>LIN</small></author>)<span class=\"ext\">蒸し風呂.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 温罨法<SUB>あんぽう</SUB>, 温湿布.</div>\r\n","<div class=\"hw\">vapōrātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vapōrō\">vaporo</a>.</div>\r\n","<div class=\"hw\">vapōrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[vapor]</div><div class=\"def\"><num>①</num> 蒸気を発する, 蒸発する;霧散する.</div><div class=\"def\"><num>②</num> 蒸気で満たす[いっぱいにする];(治療のため)蒸気に当てる.</div><div class=\"def\"><num>③</num> 暖める, 熱する.</div>\r\n","<div class=\"hw\">vapōrōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vapor]</div><div class=\"def\">湯気[熱気]に満ちた.</div>\r\n","<div class=\"hw\">vapōs</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">《古形》=<a href=\"entry://vapor\">vapor</a>.</div>\r\n","<div class=\"hw\">Varagrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Veragrī\">Veragri</a>.</div>\r\n","<div class=\"hw\">Vardaeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウァルダエイー《Dalmatia の Narona 近辺にいた一部族;Bardaei とも呼ばれた》.</div>\r\n","<div class=\"hw\">Vardaicus, Bar-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vardaei 族の.</div>\r\n","<div class=\"hw\">Varguntēius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァルグンテイユス《ローマの元老院議員;Catilina の陰謀に荷担した》.</div>\r\n","<div class=\"hw\">vargus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">浮浪者.</div>\r\n","<div class=\"hw\">varia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[varius]</div><div class=\"def\"><num>①</num> 〘動〙ヒョウ(豹).</div><div class=\"def\"><num>②</num> 〘鳥〙カササギの一種.</div>\r\n","<div class=\"hw\">Varia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウァリア《 (1) Anio 河畔にあった Aequi 族の町;現 Vicovaro.(2) Apulia の町.(3) Hispania Tarraconensis の町;現 Varea》.</div>\r\n","<div class=\"hw\">varians</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[vario]</div><div class=\"def\"><num>①</num> 色とりどりの.</div><div class=\"def\"><num>②</num> 種々の, さまざまの.</div>\r\n","<div class=\"hw\">variantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://varians\">varians</a>]</div><div class=\"def\">多種, 多様性.</div>\r\n","<div class=\"hw\">varicella</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙水痘, 水疱瘡<SUB>ぼうそう</SUB>.</div>\r\n","<div class=\"hw\">varicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[varix]</div><div class=\"def\">(小さな)静脈瘤.</div>\r\n","<div class=\"hw\">varicōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[varix]</div><div class=\"def\">〘病〙静脈瘤のできた.</div>\r\n","<div class=\"hw\">variegō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[varius/ago]</div><div class=\"def\"><num>①</num> さまざまな色にする[で飾る].</div><div class=\"def\"><num>②</num> 色とりどりである, さまざまな色で飾られる.</div>\r\n","<div class=\"hw\">varietās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[varius]</div><div class=\"def\"><num>①</num> 二つ(以上)の色がある[現われている]こと.</div><div class=\"def\"><num>②</num> 雑多, 多種多様, 変化に富むこと;変種.</div><div class=\"def\"><num>③</num> 栄枯盛衰, 浮き沈み.</div><div class=\"def\"><num>④</num> (意見の)相違, 不一致;矛盾.</div><div class=\"def\"><num>⑤</num> 不定見, 気まぐれ.</div>\r\n","<div class=\"hw\">variola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://varius\">varius</a>]</div><div class=\"def\">〘病〙天然痘, 痘瘡<SUB>とうそう</SUB>.</div>\r\n","<div class=\"hw\">varius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> さまざまな色の;まだらの, 斑点のある.</div><div class=\"def\"><num>②</num> 種々の, 雑多な;変化に富む.</div><div class=\"def\"><num>③</num> 異なった, 一致しない;ゆれ動く</div><div class=\"ex\"><i>quales sint dii varium est</i>, <i>esse nemo negat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">神々がどのようなものかについて意見は分かれるが, その存在を否定する者はない.</span></div><div class=\"def\"><num>④</num> 不定見の, 移り気な;信頼できない</div><div class=\"ex\"><i>varium et mutabile semper femina</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">女とはいつも気まぐれで変わりやすいもの.</span></div>\r\n","<div class=\"hw\">Varius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァリウス《ローマ人の氏族名;特に (1) <i>Q. ～ Hybrida</i>, 護民官(前90).(2) <i>L. ～ Rufus</i>, Augustus 帝時代の悲劇詩人;Plotius Tucca と協力して Vergilius の遺稿 <i>Aeneis</i> を公刊したという》.</div>\r\n","<div class=\"hw\">varix</div><div class=\"pos\">-icis, <i>m</i>, <i>f</i></div><div class=\"ori\">[varus<SUP>2</SUP>]</div><div class=\"def\">〘病〙静脈瘤.</div>\r\n","<div class=\"hw\">variābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vario]</div><div class=\"def\">変化しやすい.</div>\r\n","<div class=\"hw\">variānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[varius]</div><div class=\"def\">さまざまな色の</div><div class=\"ex\"><i>uva variana</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ブドウの一種.</span></div>\r\n","<div class=\"hw\">variātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">いろいろに, さまざまに.</div>\r\n","<div class=\"hw\">variātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vario]</div><div class=\"def\"><num>①</num> 変化をつけること.</div><div class=\"def\"><num>②</num> 多様性</div><div class=\"ex\"><i>sine variatione ullā dixerunt</i> (<author>L<small>IV</small></author>)<span class=\"ext\">異口同音に言った.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 心境の変化.</div>\r\n","<div class=\"hw\">variātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vario]</div><div class=\"def\">縁取り師, 刺繍をする人.</div>\r\n","<div class=\"hw\">variātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vario]</div><div class=\"def\">変化に富む.</div>\r\n","<div class=\"hw\">variē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[varius]</div><div class=\"def\"><num>①</num> 雑多な色に.</div><div class=\"def\"><num>②</num> さまざまに, 多様に.</div>\r\n","<div class=\"hw\">variō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[varius]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> さまざまな色にする[で飾る].</div><div class=\"def\"><num>②</num> 変化をつける, 多様にする;変形させる.</div><div class=\"def\"><num>③</num> (意見などを)分かれさせる;変動させる</div><div class=\"ex\"><i>variante fortunā</i> (<author>L<small>IV</small></author>)<span class=\"ext\">武運の浮き沈みがあって</span></div><div class=\"ex\">(impers pass)<i>cum sententiis variaretur</i> (<author>L<small>IV</small></author>)<span class=\"ext\">いろんな意見があったので.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> さまざまな色になる[変わる].</div><div class=\"def\"><num>②</num> 変化する, 変化が生じる.</div><div class=\"def\"><num>③</num> (意見などが)分かれる, (心情が)ゆれ動く;変動する</div><div class=\"ex\"><i>fama variat</i> (<author>L<small>IV</small></author>)<span class=\"ext\">さまざまの噂がとび交う.</span></div>\r\n","<div class=\"hw\">Varrō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ウァッロー《Terentia 氏族に属する家名;特に (1) <i>C. Terentius</i> ～, 執政官として Cannae の戦いを指揮したが Hannibal に敗れた(前216).(2) <i>M. Terentius</i> ～, Cicero と同時代の学者(前116‐27);<i>De Re Rustica</i> 「農場経営論」, <i>De Lingua Latina</i> 「ラテン語論」 などを著わした.(3) <i>P. Terentius ～ Atacinus</i>, Augustus 帝時代の詩人》.</div>\r\n","<div class=\"hw\">Varrōniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Varro の</div><div class=\"ex\"><i>fabulae Varronianae</i> (<author>G<small>ELL</small></author>)<span class=\"ext\">Varro (2) が真作として列挙した Terentius の21篇の喜劇.</span></div>\r\n","<div class=\"hw\">varulus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[varus<SUP>2</SUP>]</div><div class=\"def\">〘病〙ものもらい, 麦粒腫.</div>\r\n","<div class=\"hw\">varus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> (内側に)曲がった[湾曲した].</div><div class=\"def\"><num>②</num> 内反膝<SUB>しつ</SUB>の, O 脚の, がにまたの.</div><div class=\"def\"><num>③</num> 異なる, 対照的な.</div><hr><div class=\"hw\">varus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">吹き出物, にきび.</div>\r\n","<div class=\"hw\">Varīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウァリーニー《Germania 北部, 現バルト海近くにいた一部族》.</div>\r\n","<div class=\"hw\">vas<SUP>1</SUP></div><div class=\"pos\">vadis, <i>m</i></div><div class=\"def\"><num>①</num> (被告出廷の)保証人</div><div class=\"ex\"><i>～ factus est Damon ejus sistendi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Damon は友の出頭の保証人となった.</span></div><div class=\"def\"><num>②</num> 保証, 抵当.</div>\r\n","<div class=\"hw\">vascellum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[vasculum]</div><div class=\"def\">(小さな)骨壺.</div>\r\n","<div class=\"hw\">vasciō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://vascellum\">vascellum</a>.</div>\r\n","<div class=\"hw\">Vasconēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ウァスコネース《Hispania Tarraconensis の, 現 Navarra 地方にいた一部族;Basque 人の祖》.</div>\r\n","<div class=\"hw\">vasculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vas<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (小さな)容器.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(小さな)蜂の巣.</div><div class=\"def\"><num>③</num> 〘植〙(種子の入った)殻, 蒴<SUB>さく</SUB>.</div><div class=\"def\"><num>④</num> 陰茎.</div>\r\n","<div class=\"hw\">vasculārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://vasculum\">vasculum</a>]</div><div class=\"def\">(金・銀の)容器製造[販売]人.</div>\r\n","<div class=\"hw\">vascus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">曲がった.</div>\r\n","<div class=\"hw\">vaspicētum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">深い茂み.</div>\r\n","<div class=\"hw\">vassallus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">封建家臣.</div>\r\n","<div class=\"hw\">vastescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[vastus]</div><div class=\"def\">荒廃する.</div>\r\n","<div class=\"hw\">vastificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vastus/facio]</div><div class=\"def\">荒廃させる.</div>\r\n","<div class=\"hw\">vastitiēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"ori\">[vastus]</div><div class=\"def\">破滅(状態).</div>\r\n","<div class=\"hw\">vastitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vastus]</div><div class=\"def\"><num>①</num> 荒廃(状態), 破壊.</div><div class=\"def\"><num>②</num> 荒野;砂漠.</div><div class=\"def\"><num>③</num> 巨大, 広大;強烈.</div>\r\n","<div class=\"hw\">vastitō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr freq</i></div><div class=\"ori\">[vasto]</div><div class=\"def\">(繰り返して)荒廃させる.</div>\r\n","<div class=\"hw\">vastitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[vastus]</div><div class=\"def\"><num>①</num> (耕地の)荒廃(状態);(人が)うすよごれていること.</div><div class=\"def\"><num>②</num> 巨大.</div>\r\n","<div class=\"hw\">vastulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[vastus]</div><div class=\"def\">いささか大きめの.</div>\r\n","<div class=\"hw\">vastus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>っぽの, 無人の</div><div class=\"ex\"><i>urbs a defensoribus vasta</i> (<author>L<small>IV</small></author>)<span class=\"ext\">守備兵がいなくなった町.</span></div><div class=\"def\"><num>②</num> 荒廃した, 破壊された.</div><div class=\"def\"><num>③</num> 途方もなく大きな, 果てしのない</div><div class=\"ex\"><i>vastum mare</i> (<author>C<small>AES</small></author>)<span class=\"ext\">茫々<SUB>ぼうぼう</SUB>たる大海原.</span></div><div class=\"def\"><num>④</num> 粗野な, 見苦しい, 不快な.</div><div class=\"def\"><num>⑤</num> 飽くことを知らない.</div>\r\n","<div class=\"hw\">vastuōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vastus\">vastus</a>]</div><div class=\"def\">無人の, 荒涼とした.</div>\r\n","<div class=\"hw\">vastābundus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vasto]</div><div class=\"def\">荒らし回る.</div>\r\n","<div class=\"hw\">vastātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vasto]</div><div class=\"def\">荒廃させること, 略奪.</div>\r\n","<div class=\"hw\">vastātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vasto]</div><div class=\"def\">荒廃させる者, 略奪者.</div>\r\n","<div class=\"hw\">vastātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[vastator]</div><div class=\"def\">荒廃させる者《女性》.</div>\r\n","<div class=\"hw\">vastātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vastō\">vasto</a>.</div>\r\n","<div class=\"hw\">vastātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vastātor\">vastātor</a>]</div><div class=\"def\">略奪者の.</div>\r\n","<div class=\"hw\">vastē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vastus]</div><div class=\"def\"><num>①</num> はなはだしく, 大いに.</div><div class=\"def\"><num>②</num> (発音が)粗野に, 下品に.</div>\r\n","<div class=\"hw\">vastō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vastus]</div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>にする, 無人にする</div><div class=\"ex\"><i>vastare cultoribus agros</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">農地から耕し手を奪う.</span></div><div class=\"def\"><num>②</num> 荒廃させる, 略奪する.</div><div class=\"def\"><num>③</num> (軍勢を)全滅させる.</div><div class=\"def\"><num>④</num> (人心を)すさませる.</div>\r\n","<div class=\"hw\">vatax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"def\">=<a href=\"entry://vatius\">vatius</a>.</div>\r\n","<div class=\"hw\">vatia</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[vatius]</div><div class=\"def\">外反膝 [X 脚] の男.</div>\r\n","<div class=\"hw\">vatillum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (鳥のふんをかき集める)スコップ.</div><div class=\"def\"><num>②</num> (火のついた炭・熱した金属を入れる)火桶.</div>\r\n","<div class=\"hw\">vatius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">外反膝<SUB>しつ</SUB>の, X 脚の.</div>\r\n","<div class=\"hw\">Vatīnius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァティーニウス《ローマ人の氏族名;特に (1) <i>P. ～</i>, 護民官(前59);J. Caesar の手先;Cicero に手ひどく弾劾された.(2) Nero 帝の宮廷における道化師》.</div><hr><div class=\"hw\">Vatīnius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(Vatinius<SUP>1</SUP> (2) の顔に似せて作られた)酒杯.</div>\r\n","<div class=\"hw\">Vatīniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vatinius<SUP>1</SUP> (1) の.</div>\r\n","<div class=\"hw\">vavassor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"def\">(封建制度における)陪臣<SUB>ばいしん</SUB>.</div>\r\n","<div class=\"hw\">vavatō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">人形.</div>\r\n","<div class=\"hw\">Vecilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェキリウス《Latium の山》.</div>\r\n","<div class=\"hw\">vectis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[vectigal]</div><div class=\"def\"><num>①</num> てこ;かなてこ.</div><div class=\"def\"><num>②</num> 突き棒.</div><div class=\"def\"><num>③</num> (戸の)かんぬき.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(輿<SUB>こし</SUB>の)ながえ.</div>\r\n","<div class=\"hw\">Vectis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">ウェクティス《Britannia 南岸沖の島;現 Isle of Wight》.</div>\r\n","<div class=\"hw\">vectitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://vectō\">vectō</a>]</div><div class=\"def\">(常習的に)引く, 運ぶ.</div>\r\n","<div class=\"hw\">vectiārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vectis]</div><div class=\"def\">てこを操作する者.</div>\r\n","<div class=\"hw\">vectiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[veho]</div><div class=\"def\"><num>①</num> 運搬すること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(馬・ロバなどの)乗用動物.</div>\r\n","<div class=\"hw\">vector</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[veho]</div><div class=\"def\"><num>①</num> (馬・ロバ・船などで)運ぶ人, 運搬者.</div><div class=\"def\"><num>②</num> 船客;(馬での)旅行者, 騎士.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 馬.</div>\r\n","<div class=\"hw\">vectrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>adj f</i></div><div class=\"ori\">[vector]</div><div class=\"def\">運搬する.</div>\r\n","<div class=\"hw\">vectus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vehō\">veho</a>.</div>\r\n","<div class=\"hw\">vectābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vecto]</div><div class=\"def\">運搬できる.</div>\r\n","<div class=\"hw\">vectābulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vecto]</div><div class=\"def\">運搬具[車].</div>\r\n","<div class=\"hw\">vectāculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://vectābulum\">vectabulum</a>.</div>\r\n","<div class=\"hw\">vectātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vecto]</div><div class=\"def\"><num>①</num> (乗物で)運ばれる[旅をする]こと;乗馬.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 運搬.</div>\r\n","<div class=\"hw\">vectātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vecto]</div><div class=\"def\">騎手.</div>\r\n","<div class=\"hw\">vectātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vectō\">vecto</a>.</div>\r\n","<div class=\"hw\">vectīgal</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vectīgālis\">vectīgālis</a>]</div><div class=\"def\"><num>①</num> 賦課金, 租税;関税, 通行税</div><div class=\"ex\"><i>～ pendere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">納税する</span></div><div class=\"ex\">～ <i>imponere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">課税する.</span></div><div class=\"def\"><num>②</num> (退任する総督に属州民が送る)寄付金.</div><div class=\"def\"><num>③</num> (個人の)収入, 所得.</div><div class=\"def\"><num>④</num> (被征服民に課す)年貢.</div>\r\n","<div class=\"hw\">vectīgālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vectiō\">vectiō</a>]</div><div class=\"def\"><num>①</num> 賦課金[税金]の.</div><div class=\"def\"><num>②</num> 納税する, 貢納する</div><div class=\"ex\"><i>civitas</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">進貢都市.</span></div><div class=\"def\"><num>③</num> (個人に)収入をもたらす.</div>\r\n","<div class=\"hw\">vectō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[veho]</div><div class=\"def\"><num>①</num> 運ぶ, 運搬する.</div><div class=\"def\"><num>②</num> (<i>pass</i>)運ばれる</div><div class=\"ex\"><i>vectari equis</i> (<author>O<small>V</small></author>)<span class=\"ext\">馬に乗って行く.</span></div>\r\n","<div class=\"hw\">vectōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vector\">vector</a>]</div><div class=\"def\">運搬[輸送]用の.</div>\r\n","<div class=\"hw\">vectūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[veho]</div><div class=\"def\"><num>①</num> (海・陸の)運送, 輸送;運送手段.</div><div class=\"def\"><num>②</num> 運送料, 運賃.</div>\r\n","<div class=\"hw\">vegetus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vegeo]</div><div class=\"def\"><num>①</num> 活気のある, 元気な;激しい.</div><div class=\"def\"><num>②</num> 生きいきした;鮮やかな.</div>\r\n","<div class=\"hw\">vegetābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vegeto]</div><div class=\"def\">活気づける.</div>\r\n","<div class=\"hw\">vegetāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[vegeto]</div><div class=\"def\">生命の本源, 活力.</div>\r\n","<div class=\"hw\">vegetātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vegeto]</div><div class=\"def\">活気づけること.</div>\r\n","<div class=\"hw\">vegetātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vegeto]</div><div class=\"def\">活気づける者.</div>\r\n","<div class=\"hw\">vegetātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vegetō\">vegeto</a>.</div>\r\n","<div class=\"hw\">vegetō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vegetus\">vegetus</a>]</div><div class=\"def\">活気づける, 活発にする.</div>\r\n","<div class=\"hw\">vegeō</div><div class=\"pos\">-ēre, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 活気づける, かきたてる.</div><div class=\"def\"><num>②</num> 活発である.</div>\r\n","<div class=\"hw\">vehemens, vēm-</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"def\"><num>①</num> 激しい, 猛烈な.</div><div class=\"def\"><num>②</num> 厳しい, 重大な.</div><div class=\"def\"><num>③</num> 精力的な, 力強い.</div>\r\n","<div class=\"hw\">vehementer, vēm-</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vehemens\">vehemens, vēm-</a>]</div><div class=\"def\"><num>①</num> 激しく, 猛烈に.</div><div class=\"def\"><num>②</num> 精力的に, 強力に.</div><div class=\"def\"><num>③</num> はなはだしく, 極度に.</div>\r\n","<div class=\"hw\">vehementescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr inch</i></div><div class=\"ori\">[vehemens]</div><div class=\"def\">激しくなる.</div>\r\n","<div class=\"hw\">vehementia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vehemens]</div><div class=\"def\"><num>①</num> 強烈;力強いこと.</div><div class=\"def\"><num>②</num> 熱意, 熱心.</div>\r\n","<div class=\"hw\">vehiculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[veho]</div><div class=\"def\"><num>①</num> 荷車, 馬車.</div><div class=\"def\"><num>②</num> 運搬[輸送]手段.</div><div class=\"def\"><num>③</num> <i>praefectus vehiculorum</i>《碑》帝室郵便管理官.</div>\r\n","<div class=\"hw\">vehiculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vehiculum]</div><div class=\"def\">輸送に関する;運搬車の.</div>\r\n","<div class=\"hw\">vehiculārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://vehiculāris\">vehicularis</a>.</div>\r\n","<div class=\"hw\">vehiculātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vehiculum\">vehiculum</a>]</div><div class=\"def\">《碑》(馬と馬車を常備して)帝室郵便のすみやかな送達を実現すべき属州の義務.</div>\r\n","<div class=\"hw\">vehis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vehō\">vehō</a>]</div><div class=\"def\">荷を積んだ荷車;荷車1台分の荷物.</div>\r\n","<div class=\"hw\">vehātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[veho]</div><div class=\"def\">運搬, 輸送.</div>\r\n","<div class=\"hw\">vehēla</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[veho]</div><div class=\"def\">荷車.</div>\r\n","<div class=\"hw\">vehō</div><div class=\"pos\">-ere vexī vectum, <i>tr</i></div><div class=\"def\"><num>①</num> (人・動物の背に乗せて)運ぶ.</div><div class=\"def\"><num>②</num> (船・荷車で)運搬[輸送]する.</div><div class=\"def\"><num>③</num> (風・水・時間などが)運ぶ, もたらす</div><div class=\"ex\"><i>quod fugiens semel hora vexit</i> (<author>H<small>OR</small></author>)<span class=\"ext\">逃げ去る時がいったん運んだもの.</span></div><div class=\"def\"><num>④</num> (<i>pass</i>)(馬・馬車・船などに)乗って行く, 旅行する</div><div class=\"ex\"><i>equus in quo ego vehebar</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私が乗っていた馬</span></div><div class=\"ex\"><i>curru vehi</i> (<author>T<small>AC</small></author>)<span class=\"ext\">凱旋車に乗って来る</span></div><div class=\"ex\">(<i>pres part</i> を自動詞的に用いて)<i>quadrigis vehens</i> (<author>C<small>IC</small></author>)<span class=\"ext\">4頭立ての馬車に乗って.</span></div>\r\n","<div class=\"hw\">veia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">荷車, 荷馬車.</div>\r\n","<div class=\"hw\">vel</div><div class=\"pos\"><i>conj</i>, <i>adv</i>(volo の古い命令形)</div><div class=\"def\"><num>①</num> お望みなら</div><div class=\"ex\"><i>dasne savium?</i>―<i>immo ～ decem</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">キスしてくれる?―なんなら10回でもね.</span></div><div class=\"def\"><num>②</num> それとも, あるいは</div><div class=\"ex\">(単独で)<i>oppidum ～ urbem appellaverunt</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼らは町あるいは都市と呼んだ</span></div><div class=\"ex\"><i>～ potius</i><span class=\"ext\">否むしろ</span></div><div class=\"ex\"><i>post obitum ～ potius excessu Romuli</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Romulus の死後, というよりその姿が見えなくなってから</span></div><div class=\"ex\"><i>～ dicam</i> ... (<author>C<small>IC</small></author>)<span class=\"ext\">あるいは...とでも言おうか</span></div><div class=\"ex\">(二つ(以上)重ねて)<i>～ bello ～ paci paratus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">戦にも和平にも備えて.</span></div><div class=\"def\"><num>③</num> ...すら, ...さえも</div><div class=\"ex\"><i>～ mediocris orator</i> (<author>C<small>IC</small></author>)<span class=\"ext\">凡庸な弁士でも.</span></div><div class=\"def\"><num>④</num> たぶん, おそらく</div><div class=\"ex\"><i>～ propter ignis periculum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">おそらく火事の危険があったために.</span></div><div class=\"def\"><num>⑤</num> (+<i>superl</i>)明らかに, 文句なく</div><div class=\"ex\"><i>domus ～ optima</i> (<author>C<small>IC</small></author>)<span class=\"ext\">明らかに最高の館.</span></div><div class=\"def\"><num>⑥</num> たとえば</div><div class=\"ex\"><i>～ hic Pamphilus jurabat quotiens Bacchidi</i> (<author>T<small>ER</small></author>)<span class=\"ext\">たとえばこの Pamphilus は何度 Bacchis に誓ったことか.</span></div><div class=\"def\"><num>⑦</num> とにかく</div><div class=\"ex\"><i>credite ～ sorori</i> (<author>C<small>ALP</small></author>)<span class=\"ext\">せめて姉妹ぐらいは信じなさい.</span></div>\r\n","<div class=\"hw\">Veleda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウェレダ《Civilis の反乱(69‐70)で重要な役を演じた Bructeri 族の女予言者》.</div>\r\n","<div class=\"hw\">Velia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウェリア《 (1) Lucania 西海岸の町;ギリシア名 Elea.(2) ローマ市の Palatinus 丘の高みの一つ》.</div>\r\n","<div class=\"hw\">Veliensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Velia (1)  (2) の.</div><div class=\"hw2\"><b>Veliensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Velia (1) の住民.</div>\r\n","<div class=\"hw\">Veliocassēs</div><div class=\"pos\">-ium, <B>-cassī</B> -ōrum, <i>m pl</i></div><div class=\"def\">ウェリオカッセース《Gallia Belgica の一部族》.</div>\r\n","<div class=\"hw\">Veliternus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Velitrae の.</div><div class=\"hw2\"><b>Veliternī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Velitrae の住民.</div>\r\n","<div class=\"hw\">Veliternīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Veliternus\">Veliternus</a>.</div>\r\n","<div class=\"hw\">Velitrae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ウェリトラエ《ローマ市の約20km南東の Albanus(現 Monte Cavo)山南麓の町;現 Velletri》.</div>\r\n","<div class=\"hw\">Vellaunodūnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ウェッラウノドゥーヌム《Gallia Celtica の Senones 族の町》.</div>\r\n","<div class=\"hw\">Vellaviī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウェッラウィイー《Gallia Celtica の現 Velay 地方にいた一部族》.</div>\r\n","<div class=\"hw\">velle</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://volō\">volo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">vellicātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vellico]</div><div class=\"def\">あちこちから拾い上げて, まとまりなく.</div>\r\n","<div class=\"hw\">vellicātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vellicō\">vellicō</a>]</div><div class=\"def\">むしられること;嘲笑.</div>\r\n","<div class=\"hw\">vellicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vellō\">vellō</a>]</div><div class=\"def\"><num>①</num> つねる;むしる.</div><div class=\"def\"><num>②</num> (鳥がくちばしで)つつく.</div><div class=\"def\"><num>③</num> ののしる, 悪口を言う</div><div class=\"ex\"><i>absentem vellicare</i> (<author>H<small>OR</small></author>)<span class=\"ext\">陰口をたたく.</span></div><div class=\"def\"><num>④</num> (つねって)目を覚まさせる;刺激する.</div>\r\n","<div class=\"hw\">vellus<SUP>1</SUP></div><div class=\"pos\">-eris, <i>n</i></div><div class=\"def\"><num>①</num> 羊毛;羊毛の塊り</div><div class=\"ex\"><i>vellera trahere</i> (<author>O<small>V</small></author>)<span class=\"ext\">羊毛を梳<SUB>す</SUB>く.</span></div><div class=\"def\"><num>②</num> 絹.</div><div class=\"def\"><num>③</num> 羊皮;獣皮.</div><div class=\"def\"><num>④</num> 羊.</div><div class=\"def\"><num>⑤</num> 羊毛状のもの《雲・羽毛・雪片など》.</div><hr><div class=\"hw\">vellus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://villus\">villus</a>.</div>\r\n","<div class=\"hw\">Vellēius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェッレイユス《ローマ人の氏族名;特に (1) <i>C. ～</i>, Epicurus 学派の哲学者;弁論家 Crassus の友人(前1世紀).(2) <i>C. ～ Paterculus</i>, 歴史家;Tiberius 帝に仕えた;<i>Historiae Romanae</i> 「ローマ史」(未完)がある》.</div>\r\n","<div class=\"hw\">vellī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vellō\">vello</a>.</div>\r\n","<div class=\"hw\">vellō</div><div class=\"pos\">-ere vellī [vulsī] vulsum [volsum], <i>tr</i></div><div class=\"def\"><num>①</num> (毛・羽根などを)引っ張って抜く, むしる.</div><div class=\"def\"><num>②</num> (樹木などを)引き抜く</div><div class=\"ex\"><i>signa vellere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">軍旗を引き抜く(=進発する).</span></div><div class=\"def\"><num>③</num> 破壊する.</div><div class=\"def\"><num>④</num> 引っ張る</div><div class=\"ex\"><i>Cynthius aurem vellit et admonuit</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">Apollo が(私の)耳を引っ張って忠告された.</span></div>\r\n","<div class=\"hw\">velut, velutī</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vel/ut]</div><div class=\"def\"><num>①</num> たとえば.</div><div class=\"def\"><num>②</num> (ちょうど)...のように</div><div class=\"ex\">～ <i>pecora</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">家畜のように.</span></div><div class=\"def\"><num>③</num> いわば</div><div class=\"ex\">～ <i>hereditate relictum odium</i> (<author>N<small>EP</small></author>)<span class=\"ext\">いわば遺産相続のように受けついだ憎しみ.</span></div><div class=\"def\"><num>④</num> ～(<i>si</i>)〈+<i>subj</i>〉 あたかも...のように</div><div class=\"ex\"><i>～ si coram adesset</i> (<author>C<small>AES</small></author>)<span class=\"ext\">あたかも彼がその場にいるかのように.</span></div>\r\n","<div class=\"hw\">Velīnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Velia (1) の.</div><hr><div class=\"hw\">Velīnus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> <i>lacus ～</i> (<author>C<small>IC</small></author>)(Velinus 川が注ぐ)ウェリーヌス湖《Reate 北方に位置する》.</div><div class=\"def\"><num>②</num> <i>tribus Velina</i> (<author>C<small>IC</small></author>) Velinus 湖周辺の住民から成るローマ35部族の一つ.</div><hr><div class=\"hw\">Velīnus<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェリーヌス《Sabini 族の土地を流れる川》.</div>\r\n","<div class=\"hw\">vendax</div><div class=\"pos\">-ācis, <i>f</i></div><div class=\"ori\">[vendo]</div><div class=\"def\">売るのが好きな.</div>\r\n","<div class=\"hw\">vendibilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vendo]</div><div class=\"def\"><num>①</num> 売りやすい, (よく)売れる.</div><div class=\"def\"><num>②</num> (大衆に)好まれる, 人気のある.</div>\r\n","<div class=\"hw\">vendidī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vendō\">vendo</a>.</div>\r\n","<div class=\"hw\">venditiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vendo]</div><div class=\"def\"><num>①</num> 売却, 販売.</div><div class=\"def\"><num>②</num> 賃貸し.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 売却証書.</div>\r\n","<div class=\"hw\">venditor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vendo]</div><div class=\"def\"><num>①</num> 売り手.</div><div class=\"def\"><num>②</num> 不正取引をする人.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 裏切り者.</div>\r\n","<div class=\"hw\">venditum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://venditus\">venditus</a>]</div><div class=\"def\">売却, 販売.</div>\r\n","<div class=\"hw\">venditus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vendō\">vendo</a>.</div>\r\n","<div class=\"hw\">venditātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vendito]</div><div class=\"def\">ひけらかすこと, 誇示, 自慢.</div>\r\n","<div class=\"hw\">venditātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vendito]</div><div class=\"def\">ひけらかす人, 誇示する者.</div>\r\n","<div class=\"hw\">venditō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[vendo]</div><div class=\"def\"><num>①</num> (たびたび)売りに出す, 売ろうと努める.</div><div class=\"def\"><num>②</num> (金銭・報酬を目当てに)不正な取引をする, 売り物にする</div><div class=\"ex\"><i>pacem pretio venditare</i> (<author>L<small>IV</small></author>)<span class=\"ext\">和平に値をつけて売る《pretio は価格の <i>abl</i>》.</span></div><div class=\"def\"><num>③</num> ほめそやす, 吹聴する.</div><div class=\"def\"><num>④</num> (<i>refl</i>)自分を売り込む, (人に)取り入ろうとする</div><div class=\"ex\"><i>se venditant Caesari</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼らは Caesar のご機嫌を取ろうとしている.</span></div>\r\n","<div class=\"hw\">vendō</div><div class=\"pos\">-ere -didī -ditum, <i>tr</i></div><div class=\"ori\">[venum/do]</div><div class=\"def\">(<i>pp</i> venditus, <i>gerundiv</i> vendendus 以外の <i>pass</i> は通例 veneo を用いる)</div><div class=\"def\"><num>①</num> 売る, 売り立てる.</div><div class=\"def\"><num>②</num> (金銭・報酬を目当てに)不正な取引をする, 裏切る</div><div class=\"ex\"><i>auro patriam vendere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">黄金のために祖国を売る《auro は価格の <i>abl</i>》.</span></div><div class=\"def\"><num>③</num> ほめそやす, 吹聴する.</div><div class=\"def\"><num>④</num> 売り込む.</div>\r\n","<div class=\"hw\">Venedī, Venet(h)ī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウェネディー《Vistula 川中流域にいたスラブ系の一部族》.</div>\r\n","<div class=\"hw\">venerandus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>gerundiv</i>)</div><div class=\"ori\">[veneror]</div><div class=\"def\">畏敬の念を起こさせる, 尊敬に値する.</div>\r\n","<div class=\"hw\">veneranter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[veneror]</div><div class=\"def\">謹しんで, 敬って, うやうやしく.</div>\r\n","<div class=\"hw\">Venerius<SUP>1</SUP>, -reus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Venus の[に捧げられた].</div><div class=\"def\"><num>②</num> 性愛の[にかかわる]</div><div class=\"ex\"><i>res Veneria(sg)</i>, <i>res Veneriae(pl)</i> (<author>C<small>IC</small></author>)<span class=\"ext\">性交, 性的快楽.</span></div><div class=\"def\"><num>③</num> <i>concha Veneria</i> (<author>P<small>LIN</small></author>) 貝[軟体動物]の一種.</div><hr><div class=\"hw\">Venerius<SUP>2</SUP>, -reus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> Eryx の Venus 神殿の奴隷.</div><div class=\"def\"><num>②</num> (<i>sc. </i> jactus)(振り出した賽<SUB>さい</SUB>の)最高の目.</div>\r\n","<div class=\"hw\">veneror</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[venus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 崇拝する, 畏敬する.</div><div class=\"def\"><num>②</num> 尊敬する, 敬う, 敬意を表する</div><div class=\"ex\"><i>Larem farrepio veneratur</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">彼は聖なる麦粉(の供物)をそなえて Lar に祈る</span></div><div class=\"ex\">(<i>pass</i> の意味で)<i>Sibylla cursūs dabit venerata secundos</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">Sibylla は祈りに応じて順調な航海を許すだろう.</span></div><div class=\"def\"><num>③</num> 懇願[嘆願]する.</div>\r\n","<div class=\"hw\">venerābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[veneror]</div><div class=\"def\"><num>①</num> 尊ぶべき, 尊敬するに足る.</div><div class=\"def\"><num>②</num> 崇敬の念を示す.</div>\r\n","<div class=\"hw\">venerābiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://venerābilis\">venerābilis</a>]</div><div class=\"def\">うやうやしく, 敬意を表して.</div>\r\n","<div class=\"hw\">venerābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[veneror]</div><div class=\"def\">敬意を表する, うやうやしい.</div>\r\n","<div class=\"hw\">venerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[veneror]</div><div class=\"def\"><num>①</num> 崇敬, 崇拝;尊敬, 表敬.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 尊厳, 威光.</div>\r\n","<div class=\"hw\">venerātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[veneror]</div><div class=\"def\">尊敬[畏敬]する人.</div>\r\n","<div class=\"hw\">venerātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://veneror\">veneror</a>.</div>\r\n","<div class=\"hw\">venerō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">《古形》=<a href=\"entry://veneror\">veneror</a>.</div>\r\n","<div class=\"hw\">Venethī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Venedī\">Venedi</a>.</div>\r\n","<div class=\"hw\">Venetia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウェネティア《Veneti 族 (1)  (2) のいた地方[地域]》.</div>\r\n","<div class=\"hw\">Veneticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Veneti 族 (2) の.</div>\r\n","<div class=\"hw\">venetus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://Venetus\">Venetus</a>]</div><div class=\"def\">海の色をした, 青色の.</div>\r\n","<div class=\"hw\">Venetus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Veneti 族 (1) の.</div>\r\n","<div class=\"hw\">Venetī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウェネティー《 (1) イタリア北東部の現 Veneto 州にあたる地方にいた一部族.(2) Gallia Lugdunensis の現 Morbihan 県にあたる地域にいた一部族.(3) =<a href=\"entry://Venedī\">Venedi</a>》.</div>\r\n","<div class=\"hw\">venia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf</i>. venus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 恩恵, 好意, 思いやり</div><div class=\"ex\"><i>posce deos veniam</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">神々に恩恵を乞い求めなさい.</span></div><div class=\"def\"><num>②</num> 許可, 同意</div><div class=\"ex\"><i>bonā(cum)veniā</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ご免をこうむって, 失礼ながら.</span></div><div class=\"def\"><num>③</num> 寛大, 容赦, 免罪</div><div class=\"ex\"><i>veniam exilii impetrare</i> (<author>T<small>AC</small></author>)<span class=\"ext\">追放解除の願いを聞き届けられる.</span></div>\r\n","<div class=\"hw\">veniābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://venia\">venia</a>]</div><div class=\"def\">(罪が)赦される.</div>\r\n","<div class=\"hw\">veniālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[venia]</div><div class=\"def\"><num>①</num> 赦される</div><div class=\"ex\"><i>peccata venialia</i> (<author>A<small>UG</small></author>)<span class=\"ext\">〘カト〙小罪.</span></div><div class=\"def\"><num>②</num> 恵み深い.</div><div class=\"def\"><num>③</num> 〘修〙弁明の.</div>\r\n","<div class=\"hw\">veniō</div><div class=\"pos\">-īre vēnī ventum, <i>intr</i></div><div class=\"def\"><num>①</num> 来る, 到着する</div><div class=\"ex\"><i>ad urbem [me] venire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">都[私のところ]に来る</span></div><div class=\"ex\">(+<i>sup</i>)<i>spectatum venire</i> (<author>O<small>V</small></author>)<span class=\"ext\">見物しに来る</span></div><div class=\"ex\">(+目的の <i>dat</i>)<i>subsidio venire</i> (<author>C<small>AES</small></author>)<span class=\"ext\">救援に来る</span></div><div class=\"ex\">(+<i>inf</i>)<i>modo venerat aurum petere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">彼はさっき金がほしいと言ってやって来た</span></div><div class=\"ex\">(+<i>fut p</i>)<i>veni postulaturus</i> (<author>T<small>AC</small></author>)<span class=\"ext\">私は要請するするためにやって来た</span></div><div class=\"ex\">(impers pass)<i>est in Britanniam ventum</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Britannia に着いた.</span></div><div class=\"def\"><num>②</num> 帰る, 帰還する.</div><div class=\"def\"><num>③</num> 来襲する, 進撃して来る.</div><div class=\"def\"><num>④</num> 法廷に出頭する, 出廷する 〈contra alqm [alqd];pro alqo〉.</div><div class=\"def\"><num>⑤</num> (時が)到来する, 近づく</div><div class=\"ex\"><i>veniens annus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">来年.</span></div><div class=\"def\"><num>⑥</num> (ある状態[立場]に)なる, 陥る</div><div class=\"ex\"><i>in periculum venire</i> (<author>C<small>AES</small></author>)<span class=\"ext\">危殆に瀕<SUB>ひん</SUB>する</span></div><div class=\"ex\"><i>in Caesaris fidem et potestatem venire</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Caesar の保護と権力下に入る</span></div><div class=\"ex\"><i>res venit prope secessionem plebis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">あわや平民の離脱かという事態に立ち至った.</span></div><div class=\"def\"><num>⑦</num> 現われる, 出現する</div><div class=\"ex\"><i>res alicui in mentem venit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あることがある人の心に浮かぶ</span></div><div class=\"ex\">(impers;+<i>gen</i>)<i>venit mihi Platonis in mentem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は Plato のことを想起する.</span></div><div class=\"def\"><num>⑧</num> (植物が)成長する, 繁茂する.</div><div class=\"def\"><num>⑨</num> ...に由来する, ...の血筋[系統]である.</div><div class=\"def\"><num>⑩</num> 生ずる, 起こる</div><div class=\"ex\"><i>ad te post paulo ventura pericula</i> (<author>H<small>OR</small></author>)<span class=\"ext\">しばらくするとあなたの身に危険が及ぼうとしている.</span></div><div class=\"def\"><num>⑪</num> (ある人の)所有物となる, ...に帰属する</div><div class=\"ex\"><i>hereditas alicui venit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">遺産がある人の所有に帰す.</span></div><div class=\"def\"><num>⑫</num> (手紙・報告などが)もたらされる.</div><div class=\"def\"><num>⑬</num> (不幸・災害などが)襲う.</div><div class=\"def\"><num>⑭</num> (談話が)...に及ぶ, 言及する.</div><div class=\"def\"><num>⑮</num> (ある行動に)出る, 訴える;(ある方針を)採る.</div><div class=\"def\"><num>⑯</num> (ある範疇・項目に)包含される.</div>\r\n","<div class=\"hw\">Vennōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェンノーニウス《ローマの歴史家(前2世紀後半);その著作は散逸して現存しない》.</div>\r\n","<div class=\"hw\">vennūculus, vennunculus, vēnūculus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> <i>uva venucula</i> (<author>H<small>OR</small></author>) ブドウの一種.</div><div class=\"def\"><num>②</num> <i>far vennunculum</i> (<author>C<small>OL</small></author>) 小麦の一種.</div>\r\n","<div class=\"hw\">venter</div><div class=\"pos\">-tris, <i>m</i></div><div class=\"def\"><num>①</num> 腹;胃.</div><div class=\"def\"><num>②</num> 大食い, 暴食</div><div class=\"ex\"><i>deditus ventri atque somno</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">食欲と眠気のとりことなって.</span></div><div class=\"def\"><num>③</num> 子宮;胎児</div><div class=\"ex\"><i>ventrem ferre</i> (<author>L<small>IV</small></author>)<span class=\"ext\">妊娠している.</span></div><div class=\"def\"><num>④</num> ふくらみ, ふくらんだもの.</div>\r\n","<div class=\"hw\">Ventidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェンティディウス《ローマ人の氏族名;特に <i>P. ～ Bassus</i>, Parthia 戦で武勲を立てた(前38)》.</div>\r\n","<div class=\"hw\">Ventidiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ventidius の.</div>\r\n","<div class=\"hw\">ventilābrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ventilo]</div><div class=\"def\">(穀物をあおぎ分けるときに使う)熊手.</div>\r\n","<div class=\"hw\">ventilātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[ventilo]</div><div class=\"def\"><num>①</num> 大気にさらすこと.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 穀物をあおぎ分けること.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 正邪の判定.</div>\r\n","<div class=\"hw\">ventilātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://ventilō\">ventilō</a>]</div><div class=\"def\"><num>①</num> (穀物を)あおぎ分ける人.</div><div class=\"def\"><num>②</num> 一種の曲芸師.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 正邪の判定者.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 攪乱者.</div>\r\n","<div class=\"hw\">ventilō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ventus<SUP>3</SUP>]</div><div class=\"def\"><num>①</num> (空中で)振り回す, 揺り動かす.</div><div class=\"def\"><num>②</num> 風を送る, あおぐ.</div><div class=\"def\"><num>③</num> (穀物を)あおぎ[吹き]分ける.</div><div class=\"def\"><num>④</num> (空気・風に)あてる, さらす.</div><div class=\"def\"><num>⑤</num> あおる, かきたてる.</div><div class=\"def\"><num>⑥</num> 討議する.</div>\r\n","<div class=\"hw\">ventitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[venio]</div><div class=\"def\">たびたび来る, よく訪れる.</div>\r\n","<div class=\"hw\">ventiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[venio]</div><div class=\"def\">来ること, 到着.</div>\r\n","<div class=\"hw\">ventricola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[venter/colo<SUP>2</SUP>]</div><div class=\"def\">腹(=食欲)の奴隷, 大食漢.</div>\r\n","<div class=\"hw\">ventriculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[venter]</div><div class=\"def\"><num>①</num> 腹;胃.</div><div class=\"def\"><num>②</num> </div><div class=\"ex\">～ <i>cordis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">心室.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙室.</div>\r\n","<div class=\"hw\">ventriōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[venter]</div><div class=\"def\">太鼓腹の.</div>\r\n","<div class=\"hw\">ventrāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[venter]</div><div class=\"def\">(金品携帯用の)腹帯.</div>\r\n","<div class=\"hw\">ventrālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[venter]</div><div class=\"def\"><num>①</num> 腹の, 腹部の.</div><div class=\"def\"><num>②</num> 〘解・動〙腹側の.</div>\r\n","<div class=\"hw\">ventrōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://ventriōsus\">ventriosus</a>.</div>\r\n","<div class=\"hw\">ventulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[ventus<SUP>3</SUP>]</div><div class=\"def\">そよ風, 微風.</div>\r\n","<div class=\"hw\">ventus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://veniō\">venio</a>.</div><hr><div class=\"hw\">ventus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">来ること, 到来.</div><hr><div class=\"hw\">ventus<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 風</div><div class=\"ex\">～ <i>secundus</i> (<author>C<small>AES</small></author>)<span class=\"ext\">(航行する船への)順風</span></div><div class=\"ex\"><i>dare verba ventis [in ventos]</i> (<author>O<small>V</small></author>)<span class=\"ext\">約束を守らない.</span></div><div class=\"def\"><num>②</num> 一陣の風, そよ風.</div><div class=\"def\"><num>③</num> (<i>pl</i>)風神たち.</div><div class=\"def\"><num>④</num> (運・不運・世評などの)風向き;(事件・できごとなどに吹きつける)突風, 嵐</div><div class=\"ex\"><i>quicumque venti erunt</i> (<author>C<small>IC</small></author>)<span class=\"ext\">どう風向きが変わろうと, どんな状況になろうとも.</span></div><div class=\"def\"><num>⑤</num> 腸内ガス, 屁.</div>\r\n","<div class=\"hw\">ventōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ventōsus\">ventōsus</a>]</div><div class=\"def\"><num>①</num> 〘病〙鼓脹.</div><div class=\"def\"><num>②</num> くだらない自慢, 大風呂敷.</div>\r\n","<div class=\"hw\">ventōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ventus<SUP>3</SUP>]</div><div class=\"def\"><num>①</num> 風の多い, 吹きさらしの.</div><div class=\"def\"><num>②</num> 風のように速い.</div><div class=\"def\"><num>③</num> 空虚な, うぬぼれた</div><div class=\"ex\"><i>ventosa lingua</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">大言壮語する舌.</span></div><div class=\"def\"><num>④</num> 変わりやすい, 移り気な.</div>\r\n","<div class=\"hw\">ventūrus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>fut p</i>)</div><div class=\"ori\">[venio]</div><div class=\"def\">来たるべき, 将来の</div><div class=\"ex\"><i>venturum saeclum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">新しい時代.</span></div>\r\n","<div class=\"hw\">venus<SUP>2</SUP></div><div class=\"pos\">-neris, <i>f</i></div><div class=\"ori\">[<i>cf. </i> veneror]</div><div class=\"def\"><num>①</num> 性愛, 性交, 情事.</div><div class=\"def\"><num>②</num> 恋人, 愛人《女性》.</div><div class=\"def\"><num>③</num> 魅力, 色香, 容色.</div><div class=\"def\"><num>④</num> 優美, 優雅.</div>\r\n","<div class=\"hw\">Venus</div><div class=\"pos\">-neris, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://venus\">venus<SUP>2</SUP></a>]</div><div class=\"def\"><num>①</num> 〘神話〙ウェヌス, <SUP>∥</SUP>ヴィーナス《愛と美の女神;Volcanus の妻で Cupido の母;Aeneas は Anchises との間にもうけた息子;ギリシア神話の Aphrodite と同一視された》</div><div class=\"ex\"><i>mensis Veneris</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Aprīlis\">Aprilis</a></span></div><div class=\"ex\"><i>avis Veneris</i> (<author>M<small>AN</small></author>)<span class=\"ext\">ハト(鳩).</span></div><div class=\"def\"><num>②</num> 〘天〙金星.</div><div class=\"def\"><num>③</num> さいころ遊びの最高の目《4面のさいころを4個同時に振って全部違う目が出たとき》.</div><div class=\"def\"><num>④</num> <i>portus Veneris</i> (<author>M<small>ELA</small></author>) Gallia Narbonensis の港町(現 Port-Vendres).</div>\r\n","<div class=\"hw\">Venusia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウェヌシア《Apulia の Appia 街道沿いの町;詩人 Horatius の生地;現 Venosa》.</div>\r\n","<div class=\"hw\">venustulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://venustus\">venustus</a>]</div><div class=\"def\">魅力のある, 人を引きつける.</div>\r\n","<div class=\"hw\">venustus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[venus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 魅力のある, 愛らしい, 美しい.</div><div class=\"def\"><num>②</num> (語り口・文体が)優雅な, 洗練された, 気の利いた.</div>\r\n","<div class=\"hw\">venustās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[venus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 美, 愛らしさ.</div><div class=\"def\"><num>②</num> 魅力, 優雅.</div><div class=\"def\"><num>③</num> 喜び, 楽しみ.</div>\r\n","<div class=\"hw\">venustē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[venustus]</div><div class=\"def\">魅力的に, 優美に.</div>\r\n","<div class=\"hw\">venustō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[venustus]</div><div class=\"def\">魅力的にする, 美化する.</div>\r\n","<div class=\"hw\">Venusīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Venusia の.</div><div class=\"hw2\"><b>Venusīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Venusia の住民.</div>\r\n","<div class=\"hw\">Venāfrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ウェナーフルム《Campania の Samnites 族の町;良質のオリーブ油で有名;現 Venafro》.</div>\r\n","<div class=\"hw\">Venāfrānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Venafrum の.</div><div class=\"hw2\"><b>Venāfrānum</b></div><div class=\"pos2\">-ī, <i>n</i></div><div class=\"def2\">Venafrum 産のオリーブ油.</div>\r\n","<div class=\"hw\">venēfica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[veneficus]</div><div class=\"def\"><num>①</num> 毒を盛る者《女性》.</div><div class=\"def\"><num>②</num> 魔女.</div>\r\n","<div class=\"hw\">venēficium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://venēficus\">venēficus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 毒を盛ること;毒殺.</div><div class=\"def\"><num>②</num> 毒物, 毒薬.</div><div class=\"def\"><num>③</num> 魔法, 妖術.</div><div class=\"def\"><num>④</num> 媚薬<SUB>びやく</SUB>, ほれ薬.</div>\r\n","<div class=\"hw\">venēficus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[venenum/facio]</div><div class=\"def\"><num>①</num> 毒を盛る;有毒の.</div><div class=\"def\"><num>②</num> 魔法の.</div><hr><div class=\"hw\">venēficus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 毒を盛る人, 毒殺者.</div><div class=\"def\"><num>②</num> 魔法使い.</div>\r\n","<div class=\"hw\">venēnifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[venenum/fero]</div><div class=\"def\">《詩》毒をもたらす.</div>\r\n","<div class=\"hw\">venēnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 薬草;薬物, 薬.</div><div class=\"def\"><num>②</num> 毒物, 毒薬;害になるもの.</div><div class=\"def\"><num>③</num> 魔法の薬;媚薬<SUB>びやく</SUB>.</div><div class=\"def\"><num>④</num> 化粧品;香料.</div><div class=\"def\"><num>⑤</num> 染料.</div>\r\n","<div class=\"hw\">venēnārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[venenum]</div><div class=\"def\">毒の, 毒を含んだ.</div><hr><div class=\"hw\">venēnārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">毒物を調合する人;毒殺者.</div>\r\n","<div class=\"hw\">venēnātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[veneno]</div><div class=\"def\"><num>①</num> 毒を持っている, 有毒な</div><div class=\"ex\"><i>venenatae sagittae</i> (<author>H<small>OR</small></author>)<span class=\"ext\">毒矢.</span></div><div class=\"def\"><num>②</num> 有害な, 危険な;恐ろしい.</div><div class=\"def\"><num>③</num> 魔法の, 魔力を持った.</div>\r\n","<div class=\"hw\">venēnō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[venenum]</div><div class=\"def\"><num>①</num> 毒を入れる[塗る].</div><div class=\"def\"><num>②</num> 害する, そこなう.</div><div class=\"def\"><num>③</num> 魔法をかける.</div><div class=\"def\"><num>④</num> 染める.</div>\r\n","<div class=\"hw\">venēnōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://venēnum\">venēnum</a>]</div><div class=\"def\">(きわめて)有毒な.</div>\r\n","<div class=\"hw\">venīlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">浜辺を洗う水.</div>\r\n","<div class=\"hw\">Venīlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ウェニーリア《ニンフの名; (1) Turnus (1) の母.(2) Janus の妻》.</div>\r\n","<div class=\"hw\">venīre<SUP>1</SUP></div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://veniō\">venio</a>.</div>\r\n","<div class=\"hw\">vepris</div><div class=\"pos\">-is, <i>m</i>(<i>f</i>)(通例 <i>pl</i><b>veprēs</b> -ium [-um])</div><div class=\"def\">イバラの茂み.</div>\r\n","<div class=\"hw\">veprēcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vepris]</div><div class=\"def\">イバラの小さな茂み.</div>\r\n","<div class=\"hw\">veprētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vepris\">vepris</a>]</div><div class=\"def\">イバラの生け垣.</div>\r\n","<div class=\"hw\">Veragrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウェラグリー《Gallia Narbonensis の Octodurus(現 Martigny)あたりにいた一部族》.</div>\r\n","<div class=\"hw\">verbascum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙(ゴマノハグサ科)モウズイカ属の植物.</div>\r\n","<div class=\"hw\">verber</div><div class=\"pos\">-eris, <i>n</i></div><div class=\"ori\">[<i>cf. </i> verbena]</div><div class=\"def\"><num>①</num> 鞭.</div><div class=\"def\"><num>②</num> 投石機のひも.</div><div class=\"def\"><num>③</num> 鞭で打つこと;笞刑<SUB>ちけい</SUB>.</div><div class=\"def\"><num>④</num> (一般に)打つ[たたく]こと, 打撃.</div><div class=\"def\"><num>⑤</num> (ことばによる)非難, 叱責.</div>\r\n","<div class=\"hw\">verberetillus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://verbereus\">verbereus</a>.</div>\r\n","<div class=\"hw\">verbereus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verber]</div><div class=\"def\">鞭打ちに値する.</div>\r\n","<div class=\"hw\">verberābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[verbero<SUP>1</SUP>]</div><div class=\"def\">鞭打ちに値する.</div>\r\n","<div class=\"hw\">verberābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verbero<SUP>1</SUP>]</div><div class=\"def\">鞭で打つ.</div>\r\n","<div class=\"hw\">verberātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[verbero<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 鞭で打つこと;笞刑<SUB>ちけい</SUB>.</div><div class=\"def\"><num>②</num> 懲罰</div><div class=\"ex\">～ <i>cessationis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">怠惰への叱責.</span></div>\r\n","<div class=\"hw\">verberātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[verbero<SUP>1</SUP>]</div><div class=\"def\">打つこと.</div>\r\n","<div class=\"hw\">verberō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[verber]</div><div class=\"def\"><num>①</num> 鞭で打つ;折檻する.</div><div class=\"def\"><num>②</num> 攻撃する, 襲う.</div><div class=\"def\"><num>③</num> (風・波などが)打つ, たたく.</div><div class=\"def\"><num>④</num> (ことばで)非難[叱責]する.</div><hr><div class=\"hw\">verberō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">鞭打ちに値する者, ならず者, 悪党.</div>\r\n","<div class=\"hw\">verbex</div><div class=\"pos\">-ēcis, <i>m</i></div><div class=\"def\">=<a href=\"entry://vervex\">vervex</a>.</div>\r\n","<div class=\"hw\">verbificātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[verbum/facio]</div><div class=\"def\">大いに弁ずること.</div>\r\n","<div class=\"hw\">verbigena</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[verbum/gigno]</div><div class=\"def\">ことばから生まれた者(=キリスト).</div>\r\n","<div class=\"hw\">verbigerō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[verbum/gero]</div><div class=\"def\">ことばを交わす, 議論する.</div>\r\n","<div class=\"hw\">verbivēlitātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[verbum/velitatio]</div><div class=\"def\">口げんか, 口論.</div>\r\n","<div class=\"hw\">verbum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ことば, 語, 単語</div><div class=\"ex\"><i>uno verbo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一言で言えば, 要するに</span></div><div class=\"ex\">～ <i>pro verbo</i> (<author>C<small>IC</small></author>) =<i>ad</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">一語一語, 逐語的に, 正確に</span></div><div class=\"ex\"><i>verbi gratiā [causā]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">たとえば</span></div><div class=\"ex\"><i>meis [tuis] verbis</i><span class=\"ext\">私[あなた]に代わって[のために]</span></div><div class=\"ex\"><i>tu velim Piliam meis verbis consolere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私に代わって Pilia を慰めてやってもらえませんか.</span></div><div class=\"def\"><num>②</num> 発言, 談話</div><div class=\"ex\"><i>verba facere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">話をする</span></div><div class=\"ex\"><i>in verbo</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">話の途中で.</span></div><div class=\"def\"><num>③</num> (内実・行動を伴わない)単なることば, 空言</div><div class=\"ex\"><i>alicui verba dare</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">ある人をだます</span></div><div class=\"ex\"><i>verbo...re</i> (<author>C<small>IC</small></author>)<span class=\"ext\">名目上[理屈の上で]は...だが実際は.</span></div><div class=\"def\"><num>④</num> きまり文句;ことわざ, 格言.</div><div class=\"def\"><num>⑤</num> 〘文〙動詞.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 聖言, みことば;(三位一体の第2位たる)キリスト.</div>\r\n","<div class=\"hw\">verbālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[verbum]</div><div class=\"def\"><num>①</num> ことばの.</div><div class=\"def\"><num>②</num> 〘文〙動詞の, 動詞から派生した.</div>\r\n","<div class=\"hw\">verbēna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(オリーブ・ギンバイカ・月桂樹などの)芳香のある植物の小枝[若枝]《宗教儀式・医療に用いられた》.</div>\r\n","<div class=\"hw\">verbēnāca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://verbēna\">verbēna</a>]</div><div class=\"def\">〘植〙クマツヅラ属の植物.</div>\r\n","<div class=\"hw\">verbēnātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verbena]</div><div class=\"def\">(神聖な)小枝の冠をかぶった.</div>\r\n","<div class=\"hw\">verbōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://verbōsus\">verbōsus</a>]</div><div class=\"def\">ことば数の多いこと;駄弁, 冗舌.</div>\r\n","<div class=\"hw\">verbōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://verbum\">verbum</a>]</div><div class=\"def\"><num>①</num> ことば数の多い, くだくだしい, 冗長な.</div><div class=\"def\"><num>②</num> おしゃべり好きな, 多弁な.</div>\r\n","<div class=\"hw\">verbōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[verbosus]</div><div class=\"def\">多くのことばを費やして, くだくだと.</div>\r\n","<div class=\"hw\">Vercellae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ウェルケッラエ《Gallia Cisalpina の町;Mediolanum の西;現 Vercelli》.</div>\r\n","<div class=\"hw\">Vercingetorix</div><div class=\"pos\">-igis, <i>m</i></div><div class=\"def\">ウェルキンゲトリクス《Caesar に対する Gallia 人の反乱(前52)を指揮した Arverni 族の首領》.</div>\r\n","<div class=\"hw\">verculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[ver]</div><div class=\"def\">春のように美しい女<SUB>ひと</SUB>《原義は 「小さな春」》.</div>\r\n","<div class=\"hw\">verenda</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://verendus\">verendus</a>]</div><div class=\"def\">性器, 陰部.</div>\r\n","<div class=\"hw\">verendus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vereor\">vereor</a>]</div><div class=\"def\"><num>①</num> 畏怖[尊敬]すべき, おごそかな.</div><div class=\"def\"><num>②</num> 恐るべき.</div>\r\n","<div class=\"hw\">vereor</div><div class=\"pos\">-ērī veritus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"def\"><num>①</num> 畏敬する, 尊重する 〈+<i>acc</i>;+<i>gen</i>〉</div><div class=\"ex\"><i>metuebant eum servi</i>, <i>verebantur liberi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">奴隷どもは彼を恐れていたが, 子らは敬愛していた</span></div><div class=\"ex\"><i>ne tui quidem testimoni veritus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼はあなたが(彼の)人物保証をしてくれたことをまったく意に介さずに.</span></div><div class=\"def\"><num>②</num> 恐れる, 心配[危惧]する, 逡巡する 〈+<i>acc</i>;+<i>dat</i>;de re;+<i>inf</i>;ne;ne non;ut;+間接疑問〉</div><div class=\"ex\"><i>hostem vereri</i> (<author>C<small>AES</small></author>)<span class=\"ext\">敵を恐れる</span></div><div class=\"ex\"><i>minus navibus veritus</i> (<author>C<small>AES</small></author>)<span class=\"ext\">船の心配はしないで</span></div><div class=\"ex\"><i>de Carthagine vereri</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Carthago に恐れを抱く</span></div><div class=\"ex\"><i>quos interficere vereretur</i> (<author>C<small>AES</small></author>)<span class=\"ext\">殺すのをはばかるような者らを</span></div><div class=\"ex\"><i>～ ne iste jam auctionem nullam faciat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あの人がもう競売を行なわないのではないかと私は心配している</span></div><div class=\"ex\"><i>videris vereri ut epistulas illas acceperim</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなたは私があの手紙を受け取っていないのではとご心配のようだ</span></div><div class=\"ex\">～ <i>quid agat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼(の容態)がどんな具合か気がかりだ.</span></div>\r\n","<div class=\"hw\">Vergiliae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[vergo]</div><div class=\"def\">〘天〙すばる(=<a href=\"entry://Plēïades\">Pleiades</a>)《雄牛座中の星団》.</div>\r\n","<div class=\"hw\">Vergilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェルギリウス《ローマ人の氏族名;特に <i>P. ～ Maro</i>, 詩人(前70‐19);<i>Eclogae</i> 「牧歌」, <i>Georgica</i> 「農耕歌」, <i>Aeneis</i> 「アエネーイス」 を著わした》.</div>\r\n","<div class=\"hw\">Vergobretus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェルゴブレトゥス《Gallia の Aedui 族の最高の官職名》.</div>\r\n","<div class=\"hw\">Vergīnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェルギーニウス《ローマ人の氏族名;特に <i>L</i>. ～, 娘 Verginia が十人委員(decemvir)の Appius Claudius に横恋慕されて強奪されたため, 裁判の最中に娘を殺害してその自由と名誉を守った百人隊長;この事件がきっかけとなって十人委員会は廃止された(前449)》.</div>\r\n","<div class=\"hw\">vergō</div><div class=\"pos\">-ere versī, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 傾く, 沈む.</div><div class=\"def\"><num>②</num> 傾斜をなす, (下方に)向かって[延びて]いる;面する, 位置する.</div><div class=\"def\"><num>③</num> (時・期間が)終わりに近づく;衰退する</div><div class=\"ex\"><i>vergente die</i> (<author>S<small>UET</small></author>)<span class=\"ext\">日が西に傾いたころ.</span></div><div class=\"def\"><num>④</num> 変色する.</div><div class=\"def\"><num>⑤</num> (<i>tr</i>)傾ける, (下方に)向かわせる;注ぐ.</div>\r\n","<div class=\"hw\">vericulum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[veru]</div><div class=\"def\"><num>①</num> (小さな)串.</div><div class=\"def\"><num>②</num> (小さな)槍.</div>\r\n","<div class=\"hw\">veritus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vereor\">vereor</a>.</div>\r\n","<div class=\"hw\">vermiculor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://vermiculus\">vermiculus</a>]</div><div class=\"def\">(木に)虫が付いている, むしばまれている.</div>\r\n","<div class=\"hw\">vermiculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[vermis]</div><div class=\"def\"><num>①</num> 小さな虫;(昆虫の)幼虫.</div><div class=\"def\"><num>②</num> 狂犬病.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 深紅色(=<a href=\"entry://coccum\">coccum</a>).</div>\r\n","<div class=\"hw\">vermiculātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vermiculor]</div><div class=\"def\">(樹木・果実が)虫に食われる[むしばまれる]こと.</div>\r\n","<div class=\"hw\">vermiculātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://vermiculor\">vermiculor</a>]</div><div class=\"def\"><num>①</num> 虫の食った.</div><div class=\"def\"><num>②</num> (モザイクが)虫食い形模様の.</div>\r\n","<div class=\"hw\">vermifugum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[vermis/fugio]</div><div class=\"def\">〘薬〙駆虫薬, 虫下し.</div>\r\n","<div class=\"hw\">vermina</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"ori\">[<i>cf</i>. vermis]</div><div class=\"def\">のたうちまわるような激しい腹痛, 疝痛<SUB>せんつう</SUB>.</div>\r\n","<div class=\"hw\">verminor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"ori\">[↑<a href=\"entry://verminō\">verminō</a>]</div><div class=\"def\">(痛風・陣痛などの)激痛に苦しむ.</div>\r\n","<div class=\"hw\">verminātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://verminō\">verminō</a>]</div><div class=\"def\"><num>①</num> いても立ってもいられないほどの激痛.</div><div class=\"def\"><num>②</num> (駄獣の)シラミ寄生[寄生虫]症.</div>\r\n","<div class=\"hw\">verminō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[vermina]</div><div class=\"def\"><num>①</num> 激痛に苦しむ.</div><div class=\"def\"><num>②</num> 害虫[寄生虫]に悩まされる.</div>\r\n","<div class=\"hw\">verminōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vermis\">vermis</a>]</div><div class=\"def\">虫のわいた, 虫が付いた.</div>\r\n","<div class=\"hw\">vermis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> (昆虫の)幼虫, 蛆<SUB>うじ</SUB>虫;ミミズ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙(小脳)虫部.</div>\r\n","<div class=\"hw\">verna</div><div class=\"pos\">-ae, <i>m</i>(<i>f</i>)</div><div class=\"def\"><num>①</num> 主人の家で生まれた奴隷.</div><div class=\"def\"><num>②</num> その土地で生まれた人[採れたもの], 土地っ子.</div>\r\n","<div class=\"hw\">vernula</div><div class=\"pos\">-ae, <i>m</i>(<i>f</i>)<i>dim</i></div><div class=\"ori\">[verna]</div><div class=\"def\">主人の家で生まれた若い奴隷.</div>\r\n","<div class=\"hw\">vernum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vernus\">vernus</a>]</div><div class=\"def\">春, 春の季節</div><div class=\"ex\"><i>verno</i> (<author>C<small>ATO</small></author>)<span class=\"ext\">春に.</span></div>\r\n","<div class=\"hw\">vernus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ver]</div><div class=\"def\">春の.</div>\r\n","<div class=\"hw\">vernāculus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↑<a href=\"entry://verna\">verna</a>]</div><div class=\"def\"><num>①</num> (奴隷が)主人の家で生まれた.</div><div class=\"def\"><num>②</num> その土地で生まれた[産出する], 土着の, 本国(特にローマ)の.</div><div class=\"def\"><num>③</num> (軍隊が)現地で徴募された.</div><div class=\"def\"><num>④</num> 粗野な.</div><hr><div class=\"hw\">vernāculus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> (<i>m</i>, <i>f</i>)主人の家で生まれた奴隷.</div><div class=\"def\"><num>②</num> 悪ふざけをする人, おどけ者.</div>\r\n","<div class=\"hw\">vernālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[ver]</div><div class=\"def\">春の.</div>\r\n","<div class=\"hw\">vernātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[verno]</div><div class=\"def\"><num>①</num> (ヘビなどの)脱皮.</div><div class=\"def\"><num>②</num> (ヘビの)抜け殻.</div>\r\n","<div class=\"hw\">vernīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[verna]</div><div class=\"def\"><num>①</num> 主人の家で生まれた奴隷の.</div><div class=\"def\"><num>②</num> 奴隷根性の, こびへつらう.</div><div class=\"def\"><num>③</num> おどけた, ふざけた.</div>\r\n","<div class=\"hw\">vernīliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vernilis]</div><div class=\"def\"><num>①</num> 主人の家で生まれた奴隷のように.</div><div class=\"def\"><num>②</num> へつらって.</div><div class=\"def\"><num>③</num> おどけて, ふざけて.</div>\r\n","<div class=\"hw\">vernīlitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vernīlis\">vernīlis</a>]</div><div class=\"def\"><num>①</num> 奴隷根性, 追従<SUB>ついしょう</SUB>.</div><div class=\"def\"><num>②</num> 生意気, 無作法.</div>\r\n","<div class=\"hw\">vernō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[vernus]</div><div class=\"def\"><num>①</num> 春のようになる, 緑の草木でおおわれるようになる;開花する.</div><div class=\"def\"><num>②</num> 活発に[若々しく]なる;うっすらとひげが生える.</div>\r\n","<div class=\"hw\">Veromanduī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Viromanduī\">Viromandui</a>.</div>\r\n","<div class=\"hw\">verpa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://verpus\">verpus</a>]</div><div class=\"def\">(包皮から突出した)陰茎(=membrum virile).</div>\r\n","<div class=\"hw\">verpus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(陰茎が)包皮から突き出た;割礼を受けた.</div>\r\n","<div class=\"hw\">verriculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[verro]</div><div class=\"def\">引き網, 地引き網(=<a href=\"entry://ēverrīculum\">everriculum</a>).</div>\r\n","<div class=\"hw\">Verrius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Verrīnus\">Verrinus</a>.</div><hr><div class=\"hw\">Verrius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェッリウス《ローマ人の氏族名;特に ～ <i>Flaccus</i>, Augustus 帝時代の文法家》.</div>\r\n","<div class=\"hw\">verruncō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[averrunco]</div><div class=\"def\">回転する</div><div class=\"ex\"><i>ea bene populo verruncent</i> (<author>L<small>IV</small></author>)<span class=\"ext\">事態が(ローマの)人々に上首尾に終わりますように《祈りの決まった文句》.</span></div>\r\n","<div class=\"hw\">verrēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">〘動〙(去勢されていない)雄豚;イノシシ.</div>\r\n","<div class=\"hw\">Verrēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ウェッレース《ローマ人の家名;特に <i>C. Cornelius ～</i>, 属州総督として Sicilia 島民を手ひどく搾取したため Cicero に弾劾<SUB>だんがい</SUB>された(前70)》.</div>\r\n","<div class=\"hw\">verrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verres]</div><div class=\"def\">(去勢されていない)雄豚の;イノシシの.</div>\r\n","<div class=\"hw\">Verrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Verres の.</div>\r\n","<div class=\"hw\">verrō</div><div class=\"pos\">-ere versum, <i>tr</i></div><div class=\"def\"><num>①</num> (ほうきで)掃く, 掃き清める;(掃き)集める.</div><div class=\"def\"><num>②</num> 引きずる.</div><div class=\"def\"><num>③</num> (風・船・イルカなどが水面を)かすめて[すべるように]進む.</div><div class=\"def\"><num>④</num> (風が)吹き飛ばす, 吹きまくる.</div>\r\n","<div class=\"hw\">verrūca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> いぼ;できもの.</div><div class=\"def\"><num>②</num> 瑕瑾<SUB>かきん</SUB>, 小さな欠点.</div><div class=\"def\"><num>③</num> 高所, (土地の)隆起.</div>\r\n","<div class=\"hw\">verrūcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[verruca]</div><div class=\"def\"><num>①</num> 小さないぼ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(土地の)小隆起.</div>\r\n","<div class=\"hw\">verrūcārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://verrūca\">verrūca</a>]</div><div class=\"def\">いぼの</div><div class=\"ex\"><i>herba verrucaria</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">〘植〙キダチルリソウ(=<a href=\"entry://hēliotropium\">heliotropium</a>)《原義 「いぼ取り草」》.</span></div>\r\n","<div class=\"hw\">verrūcōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verruca]</div><div class=\"def\"><num>①</num> いぼの多い, いぼだらけの.</div><div class=\"def\"><num>②</num> (文体が)ごつごつした, 洗練されていない.</div>\r\n","<div class=\"hw\">Verrūgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"def\">ウェッルーゴー《Latium の Volsci 族の町》.</div>\r\n","<div class=\"hw\">versicapillus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[versus<SUP>1</SUP>/capillus]</div><div class=\"def\">白髪<SUB>しらが</SUB>混じりになった.</div>\r\n","<div class=\"hw\">versicolor</div><div class=\"pos\">-ōris, <i>adj</i></div><div class=\"ori\">[versus<SUP>1</SUP>/color]</div><div class=\"def\"><num>①</num> 変わる色の.</div><div class=\"def\"><num>②</num> 雑色の, 多彩な.</div>\r\n","<div class=\"hw\">versiculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[versus<SUP>3</SUP>]</div><div class=\"def\"><num>①</num> 短い[一行の]書き付け, 短文.</div><div class=\"def\"><num>②</num> 一行の詩;小詩, 短詩.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘カト〙(唱和用)短句.</div>\r\n","<div class=\"hw\">versificus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://versificō\">versificō</a>]</div><div class=\"def\">韻文の, 詩的な.</div><hr><div class=\"hw\">versificus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">詩人.</div>\r\n","<div class=\"hw\">versificātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[versifico]</div><div class=\"def\">韻文(の形)にすること, 作詩法.</div>\r\n","<div class=\"hw\">versificātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://versificō\">versificō</a>]</div><div class=\"def\"><num>①</num> (散文を)韻文にする人.</div><div class=\"def\"><num>②</num> 詩人.</div>\r\n","<div class=\"hw\">versificō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[versus<SUP>3</SUP>/facio]</div><div class=\"def\"><num>①</num> 韻文を書く.</div><div class=\"def\"><num>②</num> 韻文にする.</div>\r\n","<div class=\"hw\">versiformis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[versus<SUP>1</SUP>/forma]</div><div class=\"def\">姿を変える, 変化する.</div>\r\n","<div class=\"hw\">versipellis, vorsip-</div><div class=\"pos\">-is, <i>m(f)</i></div><div class=\"ori\">[versus<SUP>1</SUP>/pellis]</div><div class=\"def\"><num>①</num> 姿形を変えられる者, 変幻自在の人.</div><div class=\"def\"><num>②</num> 狼男.</div>\r\n","<div class=\"hw\">versor (古形 vorsor)</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"def\"><num>①</num> 歩きまわる;(頻繁に)出入り[行き来]する.</div><div class=\"def\"><num>②</num> (ある場所に)とどまる, 時を過ごす.</div><div class=\"def\"><num>③</num> (ある状況が)存在[存続]する, (ある活動が)進行中である.</div><div class=\"def\"><num>④</num> (考えが念頭を)離れない, (思いが)去来する</div><div class=\"ex\"><i>cujus os mihi ante oculos versatur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼の顔が私の眼前に浮かぶ</span></div><div class=\"ex\"><i>meae crudelitatis metus in ore omnium versabitur</i> (<author>T<small>AC</small></author>)<span class=\"ext\">私の残虐性への恐怖がすべての人々の口にのぼり続けるだろう.</span></div><div class=\"def\"><num>⑤</num> (ある状態に)ある, 巻き込まれている</div><div class=\"ex\"><i>in maximo errore versari</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大きな誤りを犯している</span></div><div class=\"ex\"><i>semper in laude versatus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">常に賞賛を浴びて.</span></div><div class=\"def\"><num>⑥</num> (人が)...に従事する</div><div class=\"ex\"><i>in omnibus artibus versatur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼はあらゆる学芸にたずさわっている.</span></div><div class=\"def\"><num>⑦</num> (物が)...に関わる, ...に関係する</div><div class=\"ex\"><i>omnes artes in veri investigatione versantur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すべての学芸は真理の探求に関わっている.</span></div>\r\n","<div class=\"hw\">versum</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://versus\">versus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">versus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://verrō\">verro</a>, <a href=\"entry://vertō\">verto</a>.</div><hr><div class=\"hw\">versus<SUP>2</SUP> (古形 vorsus), versum (古形 vorsum)</div><div class=\"pos\"><i>adv</i>(<i>pp</i>)</div><div class=\"ori\">[verto]</div><div class=\"def\">...の方向へ, ...へ向かって(常に後置される)</div><div class=\"ex\">(ad [in]+<i>acc</i>)<i>in forum ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">フォルムの方へ</span></div><div class=\"ex\"><i>ad Oceanum ～</i> (<author>C<small>AES</small></author>)<span class=\"ext\">大洋へ向かって</span></div><div class=\"ex\">(都市・小島の <i>acc</i> と)<i>Romam ～</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ローマへ向けて</span></div><div class=\"ex\">(他の <i>adv</i> と)<i>sursum ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">上方に</span></div><div class=\"ex\"><i>deorsum versum</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">下方に.</span></div><hr><div class=\"hw\">versus<SUP>3</SUP> (古形 vorsus)</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> (畑の)畝<SUB>うね</SUB>溝.</div><div class=\"def\"><num>②</num> 並んでいるもの, 列.</div><div class=\"def\"><num>③</num> (書きものの)一行;詩行</div><div class=\"ex\"><i>Graeci versūs</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ギリシア(語)の詩.</span></div><div class=\"def\"><num>④</num> サヨナキドリの鳴き声[歌声].</div><div class=\"def\"><num>⑤</num> 土地測量単位(=10, 000平方 pedes).</div><div class=\"def\"><num>⑥</num> (踊りの)旋回するステップ.</div>\r\n","<div class=\"hw\">versābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[verso]</div><div class=\"def\"><num>①</num> 向きを変えることができる.</div><div class=\"def\"><num>②</num> (運・状況が)変わりやすい, 一定しない.</div>\r\n","<div class=\"hw\">versābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verso]</div><div class=\"def\">回転する, 旋回する.</div>\r\n","<div class=\"hw\">versātilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[verso]</div><div class=\"def\"><num>①</num> (支軸の上で)旋回[回転]する.</div><div class=\"def\"><num>②</num> 多才な, 応用の利く.</div>\r\n","<div class=\"hw\">versātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[verso]</div><div class=\"def\"><num>①</num> 回転.</div><div class=\"def\"><num>②</num> 変転.</div>\r\n","<div class=\"hw\">versātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[verso, versor]</div><div class=\"def\">経験を積んだ, 熟練した.</div>\r\n","<div class=\"hw\">versō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> 回し続ける, 回転させる.</div><div class=\"def\"><num>②</num> あちらこちらへと向ける, 向きを変える;ひっくり返す.</div><div class=\"def\"><num>③</num> 追いまわす.</div><div class=\"def\"><num>④</num> かきまわす, かき混ぜる</div><div class=\"ex\"><i>omnium versatur urnā sors</i> (<author>H<small>OR</small></author>)<span class=\"ext\">すべての人々の運命は壺で振り出される.</span></div><div class=\"def\"><num>⑤</num> (武器を)振りまわす.</div><div class=\"def\"><num>⑥</num> (戦車・馬車を)操縦する.</div><div class=\"def\"><num>⑦</num> (土地を)すき[掘り]返す.</div><div class=\"def\"><num>⑧</num> (手足を)あちらこちらへ動かす;(<i>refl</i>)身もだえする.</div><div class=\"def\"><num>⑨</num> 悩ます, 苦しめる.</div><div class=\"def\"><num>⑩</num> 思案を巡らす, あれこれ考える.</div><div class=\"def\"><num>⑪</num> (新しい形をつくるために素材を)こねまわす;(表現の仕方を)変える.</div><div class=\"def\"><num>⑫</num> (発言・態度を)状況に合わせる.</div><div class=\"def\"><num>⑬</num> (考え・行動を)左右する, 操る</div><div class=\"ex\"><i>fortuna utrumque versavit</i> (<author>C<small>AES</small></author>)<span class=\"ext\">運命は二人をもてあそんだ.</span></div><div class=\"def\"><num>⑭</num> 保つ, 持続する.</div><div class=\"def\"><num>⑮</num> 取り扱う.</div>\r\n","<div class=\"hw\">versōria (古形 vorsōria)</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[verto]</div><div class=\"def\">帆脚索<SUB>ほあしづな</SUB>.</div>\r\n","<div class=\"hw\">versūra (古形 vorsūra)</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> 回転.</div><div class=\"def\"><num>②</num> (犂<SUB>すき</SUB>を引く牛が向きを変える)畝<SUB>うね</SUB>の端.</div><div class=\"def\"><num>③</num> 角<SUB>かど</SUB>, 隅<SUB>すみ</SUB>;突出部;屈曲部.</div><div class=\"def\"><num>④</num> 舞台脇, そで.</div><div class=\"def\"><num>⑤</num> (借金返済のため他から)新しい借金をすること.</div>\r\n","<div class=\"hw\">versūtia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[versutus]</div><div class=\"def\">狡猾, 奸策, 策略.</div>\r\n","<div class=\"hw\">versūtiloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://versūtus\">versūtus</a>/loquor]</div><div class=\"def\">ことば巧みな, ずるい.</div>\r\n","<div class=\"hw\">versūtus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[versus<SUP>3</SUP>]</div><div class=\"def\"><num>①</num> 巧妙な, 器用な.</div><div class=\"def\"><num>②</num> ずるい, 狡猾な.</div>\r\n","<div class=\"hw\">versūtē (古形 vors-)</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[versutus]</div><div class=\"def\">狡猾に, 巧妙に.</div>\r\n","<div class=\"hw\">vertebra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> 関節.</div><div class=\"def\"><num>②</num> 〘解・動〙椎骨, 脊椎骨.</div>\r\n","<div class=\"hw\">vertebrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vertebra\">vertebra</a>]</div><div class=\"def\"><num>①</num> 関節のある.</div><div class=\"def\"><num>②</num> 接合された;可動の.</div>\r\n","<div class=\"hw\">vertex (古形 vort-)</div><div class=\"pos\">-ticis, <i>m</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> 渦, 渦巻.</div><div class=\"def\"><num>②</num> 旋風, つむじ風.</div><div class=\"def\"><num>③</num> 頭頂, 頭</div><div class=\"ex\"><i>toto vertice supra esse</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">頭一つ分(背が他より)高い.</span></div><div class=\"def\"><num>④</num> 頂点, 頂き;天頂</div><div class=\"ex\"><i>a vertice</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">真上から.</span></div><div class=\"def\"><num>⑤</num> 天極.</div>\r\n","<div class=\"hw\">verticula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> 〘解〙関節.</div><div class=\"def\"><num>②</num> (機械の)接合部.</div>\r\n","<div class=\"hw\">verticulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[verto]</div><div class=\"def\">〘解〙腸の皺襞<SUB>しゅうへき</SUB>.</div>\r\n","<div class=\"hw\">verticulus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[verto]</div><div class=\"def\"><num>①</num> 関節.</div><div class=\"def\"><num>②</num> 〘医〙套管<SUB>とうかん</SUB>[カニューレ]の太い方の端.</div>\r\n","<div class=\"hw\">verticālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vertex]</div><div class=\"def\"><num>①</num> 鉛直の, 垂直の.</div><div class=\"def\"><num>②</num> 〘解・動〙頭頂の.</div>\r\n","<div class=\"hw\">verticōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vertex]</div><div class=\"def\">渦巻の多い.</div>\r\n","<div class=\"hw\">vertragus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Gallia の猟犬.</div>\r\n","<div class=\"hw\">Vertumnus (古形 Vort-)</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘神話〙ウェルトゥムヌス《もともと Etruria 人の神;ローマ人は(動詞 verto と結びつけ)移り変わる一年の神, さらにはあらゆる変化・交易・商売の神とみなして崇めた》.</div>\r\n","<div class=\"hw\">vertī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vertō\">verto</a>.</div>\r\n","<div class=\"hw\">vertīginor</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://vertīgō\">vertīgō</a>]</div><div class=\"def\">めまいがする.</div>\r\n","<div class=\"hw\">vertīginō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[vertigo]</div><div class=\"def\">(カメレオンの目玉が左右ばらばらに)回る.</div>\r\n","<div class=\"hw\">vertīgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vertō\">vertō (古形 vortō)</a>]</div><div class=\"def\"><num>①</num> 回転, 旋回.</div><div class=\"def\"><num>②</num> 変転, 成り行き.</div><div class=\"def\"><num>③</num> めまい</div><div class=\"ex\"><SUP>◇</SUP><i>～ epileptica</i><span class=\"ext\">〘病〙てんかん性眩暈<SUB>げんうん</SUB>.</span></div>\r\n","<div class=\"hw\">vertō (古形 vortō)</div><div class=\"pos\">-ere versī versum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 回す, 向きを変える</div><div class=\"ex\"><i>ora huc et huc vertit</i> (<author>H<small>OR</small></author>)<span class=\"ext\">顔をあちらへこちらへと向ける</span></div><div class=\"ex\"><i>stilum vertere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">鉄筆の向きを(とがっている方から平らな方へ)変える(=蝋板の文字をこすって消す)</span></div><div class=\"ex\">(<i>pass</i> で再帰的に)<i>vertitur caelum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">天が回転する</span></div><div class=\"ex\"><i>ad lapidem verti</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">石(像)に向かって立つ.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>hostem in fugam vertere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">〘軍〙敵を敗走させる</span></div><div class=\"ex\"><i>terga vertere</i> (<author>C<small>AES</small></author>) =<i>se vertere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">(敵に)背中を見せる(=逃げる).</span></div><div class=\"def\"><num>③</num> (ある方向へ)向かわせる</div><div class=\"ex\"><i>di bene vortant quod agas</i> (<author>T<small>ER</small></author>)<span class=\"ext\">神々があなたの企てを成功させて下さいますように</span></div><div class=\"ex\"><i>quo se verteret</i>, <i>non habebat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼はどちらを向けば(=どちら側に加担すれば)よいのか分らなかった</span></div><div class=\"def\">(<i>pp</i>)(ある方向を)向いた</div><div class=\"ex\"><i>insulae in Africam versae</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">Africa に面する島々.</span></div><div class=\"def\"><num>④</num> ひっくり返す, 倒す</div><div class=\"ex\"><i>ab imo moenia Trojae vertere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">Troja の城壁を基石からくつがえす.</span></div><div class=\"def\"><num>⑤</num> (土地を)掘り返す.</div><div class=\"def\"><num>⑥</num> 変える, 変形させる</div><div class=\"ex\"><i>natura cibos in corpora viva vertit</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">自然は食物を生きた肉体に変える</span></div><div class=\"ex\">(<i>pass</i> で再帰的に)<i>in rabiem coepit verti jocus</i> (<author>H<small>OR</small></author>)<span class=\"ext\">冗談が憤怒に変わり始める.</span></div><div class=\"def\"><num>⑦</num> 取り換える, 交換する</div><div class=\"ex\"><i>solum vertere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">亡命する.</span></div><div class=\"def\"><num>⑧</num> 翻訳する;言い換える.</div><div class=\"def\"><num>⑨</num> ...とみなす, 解する</div><div class=\"ex\"><i>ea in suam contumeliam vertit</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼はそれを自分への侮辱と受け止める.</span></div><div class=\"def\"><num>⑩</num> (<i>pass</i> で再帰的に)(できごとなどが)起きる, 展開する;...次第である</div><div class=\"ex\"><i>omnia in unius potestate vertuntur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すべては一個人の権力にかかっている</span></div><div class=\"ex\"><i>spes civitatis in dictatore vertitur</i> (<author>L<small>IV</small></author>)<span class=\"ext\">国家の希望は独裁官に依存している.</span></div><div class=\"def\"><num>⑪</num> ...に帰する</div><div class=\"ex\"><i>fames in deum iras vertere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">飢饉を神々の怒りのせいにする.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 向く, 向かう</div><div class=\"ex\"><i>in fugam vertere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">逃げ出す</span></div><div class=\"ex\"><i>alio vertunt</i> (<author>T<small>AC</small></author>)<span class=\"ext\">彼ら(の考え)は別の方向に向かう.</span></div><div class=\"def\"><num>②</num> ...の結果になる</div><div class=\"ex\"><i>ut detrimentum in bonum verteret</i> (<author>C<small>AES</small></author>)<span class=\"ext\">禍いが転じて福となるように.</span></div><div class=\"def\"><num>③</num> 回る, 変わる</div><div class=\"ex\"><i>jam verterat fortuna</i> (<author>L<small>IV</small></author>)<span class=\"ext\">運命はすでに転じてしまった</span></div><div class=\"ex\"><i>totae solidam in glaciem vertēre lacunae</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">池全体が固い氷に変わった.</span></div><div class=\"def\"><num>④</num> (<i>prp</i> vertens)巡る</div><div class=\"ex\"><i>anno vertente</i> (<author>C<small>IC</small></author>)<span class=\"ext\">まる一年経つうちに</span></div><div class=\"ex\"><i>annus vertens</i> (<author>C<small>IC</small></author>)<span class=\"ext\">「一巡りの年」《すべての星がいったん出発した元の地点に戻って, 天全体に同じ配置が再現されるまでの36, 000年の周期》.</span></div>\r\n","<div class=\"hw\">veru</div><div class=\"pos\">-ūs, <i>n</i></div><div class=\"def\"><num>①</num> 鉄串, 焼き串.</div><div class=\"def\"><num>②</num> 投げ槍.</div><div class=\"def\"><num>③</num> (<i>pl</i>)《碑》忍び返しのついた柵<SUB>さく</SUB>.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(写本の)疑句標(=<a href=\"entry://obelus\">obelus</a>).</div>\r\n","<div class=\"hw\">Verulae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ウェルラエ《Latium の Hernici 族の町;現 Veroli》.</div>\r\n","<div class=\"hw\">Verulamium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ウェルラミウム《Britannia の町;Londinium の北西にあった;現 St. Albans》.</div>\r\n","<div class=\"hw\">Verulānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Verulae の.</div>\r\n","<div class=\"hw\">veruīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://veru\">veru</a>]</div><div class=\"def\">鉄串.</div>\r\n","<div class=\"hw\">vervex, verbex</div><div class=\"pos\">-ēcis, <i>m</i></div><div class=\"def\"><num>①</num> (去勢された)雄羊.</div><div class=\"def\"><num>②</num> 愚か者, ばか.</div>\r\n","<div class=\"hw\">Vervēceus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vervex]</div><div class=\"def\">雄羊の姿をした《Juppiter Ammon の呼称》.</div>\r\n","<div class=\"hw\">vervēcīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vervex\">vervex, verbex</a>]</div><div class=\"def\">(去勢された)雄羊の.</div>\r\n","<div class=\"hw\">verēcundia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[verecundus]</div><div class=\"def\"><num>①</num> 控え目, 慎しみ;内気, 遠慮.</div><div class=\"def\"><num>②</num> 敬意, 尊敬</div><div class=\"ex\">～ <i>deorum</i> (<author>L<small>IV</small></author>)<span class=\"ext\">敬神の念.</span></div><div class=\"def\"><num>③</num> 廉恥心;恥じらい</div><div class=\"ex\"><i>privatis dictatorem poscere reum verecundiae non fuit</i> (<author>L<small>IV</small></author>)<span class=\"ext\">一般の市民たちには独裁官の弾劾を求めることは恥ではなかった(=彼らは臆面もなく弾劾を求めた)《verecundiae は <i>predic dat</i>》.</span></div>\r\n","<div class=\"hw\">verēcundor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://verēcundus\">verēcundus</a>]</div><div class=\"def\">控え目である, 慎しみ深い, 恥ずかしがる 〈+<i>inf</i>〉</div><div class=\"ex\"><i>verecundari in publicum prodire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">人前へ出たがらない.</span></div>\r\n","<div class=\"hw\">verēcundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vereor]</div><div class=\"def\"><num>①</num> 控え目な, 慎しみ深い</div><div class=\"ex\"><i>in appentendis honoribus inmodicus</i>, <i>in gerendis verecundissimus</i> (<author>V<small>ELL</small></author>)<span class=\"ext\">官職の獲得にはなんの遠慮もないが, (権力の)行使にはきわめて控え目な.</span></div><div class=\"def\"><num>②</num> 恥を知る;恥ずかしがりの</div><div class=\"ex\">～ <i>vultus</i> (<author>O<small>V</small></author>)<span class=\"ext\">恥ずかしそうな顔.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 尊敬すべき.</div>\r\n","<div class=\"hw\">verēcundē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[verecundus]</div><div class=\"def\">控え目に, 慎しみ深く, 遠慮して.</div>\r\n","<div class=\"hw\">verēdus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 駅馬, 早馬.</div><div class=\"def\"><num>②</num> (狩猟用の)駿馬.</div>\r\n","<div class=\"hw\">verēdārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://verēdus\">verēdus</a>]</div><div class=\"def\"><num>①</num> 《碑》帝室郵便の送達吏.</div><div class=\"def\"><num>②</num> 急使, 伝令.</div><div class=\"def\"><num>③</num> ゴシップ好きの聖職者.</div>\r\n","<div class=\"hw\">verētilla</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://verētrum\">verētrum</a>]</div><div class=\"def\">未詳の海魚《男性器に似ているという》.</div>\r\n","<div class=\"hw\">verētrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vereor]</div><div class=\"def\">男性器.</div>\r\n","<div class=\"hw\">verūtum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://verūtus\">verūtus</a>]</div><div class=\"def\">投げ槍の一種.</div>\r\n","<div class=\"hw\">verūtus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[veru]</div><div class=\"def\"><num>①</num> (串のように)先のとがった.</div><div class=\"def\"><num>②</num> 投げ槍を手にした.</div>\r\n","<div class=\"hw\">Vesbius<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://Vesuvius\">Vesuvius<SUP>1</SUP></a>, <a href=\"entry://Vesuvius\">Vesuvius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Vescia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウェスキア《Latium の Liris 川のほとりの町》.</div>\r\n","<div class=\"hw\">vescor</div><div class=\"pos\">-scī, <i>intr</i>, <i>tr dep</i></div><div class=\"def\"><num>①</num> 食べる, 食事をする 〈re;alqd〉</div><div class=\"ex\"><i>lacte caseo carne vesci</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ミルク, チーズ, 肉を常食とする</span></div><div class=\"ex\"><i>apri in morbis sibi medentur cancros vescendo</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">イノシシは病気になるとカニを食べて自分を癒す.</span></div><div class=\"def\"><num>②</num> 利用する, 享受する 〈re〉</div><div class=\"ex\"><i>vesci vitalibus auris</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">命を支える空気を享受する.</span></div><div class=\"def\"><num>③</num> 〘法〙扶養する, 養育する.</div>\r\n","<div class=\"hw\">vesculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://vescus\">vescus</a>]</div><div class=\"def\">弱々しい, やせた.</div>\r\n","<div class=\"hw\">vescus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vescor]</div><div class=\"def\"><num>①</num> やせた, 細い, 小さな.</div><div class=\"def\"><num>②</num> かじる, むしばむ</div><div class=\"ex\"><i>vescum sal</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">(岩を)むしばむ(海水中の)塩分.</span></div>\r\n","<div class=\"hw\">vescī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://vescor\">vescor</a>.</div>\r\n","<div class=\"hw\">Vescīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vescia の.</div><div class=\"hw2\"><b>Vescīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Vescia の住民.</div>\r\n","<div class=\"hw\">Veseris</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ウェセリス《Campania の Vesuvius 山麓の小さな川》.</div>\r\n","<div class=\"hw\">Vesontiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ウェソンティオー《Gallia Celtica の Sequani 族の町;現 Besançon》.</div>\r\n","<div class=\"hw\">vespa<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘動〙スズメバチ(雀蜂).</div><hr><div class=\"hw\">vespa<SUP>2</SUP></div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://vespillō\">vespillo 1</a>.</div>\r\n","<div class=\"hw\">Vespasiānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェスパシアーヌス《<i>T. Flavius ～</i>, ローマ皇帝(9‐79;在位69‐79)》.</div>\r\n","<div class=\"hw\">vesper</div><div class=\"pos\">-erī [-eris], <i>m</i></div><div class=\"def\"><num>①</num> 夕方, 晩</div><div class=\"ex\"><i>vespere</i>(abl)=<i>vesperi</i>(loc)(<author>C<small>IC</small></author>)<span class=\"ext\">夕方に.</span></div><div class=\"def\"><num>②</num> 〘天〙金星, 宵の明星.</div><div class=\"def\"><num>③</num> 西方;西方の住民.</div>\r\n","<div class=\"hw\">vespera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 夕方, 晩, 夕暮れ</div><div class=\"ex\"><i>vesperā</i>(abl)(<author>P<small>LIN</small></author>)<span class=\"ext\">夕方に.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(<i>pl</i>)〘カト〙夕の祈り, 晩課.</div>\r\n","<div class=\"hw\">vesperascō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[vesper]</div><div class=\"def\">夕方になる, 日が暮れる.</div>\r\n","<div class=\"hw\">vesperna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vesper]</div><div class=\"def\">夕食.</div>\r\n","<div class=\"hw\">vespertiliō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[vesper]</div><div class=\"def\">〘動〙コウモリ(蝙蝠).</div>\r\n","<div class=\"hw\">vespertīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vesper]</div><div class=\"def\"><num>①</num> 夕方の</div><div class=\"ex\"><i>vespertinae litterae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">夕方受け取った手紙.</span></div><div class=\"def\"><num>②</num> 西の, 西方にある.</div>\r\n","<div class=\"hw\">vesperus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vespera]</div><div class=\"def\">夕方の.</div>\r\n","<div class=\"hw\">vesperālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vespera\">vespera</a>]</div><div class=\"def\">夕方の;西の.</div>\r\n","<div class=\"hw\">vesperūgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[vesper]</div><div class=\"def\"><num>①</num> 〘天〙金星, 宵の明星.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘動〙コウモリ(=<a href=\"entry://vespertiliō\">vespertilio</a>).</div>\r\n","<div class=\"hw\">vespillō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\"><num>①</num> (極貧者のための)死体埋葬人夫.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 墓荒し.</div>\r\n","<div class=\"hw\">Vesta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘神話〙ウェスタ《Saturnus と Ops の娘で, 炉・家庭生活の女神;ギリシア神話の Hestia に当たる》.</div><div class=\"def\"><num>②</num> 炉の神聖な火.</div><div class=\"def\"><num>③</num> Vesta の神殿.</div>\r\n","<div class=\"hw\">vester<SUP>1</SUP> (古形 voster)</div><div class=\"pos\">-tra -trum, <i>adj poss</i></div><div class=\"ori\">[vos]</div><div class=\"def\">あなた方の(<i>cf. </i> tuus)</div><div class=\"ex\"><i>majores vestri</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなた方の父祖</span></div><div class=\"ex\">(vos の <i>object gen</i> vestri の代わりに)<i>odio vestro</i> (<author>L<small>IV</small></author>)<span class=\"ext\">あなた方に対する憎しみから.</span></div><hr><div class=\"hw\">vester<SUP>2</SUP> (古形 voster)</div><div class=\"pos\">-trī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://vester\">vester<SUP>1</SUP> (古形 voster)</a>]</div><div class=\"def\"><num>①</num> おまえたちの主人.</div><div class=\"def\"><num>②</num> (<i>pl</i>)あなた方の学派[党派].</div>\r\n","<div class=\"hw\">vestibulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (建物の)前庭.</div><div class=\"def\"><num>②</num> 入口の間, 玄関のホール.</div><div class=\"def\"><num>③</num> 出だし, 端緒.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解・動〙前庭, 前房, 前室.</div>\r\n","<div class=\"hw\">vesticeps</div><div class=\"pos\">-cipis, <i>adj</i></div><div class=\"ori\">[vestis/capio<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 薄ひげの生えた, 思春期に達した.</div><div class=\"def\"><num>②</num> (皮肉として)堕落した.</div>\r\n","<div class=\"hw\">vestiplica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vestis\">vestis</a>/plico]</div><div class=\"def\">衣服を折りたたんでしわのばしをする女奴隷.</div>\r\n","<div class=\"hw\">vestis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 衣服, 衣装</div><div class=\"ex\"><i>vestem mutare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">喪服に着替える.</span></div><div class=\"def\"><num>②</num> おおい;敷物.</div><div class=\"def\"><num>③</num> ヘビのぬけがら.</div><div class=\"def\"><num>④</num> クモの巣.</div>\r\n","<div class=\"hw\">vestispica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vestis\">vestis</a>/specio]</div><div class=\"def\">衣装番女奴隷, 小間使い.</div>\r\n","<div class=\"hw\">vestiārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vestiārius\">vestiārius<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 衣装だんす.</div><div class=\"def\"><num>②</num> 衣服, 着物.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 衣装部屋.</div>\r\n","<div class=\"hw\">vestiārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vestis]</div><div class=\"def\">衣服の, 衣服に関する.</div><hr><div class=\"hw\">vestiārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 衣服商.</div><div class=\"def\"><num>②</num> 《碑》衣装番の奴隷.</div>\r\n","<div class=\"hw\">vestiō</div><div class=\"pos\">-īre -īvī -ītum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[vestis]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> (衣服を)着せる.</div><div class=\"def\"><num>②</num> おおう, 包む.</div><div class=\"def\"><num>③</num> (考えをことばで)表現する.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)装う, 着用する.</div>\r\n","<div class=\"hw\">vestrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vester<SUP>1</SUP>]</div><div class=\"def\">あなた方の財産[お金].</div>\r\n","<div class=\"hw\">vestrās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vester<SUP>1</SUP>]</div><div class=\"def\">あなた方の家族[国]の.</div>\r\n","<div class=\"hw\">Vestālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://Vestālis\">Vestālis<SUP>1</SUP></a>]</div><div class=\"def\">Vesta の祭典《6月9日に行なわれた》.</div>\r\n","<div class=\"hw\">Vestālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> Vesta の</div><div class=\"ex\"><i>virgo</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">Vesta の巫女<SUB>みこ</SUB>.</span></div><div class=\"def\"><num>②</num> Vesta の巫女の.</div><div class=\"def\"><num>③</num> 貞淑な.</div><hr><div class=\"hw\">Vestālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">(<i>sc. </i> virgo)Vesta の巫女.</div>\r\n","<div class=\"hw\">vestīgium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vestīgō\">vestīgō</a>]</div><div class=\"def\"><num>①</num> (人・動物が通った)跡, 足跡.</div><div class=\"def\"><num>②</num> 地点, 場所</div><div class=\"ex\"><i>eodem vestigio remanere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">同じ場所にとどまる.</span></div><div class=\"def\"><num>③</num> 痕跡, 名残り</div><div class=\"ex\"><i>vestigia urbis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">町の廃墟.</span></div><div class=\"def\"><num>④</num> 足の裏.</div><div class=\"def\"><num>⑤</num> 時点</div><div class=\"ex\"><i>in illo vestigio temporis</i> (<author>C<small>AES</small></author>)<span class=\"ext\">その瞬間に</span></div><div class=\"ex\"><i>e vestigio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">直ちに, 即刻.</span></div>\r\n","<div class=\"hw\">vestīgātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vestigo]</div><div class=\"def\"><num>①</num> (獣などの跡を)追う人, 猟師.</div><div class=\"def\"><num>②</num> 密告者.</div>\r\n","<div class=\"hw\">vestīgō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 足跡を追う;探索する.</div><div class=\"def\"><num>②</num> 捜し出す, 発見する.</div>\r\n","<div class=\"hw\">vestīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vestis]</div><div class=\"def\"><num>①</num> 衣服, 衣装.</div><div class=\"def\"><num>②</num> 掛け布;敷物.</div>\r\n","<div class=\"hw\">Vestīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vestini 族の.</div>\r\n","<div class=\"hw\">Vestīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウェスティーニー《Appenninus 山脈中部の東側にいた一部族》.</div>\r\n","<div class=\"hw\">vestītus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vestio]</div><div class=\"def\">盛装した, 着飾った.</div><hr><div class=\"hw\">vestītus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 衣服, 衣装</div><div class=\"ex\"><i>mutare vestitum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">喪服に着替える</span></div><div class=\"ex\"><i>redire ad vestitum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(喪服から)再び普段の衣服を着る.</span></div><div class=\"def\"><num>②</num> (自然の)おおい</div><div class=\"ex\"><i>riparum vestitūs viridissimi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">土堤をおおう緑したたる若草.</span></div><div class=\"def\"><num>③</num> 文飾.</div>\r\n","<div class=\"hw\">Vesulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェスルス《Liguria の山;現 Monte Viso》.</div>\r\n","<div class=\"hw\">Vesuvius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Vesuvīnus\">Vesuvinus</a>.</div><hr><div class=\"hw\">Vesuvius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェスウィウス《Campania の Neapolis 東方の活火山;79年の噴火は Pompeii, Herculaneum を埋没させた;現 Vesuvio》.</div>\r\n","<div class=\"hw\">Vesuvīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vesuvius の.</div>\r\n","<div class=\"hw\">Vesvius<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://Vesuvius\">Vesuvius<SUP>1</SUP></a>, <a href=\"entry://Vesuvius\">Vesuvius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Vesēvus<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://Vesuvius\">Vesuvius<SUP>1</SUP></a>, <a href=\"entry://Vesuvius\">Vesuvius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Vetera</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"def\">(<i>sc. </i> castra)ウェテラ《Gallia Belgica の Rhenus 川沿いの町》.</div>\r\n","<div class=\"hw\">vetera</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"ori\">[vetus]</div><div class=\"def\">古い事物, 過去のできごと, 伝統.</div>\r\n","<div class=\"hw\">veterascō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[vetus]</div><div class=\"def\">古くなる, 年を経る.</div>\r\n","<div class=\"hw\">veternus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vetus]</div><div class=\"def\"><num>①</num> 老年, 老齢.</div><div class=\"def\"><num>②</num> 病的な眠気[倦怠感], 昏睡;(熊の)冬眠.</div><div class=\"def\"><num>③</num> 無気力, 無為, 怠惰.</div><div class=\"def\"><num>④</num> 古い汚物の山.</div>\r\n","<div class=\"hw\">veternōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://veternus\">veternus</a>]</div><div class=\"def\"><num>①</num> 昏睡(状態)の, 眠くてたまらない.</div><div class=\"def\"><num>②</num> 無気力な, 不活発な.</div>\r\n","<div class=\"hw\">veterāmentārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">古物を扱う</div><div class=\"ex\"><i>～ sutor</i> (<author>S<small>UET</small></author>)<span class=\"ext\">古靴直し.</span></div>\r\n","<div class=\"hw\">veterānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vetus]</div><div class=\"def\"><num>①</num> 経験豊かな;古参の.</div><div class=\"def\"><num>②</num> (動植物が)成熟した.</div><hr><div class=\"hw\">veterānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 古参兵, 老兵.</div><div class=\"def\"><num>②</num> 老練家.</div>\r\n","<div class=\"hw\">veterārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://veterārius\">veterārius</a>]</div><div class=\"def\">(成熟させるための)ぶどう酒貯蔵室.</div>\r\n","<div class=\"hw\">veterārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vetus]</div><div class=\"def\">(ぶどう酒が)古い, 熟成した</div><div class=\"ex\"><i>vina veteraria</i> (<author>S<small>EN</small></author>)<span class=\"ext\">年代物のぶどう酒.</span></div>\r\n","<div class=\"hw\">veterātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vetero]</div><div class=\"def\"><num>①</num> 老練家, 経験豊かな人.</div><div class=\"def\"><num>②</num> 老獪<SUB>ろうかい</SUB>なやつ, 古だぬき.</div><div class=\"def\"><num>③</num> 老奴隷.</div>\r\n","<div class=\"hw\">veterātrix</div><div class=\"pos\">-īcis, <i>adj f</i></div><div class=\"ori\">[veterator]</div><div class=\"def\">(魔法に)通じた.</div>\r\n","<div class=\"hw\">veterātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vetero]</div><div class=\"def\">古くなった;慢性の.</div>\r\n","<div class=\"hw\">veterātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[veterator]</div><div class=\"def\">狡猾な;巧妙な.</div>\r\n","<div class=\"hw\">veterātōriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://veterātōrius\">veterātōrius</a>]</div><div class=\"def\">巧みに, 手際よく.</div>\r\n","<div class=\"hw\">veterēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[vetus]</div><div class=\"def\"><num>①</num> 先人, 古人;祖先.</div><div class=\"def\"><num>②</num> 古い著述家たち.</div>\r\n","<div class=\"hw\">Veterēs</div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"def\">(<i>sc. </i> tabernae)ローマ市の Forum の南側の商店街《「老舗街」 の意》.</div>\r\n","<div class=\"hw\">veterīnae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>veterīna</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[veterinus]</div><div class=\"def\">荷車役用家畜, 駄獣.</div>\r\n","<div class=\"hw\">veterīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vetus]</div><div class=\"def\"><num>①</num> 荷物を運ぶ</div><div class=\"ex\"><i>bestia veterina</i> (<author>C<small>ATO</small></author>)<span class=\"ext\">駄獣.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 駄獣の.</div>\r\n","<div class=\"hw\">veterīnārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[veterinus]</div><div class=\"def\">駄獣の医療に関わる.</div><hr><div class=\"hw\">veterīnārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(<i>sc. </i> medicus)獣医.</div>\r\n","<div class=\"hw\">veterō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[vetus]</div><div class=\"def\">古くさせる, 陳腐にする.</div>\r\n","<div class=\"hw\">vetitum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vetitus\">vetitus</a>]</div><div class=\"def\"><num>①</num> 禁止事項.</div><div class=\"def\"><num>②</num> 禁令, 禁止.</div>\r\n","<div class=\"hw\">vetitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vetō\">veto</a>.</div>\r\n","<div class=\"hw\">Vettōnēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ウェットーネース《Lusitania にいた一部族》.</div>\r\n","<div class=\"hw\">vetula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vetulus\">vetulus<SUP>1</SUP></a>]</div><div class=\"def\">初老の女性.</div>\r\n","<div class=\"hw\">vetulus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[vetus]</div><div class=\"def\">(人・動物が)やや老いた;(物が)やや古い.</div><hr><div class=\"hw\">vetulus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"def\">初老の男性.</div>\r\n","<div class=\"hw\">Veturius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェトゥリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">vetus</div><div class=\"pos\">-teris(<i>comp</i> veterior, <i>superl</i> veterrimus), <i>adj</i></div><div class=\"def\"><num>①</num> 年を取った, 老齢の.</div><div class=\"def\"><num>②</num> 古い, 長年の;慢性の.</div><div class=\"def\"><num>③</num> 昔の, 過去の.</div><div class=\"def\"><num>④</num> 老練な, 経験を積んだ 〈+<i>gen</i>〉</div><div class=\"ex\">～ <i>miles</i> (<author>C<small>IC</small></author>)<span class=\"ext\">古参兵</span></div><div class=\"ex\">～ <i>regnandi</i> (<author>T<small>AC</small></author>)<span class=\"ext\">支配の経験豊かな.</span></div>\r\n","<div class=\"hw\">vetustescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↓<a href=\"entry://vetustus\">vetustus</a>]</div><div class=\"def\">(ぶどう酒が)熟成する.</div>\r\n","<div class=\"hw\">vetustus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vetus]</div><div class=\"def\"><num>①</num> (事物が)古い, 年を経た, 長期にわたる;(病気が)慢性の.</div><div class=\"def\"><num>②</num> (人が)古参の, 年長の.</div><div class=\"def\"><num>③</num> 太古の, 大昔の.</div><div class=\"def\"><num>④</num> 古風な, 古体の.</div>\r\n","<div class=\"hw\">vetustās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vetus\">vetus</a>]</div><div class=\"def\"><num>①</num> 老年, 高齢.</div><div class=\"def\"><num>②</num> 古いこと;長年, 長期の継続[経験];(病気の)慢性.</div><div class=\"def\"><num>③</num> 太古(の人々・制度), 古い伝承.</div><div class=\"def\"><num>④</num> 遠い未来, 後世.</div>\r\n","<div class=\"hw\">vetustē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vetustus]</div><div class=\"def\">昔風に.</div>\r\n","<div class=\"hw\">vetuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vetō\">veto</a>.</div>\r\n","<div class=\"hw\">vetō</div><div class=\"pos\">-āre -tuī -titum, <i>tr</i></div><div class=\"def\">禁止する, 拒否する, 妨げる 〈+<i>acc</i>;+<i>inf</i>;<i>+acc c</i>. <i>inf</i>;ne〉</div><div class=\"ex\"><i>vetuit me tali voce</i> (<author>H<small>OR</small></author>)<span class=\"ext\">彼は次のように言って私を制した</span></div><div class=\"ex\"><i>bella vetare</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">戦に反対する</span></div><div class=\"ex\"><i>lex vetat delinquere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">法は悪業を禁ずる</span></div><div class=\"ex\"><i>ab opere legatos discedere vetuerat</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼は副官たちに作業の現場から離れるなと命じておいた</span></div><div class=\"ex\"><i>edicto vetuit ne quis se praeter Apellen pingueret</i> (<author>H<small>OR</small></author>)<span class=\"ext\">(王は)Apelles 以外は誰も自分を描いてはならぬと法令で禁止した.</span></div>\r\n","<div class=\"hw\">vexillifer</div><div class=\"pos\">-fera -ferum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vexillum\">vexillum</a>/fero]</div><div class=\"def\">軍旗を持っている.</div>\r\n","<div class=\"hw\">vexillum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[velum]</div><div class=\"def\"><num>①</num> 軍旗.</div><div class=\"def\"><num>②</num> (同じ軍旗の下で戦う)小部隊;分遣隊.</div>\r\n","<div class=\"hw\">vexillārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vexillum]</div><div class=\"def\"><num>①</num> 旗手.</div><div class=\"def\"><num>②</num> (盗賊団の)頭目.</div><div class=\"def\"><num>③</num> (<i>pl</i>)分遣隊.</div>\r\n","<div class=\"hw\">vexillātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vexillum]</div><div class=\"def\"><num>①</num> 分遣隊.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 騎兵隊.</div>\r\n","<div class=\"hw\">vexāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[vexo]</div><div class=\"def\">動揺, 変動.</div>\r\n","<div class=\"hw\">vexātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vexo]</div><div class=\"def\"><num>①</num> 激しく揺する[ゆさぶる]こと, 衝撃(を与えること).</div><div class=\"def\"><num>②</num> 苦しめること, 迫害.</div><div class=\"def\"><num>③</num> 苦痛, 困苦.</div>\r\n","<div class=\"hw\">vexātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vexo]</div><div class=\"def\">苦しめる人, 迫害者.</div>\r\n","<div class=\"hw\">vexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vehō\">veho</a>.</div>\r\n","<div class=\"hw\">vexō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[veho]</div><div class=\"def\"><num>①</num> 絶えず激しい力を加える, 激しく動かす[ゆさぶる];損傷を与える.</div><div class=\"def\"><num>②</num> 虐待する, 迫害する.</div><div class=\"def\"><num>③</num> 荒廃させる;略奪[強奪]する.</div><div class=\"def\"><num>④</num> 苦しめる, 悩ます;(健康を)そこなわせる</div><div class=\"ex\"><i>sollicitudo vexat impios</i> (<author>C<small>IC</small></author>)<span class=\"ext\">不安が不信心者たちをさいなむ.</span></div><div class=\"def\"><num>⑤</num> (ことばで)攻撃する, ののしる.</div>\r\n","<div class=\"hw\">via</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 道, 道路.</div><div class=\"def\"><num>②</num> 通り;街道</div><div class=\"ex\"><i>Sacra</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">(ローマ市内の)聖道</span></div><div class=\"ex\">～ <i>Appia</i> (<author>C<small>IC</small></author>)<span class=\"ext\">アッピア街道《⇒ <a href=\"entry://Appius\">Appius</a>》</span></div><div class=\"ex\">～ <i>Aurelia</i><span class=\"ext\">アウレーリア街道《⇒ <a href=\"entry://Aurēlius\">Aurelius<SUP>2</SUP></a>》.</span></div><div class=\"def\"><num>③</num> 通路.</div><div class=\"def\"><num>④</num> (呼気・血液・食べ物などの通る)管<SUB>くだ</SUB>《気管・血管・食道》.</div><div class=\"def\"><num>⑤</num> 道のり, 旅程, 旅.</div><div class=\"def\"><num>⑥</num> 行程, 行軍.</div><div class=\"def\"><num>⑦</num> (人生の)道, 進路</div><div class=\"ex\">～ <i>vivendi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">人生行路.</span></div><div class=\"def\"><num>⑧</num> 手段, 方法</div><div class=\"ex\">～ <i>laudis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">賞賛を博するための方途</span></div><div class=\"ex\"><i>viā et arte dicere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">体系的かつ理論的に弁論する.</span></div>\r\n","<div class=\"hw\">vians</div><div class=\"pos\">-ontis, <i>m</i>(<i>prp</i>)</div><div class=\"ori\">[vio]</div><div class=\"def\">旅人.</div>\r\n","<div class=\"hw\">vibrissō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">(歌いながら)声を震わせる.</div>\r\n","<div class=\"hw\">vibriō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘細菌〙ビブリオ《コレラの病原菌などのビブリオ属細菌の総称》.</div>\r\n","<div class=\"hw\">vibrācae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">鼻毛.</div>\r\n","<div class=\"hw\">vibrātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vibro]</div><div class=\"def\">きらめく, またたく.</div><hr><div class=\"hw\">vibrātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">きらめき, 輝き.</div>\r\n","<div class=\"hw\">vibrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 震わせる, 震動させる, ゆさぶる</div><div class=\"ex\"><i>flamen vestes vibrare</i> (<author>O<small>V</small></author>)<span class=\"ext\">風が衣服をひらひら翻す.</span></div><div class=\"def\"><num>②</num> (飛び道具を)振りまわす;投げ飛ばす.</div><div class=\"def\"><num>③</num> (ことばを)投げつける.</div><div class=\"def\"><num>④</num> (髪を)縮らす.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 震える, 震動する.</div><div class=\"def\"><num>②</num> 突進する;速く飛ぶ.</div><div class=\"def\"><num>③</num> 閃光を発する, きらめく.</div>\r\n","<div class=\"hw\">vibōnēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">Britannica(<i>sc. </i> herba)と呼ばれる植物の花《扁桃炎の予防に効能があるとされた》.</div>\r\n","<div class=\"hw\">Vica Pota</div><div class=\"pos\">-ae -ae, <i>f</i></div><div class=\"ori\">[vinco, potior<SUP>2</SUP>]</div><div class=\"def\">勝利の女神 Victoria の添え名.</div>\r\n","<div class=\"hw\">vice, vicem</div><div class=\"def\">⇒<a href=\"entry://vicis\">vicis</a>.</div>\r\n","<div class=\"hw\">vicedominus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vicis/dominus]</div><div class=\"def\"><num>①</num> 副王, 太守.</div><div class=\"def\"><num>②</num> 司教領守護職.</div>\r\n","<div class=\"hw\">vicia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙マメ科ソラマメ属の植物《家畜の飼料として栽培された》.</div>\r\n","<div class=\"hw\">Vicilīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vigil<SUP>1</SUP>]</div><div class=\"def\">(Hirpini 族における)Juppiter の添え名《「油断のない者」 の意》.</div>\r\n","<div class=\"hw\">vicis</div><div class=\"pos\">(<i>gen</i>), <i>f</i>(<i>sg nom</i> vicēs は3世紀以前の用例なし, <i>dat</i> vicī(まれ), <i>acc</i> vicem, <i>abl</i> vice;<i>pl nom</i>, <i>acc</i> vicēs, <i>gen</i> 用例なし, <i>dat</i>, <i>abl</i> vicibus)</div><div class=\"def\"><num>①</num> 順番, 引継ぎ, 交代</div><div class=\"ex\"><i>hac vice sermonum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">話を取り交わして</span></div><div class=\"ex\"><i>per vices</i> (<author>O<small>V</small></author>)<span class=\"ext\">交互に</span></div><div class=\"ex\"><i>in vicem [vices]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">交互に, お互いに</span></div><div class=\"ex\"><i>vice versā</i> (<author>S<small>EN</small></author>)<span class=\"ext\">逆に, あべこべに.</span></div><div class=\"def\"><num>②</num> 人生の浮き沈み, 運命.</div><div class=\"def\"><num>③</num> 返報, 報復</div><div class=\"ex\"><i>redde vicem meritis</i> (<author>O<small>V</small></author>)<span class=\"ext\">報いを受けて当然の人々に仕返ししてやりなさい.</span></div><div class=\"def\"><num>④</num> 地位, 役割, 任務</div><div class=\"ex\"><i>vestram vicem explete</i> (<author>T<small>AC</small></author>)<span class=\"ext\">諸君の義務を果たしてくれ.</span></div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 度, 回</div><div class=\"ex\"><i>alterā vice</i> (<author>V<small>ULG</small></author>)<span class=\"ext\">2度も.</span></div><div class=\"def\"><num>⑥</num> (副詞的用法)</div><div class=\"def\"><num1>⒜</num1> vicem (1) ...の代わりに, ...のために 〈+<i>gen</i>;+<i>adj pers</i>〉</div><div class=\"ex\"><i>eri vicem</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">主人に代わって</span></div><div class=\"ex\"><i>tuam vicem doleo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はあなたの不幸を気の毒に思っている.</span></div><div class=\"def\"> (2) ...のように 〈+<i>gen</i>〉</div><div class=\"ex\"><i>vicem pecorum</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">家畜のように.</span></div><div class=\"def\"><num1>⒝</num1> vice (1) ...の代わりに, ...のために 〈+<i>gen</i>〉</div><div class=\"ex\"><i>quaestoris vice</i> (<author>S<small>UET</small></author>)<span class=\"ext\">財務官に代わって.</span></div><div class=\"def\"> (2) ...のように 〈+<i>gen</i>〉</div><div class=\"ex\"><i>vice mundi</i> (<author>S<small>UET</small></author>)<span class=\"ext\">天体のように.</span></div>\r\n","<div class=\"hw\">vicissim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vicis]</div><div class=\"def\"><num>①</num> 順番として, 交代して;交互に.</div><div class=\"def\"><num>②</num> 反対に, 逆に.</div><div class=\"def\"><num>③</num> 他方, さらにまた.</div>\r\n","<div class=\"hw\">vicissitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vicis]</div><div class=\"def\">交代, 継承.</div>\r\n","<div class=\"hw\">vicissitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[vicis]</div><div class=\"def\"><num>①</num> 交代, 継承.</div><div class=\"def\"><num>②</num> 変化, 移り変わり</div><div class=\"ex\"><i>fortunae vicissitudines</i> (<author>C<small>IC</small></author>)<span class=\"ext\">運命の変転.</span></div><div class=\"def\"><num>③</num> 返報.</div>\r\n","<div class=\"hw\">vicissātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vicis\">vicis</a>]</div><div class=\"def\"><num>①</num> もう一度.</div><div class=\"def\"><num>②</num> その代わりに.</div>\r\n","<div class=\"hw\">victima</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 犠牲獣, いけにえ.</div><div class=\"def\"><num>②</num> 犠牲[被害]者.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 虐殺.</div>\r\n","<div class=\"hw\">victimārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://victima\">victima</a>]</div><div class=\"def\">犠牲獣の.</div><hr><div class=\"hw\">victimārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 犠牲式を行なうときの助手.</div><div class=\"def\"><num>②</num> 犠牲獣商人.</div>\r\n","<div class=\"hw\">victimō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[victima]</div><div class=\"def\">(獣を)犠牲に捧げる.</div>\r\n","<div class=\"hw\">victitō</div><div class=\"pos\">-āre -āvī, <i>intr freq</i></div><div class=\"ori\">[vivo]</div><div class=\"def\">生活する, 生きる</div><div class=\"ex\"><i>ficis victitamus aridis</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">私たちは干しイチジクを食べて生きている.</span></div>\r\n","<div class=\"hw\">victor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vinco]</div><div class=\"def\"><num>①</num> 勝利者, 征服者.</div><div class=\"def\"><num>②</num> (形容詞的に)勝利を得た, 勝ち誇る</div><div class=\"ex\">～ <i>equus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">優勝馬.</span></div>\r\n","<div class=\"hw\">victrix<SUP>1</SUP></div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[victor]</div><div class=\"def\">勝利[征服]者《女性》.</div><hr><div class=\"hw\">victrix<SUP>2</SUP></div><div class=\"pos\">-īcis, <i>adj</i></div><div class=\"def\"><num>①</num> 勝利の, 勝ち誇る</div><div class=\"ex\"><i>victricia arma</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">勝利を勝ち取った武器.</span></div><div class=\"def\"><num>②</num> 勝利を告げる</div><div class=\"ex\"><i>litterae victrices</i> (<author>C<small>IC</small></author>)<span class=\"ext\">戦勝を伝える書簡.</span></div>\r\n","<div class=\"hw\">victus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vincō\">vinco</a>, <a href=\"entry://vīvō\">vivo</a>.</div><hr><div class=\"hw\">victus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[vivo]</div><div class=\"def\"><num>①</num> 食物, 栄養物.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 生活必需品.</div><div class=\"def\"><num>③</num> 生活様式, 暮らしぶり.</div>\r\n","<div class=\"hw\">victuālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://victuālis\">victuālis</a>]</div><div class=\"def\">食糧.</div>\r\n","<div class=\"hw\">victuālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[victus<SUP>2</SUP>]</div><div class=\"def\">食物の, 栄養物の.</div>\r\n","<div class=\"hw\">victōria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://victor\">victor</a>]</div><div class=\"def\"><num>①</num> 勝利.</div><div class=\"def\"><num>②</num> 成功.</div>\r\n","<div class=\"hw\">Victōria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘神話〙ウィクトーリア《勝利の女神》.</div><div class=\"def\"><num>②</num> Victoria の像.</div>\r\n","<div class=\"hw\">Victōriola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"def\">勝利の女神 Victoria の小像.</div>\r\n","<div class=\"hw\">victōriātus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://Victōria\">Victōria</a>]</div><div class=\"def\"><num>①</num> (<i>sc. </i> nummus)(Victoria 像を刻印した)銀貨(=<img class=\"font\" src=\"img/B151.png\"> denarius).</div><div class=\"def\"><num>②</num> 重量単位(=<img class=\"font\" src=\"img/B151.png\"> denarius).</div>\r\n","<div class=\"hw\">victōriōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[victoria]</div><div class=\"def\">数多くの勝利を誇る.</div>\r\n","<div class=\"hw\">vicāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vicarius<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 身代わりの女性(=<a href=\"entry://Alcēstis\">Alcestis</a>).</div><div class=\"def\"><num>②</num> 《碑》(他の奴隷に買われた)下働きの女奴隷.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 親衛隊長代理の職[地位].</div>\r\n","<div class=\"hw\">vicārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vicis]</div><div class=\"def\">代理の, 身代わりの.</div><hr><div class=\"hw\">vicārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 代理人, 代行者;身代わり</div><div class=\"ex\"><i>alieni juris</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">他人の権利の代理人.</span></div><div class=\"def\"><num>②</num> 後継者.</div><div class=\"def\"><num>③</num> (他の奴隷に買われた)下働きとしての奴隷.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘カト〙司教代理.</div>\r\n","<div class=\"hw\">vicāriātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vicarius<SUP>2</SUP>]</div><div class=\"def\">〘カト〙司教代理の職.</div>\r\n","<div class=\"hw\">vicēs</div><div class=\"def\">⇒<a href=\"entry://vicis\">vicis</a>.</div>\r\n","<div class=\"hw\">videō</div><div class=\"pos\">-ēre vīdī vīsum, <i>tr</i></div><div class=\"def\"><num>①</num> 見る 〈+<i>acc</i>;+<i>acc c. inf</i>;ut〉</div><div class=\"ex\"><i>clare oculis</i> ～ (<author>P<small>LAUT</small></author>)<span class=\"ext\">わしは(老人だが)目は確かだぞ</span></div><div class=\"ex\"><i>quem vides?</i> (<author>T<small>ER</small></author>)<span class=\"ext\">あなたは誰を見てるの</span></div><div class=\"ex\"><i>caelum videre</i> (<author>O<small>V</small></author>)<span class=\"ext\">天を仰ぐ</span></div><div class=\"ex\"><i>qui surgere videt per nubila lunam</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">雲間を月が昇るのを目にする人</span></div><div class=\"ex\"><i>nonne vides ut antennae gemant?</i> (<author>H<small>OR</small></author>)<span class=\"ext\">帆桁がきしんでいるのが見えないか.</span></div><div class=\"def\"><num>②</num> (物を主語として)展望する</div><div class=\"ex\"><i>triclinium hortum et gestationem videt</i> (<author>P<small>LIN</small> M<small>IN</small></author>)<span class=\"ext\">食堂から庭園と遊歩道が見渡せます.</span></div><div class=\"def\"><num>③</num> 注視する, 観察する</div><div class=\"ex\"><i>vide si non os impudens videtur</i> (<author>T<small>ER</small></author>)<span class=\"ext\">ほら, よく見て, あつかましそうな顔に見えないこと?</span></div><div class=\"def\"><num>④</num> 目撃する, 証人となる</div><div class=\"ex\"><i>multas victorias aetas nostra vidit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">われわれの時代は数多くの勝利を体験した.</span></div><div class=\"def\"><num>⑤</num> 会う, 会いに行く.</div><div class=\"def\"><num>⑥</num> (視覚以外で)感知する</div><div class=\"ex\"><i>mugire videbis sub pedibus terram</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">あなたは足もとで大地がとどろくのを感じるでしょう.</span></div><div class=\"def\"><num>⑦</num> (心の目で)知覚する, 認識する</div><div class=\"ex\"><i>aliquid in somnis videre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">夢で何かを見る.</span></div><div class=\"def\"><num>⑧</num> 予見する</div><div class=\"ex\"><i>sagax ventura videre</i> (<author>O<small>V</small></author>)<span class=\"ext\">未来を予見するのが巧みな.</span></div><div class=\"def\"><num>⑨</num> 調査する, 考察する 〈+<i>acc</i>;+間接疑問〉</div><div class=\"ex\"><i>Epicuri sententiam videre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Epicurus の言説を検討する</span></div><div class=\"ex\"><i>videbit judex an puniendus sit</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">裁判官が(被告の)有罪か無罪かを決定するだろう.</span></div><div class=\"def\"><num>⑩</num> 用心する, 警戒する 〈ne, ut〉</div><div class=\"ex\"><i>uti consul videret ne quid res publica detrimenti caperet</i> (<author>C<small>IC</small></author>)<span class=\"ext\">国家が何らの被害もこうむらないように執政官が警戒すべし(と決議した).</span></div><div class=\"def\"><num>⑪</num> 取り計らう, 配慮する</div><div class=\"ex\"><i>tum reliqua videbimus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">その他のことについてはあとで考えよう.</span></div><div class=\"def\"><num>⑫</num> 供給する</div><div class=\"ex\"><i>asperum hoc vinum est</i>:<i>aliud lenius vide</i> (<author>T<small>ER</small></author>)<span class=\"ext\">このぶどう酒は酸っぱいわ, もっと甘いのを下さいな.</span></div><div class=\"def\"><num>⑬</num> (喜劇で)</div><div class=\"ex\"><i>me vide</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">私にまかせておけ.</span></div><div class=\"def\"><num>⑭</num> (<i>pass</i>)...らしく見える, ...と思われる, ...と考えられる 〈+<i>inf</i>;+<i>nom c. inf</i>;<i>+refl dat</i>〉</div><div class=\"ex\"><i>quod difficillimum nobis videbatur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私たちには最も困難と思われていたこと</span></div><div class=\"ex\"><i>satis facere rei publicae videmur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私たちは国家に充分尽くしていると考えられる</span></div><div class=\"ex\"><i>divitior mihi videtur esse vera amicitia</i> (<author>C<small>IC</small></author>)<span class=\"ext\">真の友情はもっと豊かなものであるように私には思われる</span></div><div class=\"ex\"><i>videor mihi gratum fecisse Siculis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はシキリア島民に善政を施したと自分では考えている.</span></div><div class=\"def\"><num>⑮</num> (<i>pass</i>;<i>n pron</i> を主語として)良い[正しい, 適当]と思われる</div><div class=\"ex\"><i>quid tibi videtur?</i> (<author>T<small>ER</small></author>)<span class=\"ext\">おまえはどうすればいいと思うかね</span></div><div class=\"ex\"><i>quae visa sunt occultant</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼らは(隠すのが)適当と判断したことを隠す.</span></div><div class=\"def\"><num>⑯</num> (<i>pass impers</i>)良い[正しい, 適当]と思われる 〈+<i>inf</i>;ut〉</div><div class=\"ex\"><i>mihi sic videtur</i> (<author>T<small>ER</small></author>)<span class=\"ext\">わしはそれがいいと思うね</span></div><div class=\"ex\"><i>itaque visum est de his rebus exponere</i> (<author>V<small>ITR</small></author>)<span class=\"ext\">こうして私はこれらの事柄について説明しておこうと決心した</span></div><div class=\"ex\"><i>scis ita nobis esse visum</i>, <i>ut isti ante legerent</i> (<author>C<small>IC</small></author>)<span class=\"ext\">君も知っての通り, 私はあの人たちが先に読むようにするのが好ましいと判断したのだ</span></div><div class=\"ex\">(挿入句的に)<i>si tibi videtur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">もしあなたに良いと思われるなら, お気に召すなら.</span></div>\r\n","<div class=\"hw\">vidua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[viduus]</div><div class=\"def\"><num>①</num> (死別または離婚により)夫のいない女性.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 未婚女性.</div>\r\n","<div class=\"hw\">viduitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[viduus]</div><div class=\"def\"><num>①</num> 未亡人であること, やもめ暮らし.</div><div class=\"def\"><num>②</num> 欠けていること 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">viduus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 配偶者に死なれた[と離婚した].</div><div class=\"def\"><num>②</num> 未婚の, 独身の.</div><div class=\"def\"><num>③</num> ...を奪われた, 欠けた 〈+<i>abl [gen]</i>;a re〉</div><div class=\"ex\"><i>pectus viduum amoris</i> (<author>O<small>V</small></author>)<span class=\"ext\">愛を失くした胸</span></div><div class=\"ex\">～ <i>pecudibus ager</i> (<author>C<small>OL</small></author>)<span class=\"ext\">家畜のいない田野.</span></div><div class=\"def\"><num>④</num> 所有者[主人]のいない.</div><div class=\"def\"><num>⑤</num> (ブドウのつるに)支えのない.</div>\r\n","<div class=\"hw\">viduālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vidua\">vidua</a>]</div><div class=\"def\">未亡人の.</div>\r\n","<div class=\"hw\">viduātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[viduo]</div><div class=\"def\">=<a href=\"entry://viduitās\">viduitas 1</a>.</div>\r\n","<div class=\"hw\">viduō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://viduus\">viduus</a>]</div><div class=\"def\"><num>①</num> 寡婦にする.</div><div class=\"def\"><num>②</num> 奪う, 空<SUB>から</SUB>にする</div><div class=\"ex\"><i>viduare civibus urbem</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">町から市民たちを奪い去る.</span></div>\r\n","<div class=\"hw\">vidēlicet</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[video/licet]</div><div class=\"def\"><num>①</num> ...は自明である 〈+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>esse ～ in terris primordia rerum</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">大地の中に物の原子が存在することは明らかである.</span></div><div class=\"def\"><num>②</num> 明らかに.</div><div class=\"def\"><num>③</num> (皮肉として)もちろん</div><div class=\"ex\"><i>homo ～ timidus et permodestus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(Catilina は)もちろん小心できわめて穏健な人物.</span></div><div class=\"def\"><num>④</num> すなわち.</div>\r\n","<div class=\"hw\">vidēn</div><div class=\"def\">=videsne(⇒ <a href=\"entry://videō\">video</a>, <a href=\"entry://-ne\">-ne</a>).</div>\r\n","<div class=\"hw\">Vienna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウィエンナ《Gallia Narbonensis の Rhodanus 川沿いの町:現 Vienne》.</div>\r\n","<div class=\"hw\">Viennensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Vienna の.</div><div class=\"hw2\"><b>Viennensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Vienna の住民.</div>\r\n","<div class=\"hw\">viescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://vieō\">vieō</a>]</div><div class=\"def\">しなびる, 縮む.</div>\r\n","<div class=\"hw\">vieō</div><div class=\"pos\">-ēre -ētum, <i>tr</i></div><div class=\"def\">結び[より]合わせる, 編む.</div>\r\n","<div class=\"hw\">vigescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://vigeō\">vigeō</a>]</div><div class=\"def\">活発になる;繁栄し始める.</div>\r\n","<div class=\"hw\">vigeō</div><div class=\"pos\">-ēre -guī, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> vegeo]</div><div class=\"def\"><num>①</num> 元気である, 活発である, 活力がある</div><div class=\"ex\"><i>Persarum vigui rege beatior</i> (<author>H<small>OR</small></author>)<span class=\"ext\">ぼくはペルシア王よりも幸せで元気いっぱいだった.</span></div><div class=\"def\"><num>②</num> 繁栄している, 有力である, 流行している.</div>\r\n","<div class=\"hw\">vigil<SUP>1</SUP></div><div class=\"pos\">-ilis, <i>adj</i></div><div class=\"ori\">[vigeo]</div><div class=\"def\"><num>①</num> 眠らない, 徹夜の</div><div class=\"ex\">～ <i>ignis</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">休みなく燃え続ける火.</span></div><div class=\"def\"><num>②</num> 警戒している, 油断のない.</div><hr><div class=\"hw\">vigil<SUP>2</SUP></div><div class=\"pos\">-ilis, <i>m</i></div><div class=\"def\">夜警, 不寝番.</div>\r\n","<div class=\"hw\">vigilans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[vigilo]</div><div class=\"def\"><num>①</num> 眠らない.</div><div class=\"def\"><num>②</num> 警戒している.</div>\r\n","<div class=\"hw\">vigilanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vigilans\">vigilans</a>]</div><div class=\"def\">注意深く, 油断なく.</div>\r\n","<div class=\"hw\">vigilantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vigilans]</div><div class=\"def\"><num>①</num> 不寝, 徹夜.</div><div class=\"def\"><num>②</num> 警戒, 用心.</div>\r\n","<div class=\"hw\">vigilax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[vigilo]</div><div class=\"def\">眠らない;警戒している</div><div class=\"ex\"><i>curae vigilaces</i> (<author>O<small>V</small></author>)<span class=\"ext\">絶え間ない心労.</span></div>\r\n","<div class=\"hw\">vigilia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vigil<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 眠らずにいること;不眠(症).</div><div class=\"def\"><num>②</num> 不寝番, 夜警.</div><div class=\"def\"><num>③</num> 1夜警時《日没から夜明けまでの時間の <img class=\"font\" src=\"img/B153.png\">》</div><div class=\"ex\"><i>de tertia vigila</i> (<author>C<small>AES</small></author>)<span class=\"ext\">第3夜警時(の間)に.</span></div><div class=\"def\"><num>④</num> 歩哨, 見張り(番).</div><div class=\"def\"><num>⑤</num> 警戒, 用心.</div><div class=\"def\"><num>⑥</num> (宗教的な)夜間の儀式.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘カト〙(主要祝日の)前日の典礼.</div>\r\n","<div class=\"hw\">vigilium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vigil<SUP>1</SUP>]</div><div class=\"def\">見張り, 警戒.</div>\r\n","<div class=\"hw\">vigiliārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vigil<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 物見やぐら, 望楼.</div><div class=\"def\"><num>②</num> 《碑》望楼の形をした墓.</div>\r\n","<div class=\"hw\">vigilārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://vigiliārium\">vigiliarium</a>.</div>\r\n","<div class=\"hw\">vigilō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[vigil<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (夜間)起きている, 眠らずにいる.</div><div class=\"def\"><num>②</num> めざめる.</div><div class=\"def\"><num>③</num> 警戒する, 用心する</div><div class=\"ex\"><i>vigila ut mihi succedatur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の後任が来るように注意していてくれ.</span></div><div class=\"def\"><num>④</num> 眠らずに仕上げる</div><div class=\"ex\"><i>vigilatum carmen</i> (<author>O<small>V</small></author>)<span class=\"ext\">夜も寝ないで書き上げた詩.</span></div><div class=\"def\"><num>⑤</num> 夜ふかしする</div><div class=\"ex\"><i>vigilatam convivio noctem</i> (<author>T<small>AC</small></author>)<span class=\"ext\">饗宴でふけた夜.</span></div>\r\n","<div class=\"hw\">vigor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vigeo]</div><div class=\"def\"><num>①</num> 活力, 精力, 気力.</div><div class=\"def\"><num>②</num> (宝石の)特別な輝き.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘法〙効力, 有効性.</div>\r\n","<div class=\"hw\">vigōrans</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vigor\">vigor</a>]</div><div class=\"def\"><num>①</num> 活気のある.</div><div class=\"def\"><num>②</num> 強固にする.</div>\r\n","<div class=\"hw\">vigōrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vigor]</div><div class=\"def\"><num>①</num> 活発な.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 強固にされた.</div>\r\n","<div class=\"hw\">vigōrātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://vigōrātus\">vigōrātus</a>]</div><div class=\"def\">勢いよく.</div>\r\n","<div class=\"hw\">villa</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vicus]</div><div class=\"def\"><num>①</num> 別荘, 田舎屋敷.</div><div class=\"def\"><num>②</num> 荘園, 農場.</div><div class=\"def\"><num>③</num> ～ <i>publica</i> (<author>C<small>IC</small></author>, <author>L<small>IV</small></author>) Campus Martius にあった公共施設《そこで人口・財産登録が行なわれた他, 外国からの使節の宿舎にもあてられた》.</div><div class=\"def\"><num>④</num> 村(=<a href=\"entry://vīcus\">vicus</a>).</div>\r\n","<div class=\"hw\">villic-</div><div class=\"def\">⇒vilic-.</div>\r\n","<div class=\"hw\">Villius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィッリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">villula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[villa]</div><div class=\"def\">小さな別荘[農場].</div>\r\n","<div class=\"hw\">villum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[vinum]</div><div class=\"def\">少量のぶどう酒.</div>\r\n","<div class=\"hw\">villus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> (羊などの)もじゃもじゃの毛.</div><div class=\"def\"><num>②</num> (布地の)けば.</div><div class=\"def\"><num>③</num> (樹木に生ずる)コケのようなもの.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙(小腸粘膜などの)絨毛.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘植〙(果実・花などの)絨毛.</div>\r\n","<div class=\"hw\">villāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://villa\">villa</a>]</div><div class=\"def\">農場の.</div>\r\n","<div class=\"hw\">villāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[villa]</div><div class=\"def\">農場の, 別荘の.</div>\r\n","<div class=\"hw\">villōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[villus]</div><div class=\"def\">毛でおおわれた, 毛むくじゃらの.</div>\r\n","<div class=\"hw\">vincibilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vinco]</div><div class=\"def\"><num>①</num> 勝つ[打ち負かす]ことができる.</div><div class=\"def\"><num>②</num> (議論が)説得力のある.</div>\r\n","<div class=\"hw\">vinciō</div><div class=\"pos\">-īre vinxī vinctum, <i>tr</i></div><div class=\"def\"><num>①</num> 縛る, 結ぶ, つなぐ</div><div class=\"ex\"><i>vincire post terga manūs</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">後ろ手に縛る</span></div><div class=\"ex\"><i>canis catenā vinctus</i> (<author>P<small>ETR</small></author>)<span class=\"ext\">鎖につながれた犬.</span></div><div class=\"def\"><num>②</num> (装身具などで)巻きつける, 飾る</div><div class=\"ex\"><i>vincire tempora floribus</i> (<author>H<small>OR</small></author>)<span class=\"ext\">額を花輪で飾る.</span></div><div class=\"def\"><num>③</num> 取り囲む</div><div class=\"ex\"><i>loca praesidiis vincire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(その)地点を守備隊で固める.</span></div><div class=\"def\"><num>④</num> (道徳的・感情的に)束縛する.</div><div class=\"def\"><num>⑤</num> (眠り・酒などで)身体の自由を奪う.</div><div class=\"def\"><num>⑥</num> 〘修〙(ことばを)緊密に結びつける.</div>\r\n","<div class=\"hw\">vinclum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://vinculum\">vinculum</a>.</div>\r\n","<div class=\"hw\">vinctiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vincio]</div><div class=\"def\"><num>①</num> 結びつけること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> おむつ.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(胸部の)痙攣<SUB>けいれん</SUB>性収縮.</div>\r\n","<div class=\"hw\">vinctus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vinciō\">vincio</a>.</div><hr><div class=\"hw\">vinctus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">ひも.</div>\r\n","<div class=\"hw\">vinctūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vincio]</div><div class=\"def\"><num>①</num> 結びつけること, ゆわえること.</div><div class=\"def\"><num>②</num> 包帯.</div>\r\n","<div class=\"hw\">vinculum, vinclum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vincio]</div><div class=\"def\"><num>①</num> ひも, なわ, 綱.</div><div class=\"def\"><num>②</num> (<i>pl</i>)鎖, (手・足)枷<SUB>かせ</SUB></div><div class=\"ex\"><i>moribus suis Orgetoricem ex vinculis causam dicere coegerunt</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼らは部族の慣例どおり Orgetorix に鎖につながれて弁明することを強いた</span></div><div class=\"ex\"><i>in vincula duci</i> (<author>L<small>IV</small></author>)<span class=\"ext\">鎖につながれる(=投獄される).</span></div><div class=\"def\"><num>③</num> 拘束, 束縛.</div><div class=\"def\"><num>④</num> きずな, 縁<SUB>えん</SUB></div><div class=\"ex\">～ <i>jugale</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">夫婦のきずな.</span></div>\r\n","<div class=\"hw\">vincō</div><div class=\"pos\">-ere vīcī victum, <i>tr</i>(<i>intr</i>)</div><div class=\"def\"><num>①</num> (軍事的に)勝利する, 打ち負かす, 征服する</div><div class=\"ex\"><i>Galliam bello vici</i> (<author>C<small>AES</small></author>)<span class=\"ext\">私は戦争で Gallia を征服した.</span></div><div class=\"def\"><num>②</num> (競技・訴訟・議論などで)勝つ</div><div class=\"ex\"><i>judicium vincere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">勝訴する</span></div><div class=\"ex\"><i>Othonem vincere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(競売で)Otho に競<SUB>せ</SUB>り勝つ.</span></div><div class=\"def\"><num>③</num> (人間以外の競合関係で)優位に立つ, 圧倒する</div><div class=\"ex\"><i>nix zephylo victa tepente</i> (<author>O<small>V</small></author>)<span class=\"ext\">生暖かい西風に溶けた雪.</span></div><div class=\"def\"><num>④</num> (精神的・感情的に)強いる, 束縛する</div><div class=\"ex\"><i>victus animi respexit</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(Orpheus は)決心がにぶって後ろを振り返った</span></div><div class=\"ex\"><i>victus patris precibus lacrimisque</i> (<author>L<small>IV</small></author>)<span class=\"ext\">父親の嘆願と涙に負けて.</span></div><div class=\"def\"><num>⑤</num> 上回る, しのぐ</div><div class=\"ex\"><i>vivendo vici mea fata</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">私は生きながらえて天命を超えた.</span></div><div class=\"def\"><num>⑥</num> 立証に成功する, 確証する</div><div class=\"ex\"><i>vince bonum virum fuisse Oppianicum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Oppianicus が善良な市民であったことを証明せよ.</span></div><div class=\"def\"><num>⑦</num> (要求を)勝ち取る</div><div class=\"ex\"><i>vincite</i>, <i>si ita vultis</i> (<author>C<small>AES</small></author>)<span class=\"ext\">おまえたちがそう望むなら, そうするがよい.</span></div>\r\n","<div class=\"hw\">Vindelicī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウィンデリキー《Alpes 山脈と Danubius 川の間にいた一部族;中心地は Augusta Vindelicorum(現 Augsburg)》.</div>\r\n","<div class=\"hw\">vindex<SUP>1</SUP></div><div class=\"pos\">-dicis, <i>m</i>, <i>f</i></div><div class=\"ori\">[vindico]</div><div class=\"def\"><num>①</num> 〘法〙(被告の)保証[代理]人.</div><div class=\"def\"><num>②</num> 保護[擁護]する人</div><div class=\"ex\">～ <i>injuriae</i> (<author>L<small>IV</small></author>)<span class=\"ext\">不法行為から守る人.</span></div><div class=\"def\"><num>③</num> 復讐[処罰]する人.</div><hr><div class=\"hw\">vindex<SUP>2</SUP></div><div class=\"pos\">-dicis, <i>adj</i></div><div class=\"def\">復讐の, 処罰する</div><div class=\"ex\"><i>animus</i> ～ <i>avarae fraudis</i> (<author>H<small>OR</small></author>)<span class=\"ext\">貪欲な欺瞞を懲らしめる精神.</span></div>\r\n","<div class=\"hw\">Vindex</div><div class=\"pos\">-icis, <i>m</i></div><div class=\"def\">ウィンデクス《ローマ人の家名;特に <i>C. Julius ～</i>, Gallia で Nero 帝に反乱ののろしを揚げた(後68)》.</div>\r\n","<div class=\"hw\">vindiciae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[↓<a href=\"entry://vindicō\">vindicō</a>]</div><div class=\"def\"><num>①</num> 〘法〙(所有権争いが決着するまでの)暫定所有(権)</div><div class=\"ex\"><i>injustis vindiciis alienos fundos petere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">不当な(所有権の)要求によって他人の地所を横領しようとする.</span></div><div class=\"def\"><num>②</num> (所有権争いの)対象物件.</div>\r\n","<div class=\"hw\">vindicta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vindicō\">vindicō</a>]</div><div class=\"def\"><num>①</num> (解放の儀式で奴隷の頭に触れる)杖.</div><div class=\"def\"><num>②</num> 解放, 救済.</div><div class=\"def\"><num>③</num> 復讐;処罰.</div>\r\n","<div class=\"hw\">vindicātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vindico]</div><div class=\"def\"><num>①</num> 〘法〙(所有権の)主張.</div><div class=\"def\"><num>②</num> (不正行為からの)防御;(不正行為への)報復.</div>\r\n","<div class=\"hw\">vindicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vis/dico<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 〘法〙(人・物の)所有権を主張[要求・請求]する.</div><div class=\"def\"><num>②</num> (不当に)自分のものと称する, 私物化する</div><div class=\"ex\"><i>Chii Homerum suum vindicant</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Chios 島民は Homerus を同国人と称えている.</span></div><div class=\"def\"><num>③</num> 自由(身分)にする, 解放する</div><div class=\"ex\"><i>sponsam in libertatem vindicare</i> (<author>L<small>IV</small></author>)<span class=\"ext\">許婚<SUB>いいなずけ</SUB>の自由(身分)の回復を要求する.</span></div><div class=\"def\"><num>④</num> (危険・危害などから)救う, 防御する</div><div class=\"ex\"><i>a cruditate vindicare</i> (<author>L<small>IV</small></author>)<span class=\"ext\">残酷な仕打ちから守る.</span></div><div class=\"def\"><num>⑤</num> 復讐する, 罰する</div><div class=\"ex\"><i>acerrime maleficia vindicare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">悪行を非常にきびしく罰する</span></div><div class=\"ex\">(<i>impers pass</i> と in+<i>acc</i> の構文で)<i>in bello saepius vindicatum est in eos</i>, <i>qui contra imperium in hostem pugnaverant</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">戦争ではかなりしばしば命令に背いて敵を攻撃した者どもが処罰された.</span></div>\r\n","<div class=\"hw\">Vindobona</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ウィンドボナ《Pannonia 北部の Danubius 川沿いの町;現 Wien》.</div>\r\n","<div class=\"hw\">Vindonissa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウィンドニッサ《Helvetii 族の町;現 Windisch(スイス)》.</div>\r\n","<div class=\"hw\">vindēmia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vinum/demo]</div><div class=\"def\"><num>①</num> ブドウの収穫[取り入れ].</div><div class=\"def\"><num>②</num> ブドウの実, ぶどう酒.</div><div class=\"def\"><num>③</num> (一般に)収穫, 取り入れ.</div>\r\n","<div class=\"hw\">vindēmiola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vindemia]</div><div class=\"def\">ブドウのわずかな収穫;ささやかな貯え.</div>\r\n","<div class=\"hw\">vindēmitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vindemio]</div><div class=\"def\"><num>①</num> =<a href=\"entry://vindēmiātor\">vindemiator</a>.</div><div class=\"def\"><num>②</num> 〘天〙乙女座の星《その出現はブドウの収穫期の到来を告げる》.</div>\r\n","<div class=\"hw\">vindēmiālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vindēmiālis\">vindēmiālis</a>]</div><div class=\"def\">ブドウの収穫を祝う祭.</div>\r\n","<div class=\"hw\">vindēmiālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vindemia]</div><div class=\"def\">ブドウの収穫に関する.</div>\r\n","<div class=\"hw\">vindēmiātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vindemia]</div><div class=\"def\">ブドウを摘む[取り入れる]人.</div>\r\n","<div class=\"hw\">vindēmiātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vindēmiātor\">vindēmiātor</a>]</div><div class=\"def\">ブドウ摘みの.</div>\r\n","<div class=\"hw\">vindēmiō</div><div class=\"pos\">-āre, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[vindemiator]</div><div class=\"def\">ブドウを摘む[取り入れる].</div>\r\n","<div class=\"hw\">vinnulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> venustulus]</div><div class=\"def\">(語り口が)楽しい, 面白おかしい.</div>\r\n","<div class=\"hw\">vinxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vinciō\">vincio</a>.</div>\r\n","<div class=\"hw\">viocūrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[via/curo]</div><div class=\"def\">道路管理人.</div>\r\n","<div class=\"hw\">viola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[<i>cf. Gk</i>▷<img class=\"font\" src=\"img/A14D.png\">ον◁]</div><div class=\"def\"><num>①</num> 〘植〙スミレ・ストック(アラセイトウ)・スノードロップ(マツユキソウ)などの春の花.</div><div class=\"def\"><num>②</num> すみれ色, 青紫色.</div>\r\n","<div class=\"hw\">violens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[vis]</div><div class=\"def\">激しい, 猛烈な.</div>\r\n","<div class=\"hw\">violenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://violens\">violens</a>]</div><div class=\"def\">乱暴に, 激しく.</div>\r\n","<div class=\"hw\">violentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://violentus\">violentus</a>]</div><div class=\"def\"><num>①</num> 暴力(行為).</div><div class=\"def\"><num>②</num> (性格・気性などの)激しさ, 狂暴性;怒り.</div><div class=\"def\"><num>③</num> (自然の)猛威, 厳しさ.</div>\r\n","<div class=\"hw\">violentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vis]</div><div class=\"def\"><num>①</num> 乱暴な, 破壊的な.</div><div class=\"def\"><num>②</num> 激しい, 強烈な.</div>\r\n","<div class=\"hw\">violābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[violo]</div><div class=\"def\"><num>①</num> 傷つけられる.</div><div class=\"def\"><num>②</num> はずかしめを受ける.</div>\r\n","<div class=\"hw\">violāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[viola]</div><div class=\"def\">すみれ色の.</div>\r\n","<div class=\"hw\">violāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[viola]</div><div class=\"ex\"><i>dies</i> ～<span class=\"ext\">《碑》故人を追悼して墓所にスミレ(またはストック)を供える日(3月22日).</span></div>\r\n","<div class=\"hw\">violārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[viola]</div><div class=\"def\">スミレの花壇[園].</div>\r\n","<div class=\"hw\">violārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[viola]</div><div class=\"def\"><num>①</num> 《碑》スミレ(の花輪)を売る人.</div><div class=\"def\"><num>②</num> 衣服をすみれ色に染める職人.</div>\r\n","<div class=\"hw\">violātiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[violo]</div><div class=\"def\"><num>①</num> (神聖なものの)冒涜.</div><div class=\"def\"><num>②</num> (約束の)不履行.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 性的暴行.</div><hr><div class=\"hw\">violātiō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[viola]</div><div class=\"def\">《碑》墓にスミレ(またはストック)を供えること(⇒ <a href=\"entry://violāris\">violaris</a>).</div>\r\n","<div class=\"hw\">violātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[violo]</div><div class=\"def\"><num>①</num> 危害を加える人.</div><div class=\"def\"><num>②</num> (条約などを)破る者.</div><div class=\"def\"><num>③</num> 冒涜する人.</div><div class=\"def\"><num>④</num> 陵辱する人.</div>\r\n","<div class=\"hw\">violātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://violō\">violo</a>.</div>\r\n","<div class=\"hw\">violō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vis]</div><div class=\"def\"><num>①</num> 暴力をふるう, 危害を加える.</div><div class=\"def\"><num>②</num> 侵入する, 略奪する.</div><div class=\"def\"><num>③</num> (条約などを)破る, 犯す</div><div class=\"ex\"><i>dignitatem violare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">威信を傷つける.</span></div><div class=\"def\"><num>④</num> 冒涜する, はずかしめる</div><div class=\"ex\"><i>loca religiosa et lucos violare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">聖所や神苑を冒涜する.</span></div><div class=\"def\"><num>⑤</num> けがす</div><div class=\"ex\"><i>ne hospitali caede dextram violaret</i> (<author>L<small>IV</small></author>)<span class=\"ext\">客人を殺害した血で右手をけがすことのないように.</span></div><div class=\"def\"><num>⑥</num> (表面の)輝きをそこなう</div><div class=\"ex\"><i>Indum sanguineo violare ostro ebur</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">血のような深紅色でインドの象牙を染める.</span></div>\r\n","<div class=\"hw\">Vipstānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィプスターヌス《～ <i>Messalla</i>, 1世紀のローマの軍人・雄弁家・歴史家》.</div>\r\n","<div class=\"hw\">Vipsānia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウィプサーニア《～ <i>Agrippina</i>, M. Vipsanius Agrippa の娘;(即位前の)Tiberius の妻》.</div>\r\n","<div class=\"hw\">Vipsānius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィプサーニウス《ローマ人の氏族名;特に <i>M. ～ Agrippa</i>, Augustus の娘 Julia の夫》.</div>\r\n","<div class=\"hw\">vir</div><div class=\"pos\">virī, <i>m</i></div><div class=\"def\"><num>①</num> (女 femina に対して)男.</div><div class=\"def\"><num>②</num> (少年 puer に対して)成人男子.</div><div class=\"def\"><num>③</num> 男らしい[真の]男.</div><div class=\"def\"><num>④</num> 夫.</div><div class=\"def\"><num>⑤</num> 恋人, 愛人.</div><div class=\"def\"><num>⑥</num> (通例 <i>pl</i>)兵士(=歩兵);船員.</div><div class=\"def\"><num>⑦</num> (<i>pl</i>)人類.</div><div class=\"def\"><num>⑧</num> (is, ille の代わりに)あの[例の]男.</div><div class=\"def\"><num>⑨</num> (各)個人.</div><div class=\"def\"><num>⑩</num> 男性としての機能.</div>\r\n","<div class=\"hw\">vira</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vir\">vir</a>]</div><div class=\"def\">女(=<a href=\"entry://fēmina\">femina</a>).</div>\r\n","<div class=\"hw\">Virbius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙ウィルビウス《 (1) Hippolytus の別名.(2) Hippolytus の息子》.</div>\r\n","<div class=\"hw\">Virdomarus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Viridomarus\">Viridomarus</a>.</div>\r\n","<div class=\"hw\">virectum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vireo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 緑地.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 緑色.</div>\r\n","<div class=\"hw\">virentia</div><div class=\"pos\">-ium, <i>n pl(prp)</i></div><div class=\"ori\">[↓<a href=\"entry://vireō\">vireō<SUP>1</SUP></a>]</div><div class=\"def\">植物, 草木.</div>\r\n","<div class=\"hw\">virescō<SUP>1</SUP></div><div class=\"pos\">-ere -ruī, <i>intr inch</i></div><div class=\"ori\">[vireo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 緑色になる, 青々とする.</div><div class=\"def\"><num>②</num> 活発になる, 繁栄する.</div><hr><div class=\"hw\">virescō<SUP>2</SUP></div><div class=\"pos\">-ere -ruī, <i>intr inch</i></div><div class=\"ori\">[vis]</div><div class=\"def\">力を回復する.</div>\r\n","<div class=\"hw\">vireō<SUP>1</SUP></div><div class=\"pos\">-ēre -ruī, <i>intr</i></div><div class=\"def\"><num>①</num> 緑色である, 青々としている.</div><div class=\"def\"><num>②</num> 溌剌<SUB>はつらつ</SUB>としている, 元気である.</div><hr><div class=\"hw\">vireō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">〘鳥〙カワラヒワ.</div>\r\n","<div class=\"hw\">virga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> (細くしなやかな)若枝, 小枝.</div><div class=\"def\"><num>②</num> 接ぎ木, 挿し木.</div><div class=\"def\"><num>③</num> (捕鳥用の)もちざお.</div><div class=\"def\"><num>④</num> ほうき.</div><div class=\"def\"><num>⑤</num> (体罰・乗馬用の)鞭.</div><div class=\"def\"><num>⑥</num> (束桿<SUB>そっかん</SUB>(fasces)に束ねられた)棒;《詩》束桿;(職務を示す)杖.</div><div class=\"def\"><num>⑦</num> (Mercurius の)杖(=<a href=\"entry://cādūceus\">caduceus</a>);(Circe の)魔法の杖.</div><div class=\"def\"><num>⑧</num> 棒, 竿.</div><div class=\"def\"><num>⑨</num> (亜麻の)茎.</div><div class=\"def\"><num>⑩</num> (衣服の)縦縞模様;(天空に現われる)色の筋(=不完全な虹).</div><div class=\"def\"><num>⑪</num> (系図の)分枝.</div><div class=\"def\"><num>⑫</num> <SUP>◇</SUP> 陰茎(=membrum virile).</div>\r\n","<div class=\"hw\">virgeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[virga]</div><div class=\"def\">若[小]枝の[で編んだ].</div>\r\n","<div class=\"hw\">virgidēmia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[virga]</div><div class=\"def\">鞭の収穫(=さんざん鞭打たれること)《vindemia をもじった喜劇の造語》.</div>\r\n","<div class=\"hw\">Virgilius</div><div class=\"def\">(後代の写本・刊本に見られる綴り)=<a href=\"entry://Vergilius\">Vergilius</a>.</div>\r\n","<div class=\"hw\">virginal</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"ori\">[virgo]</div><div class=\"def\"><num>①</num> 未詳の海の生物.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> =<a href=\"entry://virgināle\">virginale</a>.</div>\r\n","<div class=\"hw\">virgineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[virgo]</div><div class=\"def\"><num>①</num> 若い娘の, 乙女[処女]の</div><div class=\"ex\"><i>virgineum ruborem ore suffundere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">乙女の恥じらいで顔を赤らめる</span></div><div class=\"ex\">～ <i>Helicon</i> (<author>O<small>V</small></author>)<span class=\"ext\">Musae の住む Helicon 山</span></div><div class=\"ex\"><i>focus</i> ～ (<author>P<small>ROP</small></author>)<span class=\"ext\">Vesta の巫女たちの守る炉.</span></div><div class=\"def\"><num>②</num> (土地が)未開墾の.</div><div class=\"def\"><num>③</num> 乙女座の.</div><div class=\"def\"><num>④</num> (ローマ市の)aqua Virgo 「乙女水道」 の.</div>\r\n","<div class=\"hw\">virginitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[virgo]</div><div class=\"def\"><num>①</num> 処女であること, 処女性.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 処女たち(=virgines).</div>\r\n","<div class=\"hw\">Virginius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Vergīnius\">Verginius</a>.</div>\r\n","<div class=\"hw\">virgināle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://virginālis\">virginālis</a>]</div><div class=\"def\">女性器(=pudenda muliebria).</div>\r\n","<div class=\"hw\">virginālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[virgo]</div><div class=\"def\">乙女の, 未婚の娘らしい</div><div class=\"ex\">～ <i>habitus atque vestitus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">乙女の身なりと衣装.</span></div>\r\n","<div class=\"hw\">virginārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[virgo]</div><div class=\"ex\"><i>feles virginaria</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">娘さらい《遊女屋に売りとばす》.</span></div>\r\n","<div class=\"hw\">virgula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[virga]</div><div class=\"def\"><num>①</num> 小枝.</div><div class=\"def\"><num>②</num> 小さな棒[杖]</div><div class=\"ex\">～ <i>divina</i> (<author>C<small>IC</small></author>)<span class=\"ext\">魔法の杖.</span></div><div class=\"def\"><num>③</num> 直線;筋.</div><div class=\"def\"><num>④</num> </div><div class=\"ex\"><i>censoria</i> ～ (<author>Q<small>UINT</small></author>)<span class=\"ext\">(偽作と思われる詩行に付ける)疑句標(=<a href=\"entry://obelus\">obelus</a>).</span></div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>(衣服の)縞.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> アクセント記号.</div>\r\n","<div class=\"hw\">virgulta</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://virgultum\">virgultum</a>]</div><div class=\"def\"><num>①</num> 低木のやぶ[茂み];若枝.</div><div class=\"def\"><num>②</num> 柴を束ねたもの, そだ, 薪<SUB>まき</SUB>.</div>\r\n","<div class=\"hw\">virgultum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[virgula]</div><div class=\"def\">低木, 灌木<SUB>かんぼく</SUB>.</div>\r\n","<div class=\"hw\">virgultus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://virgultum\">virgultum</a>]</div><div class=\"def\">やぶ[茂み]でおおわれた.</div>\r\n","<div class=\"hw\">virgulātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://virgula\">virgula</a>]</div><div class=\"def\">縞[筋]のある, 縞模様の.</div>\r\n","<div class=\"hw\">virguncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[virgo<SUP>1</SUP>]</div><div class=\"def\">小娘.</div>\r\n","<div class=\"hw\">virgātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://virga\">virga</a>]</div><div class=\"def\">(奴隷を)鞭打つ者.</div>\r\n","<div class=\"hw\">virgātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[virga]</div><div class=\"def\"><num>①</num> 小枝で編んだ.</div><div class=\"def\"><num>②</num> 縦縞模様の(衣服を着た).</div>\r\n","<div class=\"hw\">virgētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[virga]</div><div class=\"def\">柳の茂み.</div>\r\n","<div class=\"hw\">virgō<SUP>1</SUP></div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"def\"><num>①</num> 乙女, 処女</div><div class=\"ex\"><i>doctae virgines</i> (<author>C<small>ATUL</small></author>)<span class=\"ext\">=Musae</span></div><div class=\"ex\">～ <i>bellica</i> (<author>O<small>V</small></author>)<span class=\"ext\">戦の処女(神)(=<a href=\"entry://Minerva\">Minerva</a>).</span></div><div class=\"def\"><num>②</num> (V-)〘天〙乙女座.</div><div class=\"def\"><num>③</num> <i>(aqua)Virgo</i> (<author>O<small>V</small></author>) 「乙女水道」《M. Agrippa が建設したローマ市の水道;現在でも Trevi の泉に水を送っている》.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(V-)〘カト〙聖母マリア.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘カト〙修道女.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>(<i>m</i>)童貞の若者;独身を通している人.</div><hr><div class=\"hw\">virgō<SUP>2</SUP></div><div class=\"pos\">-ginis, <i>adj</i></div><div class=\"def\"><num>①</num> 未婚の</div><div class=\"ex\"><i>filia</i> ～ (<author>T<small>ER</small></author>)<span class=\"ext\">生娘.</span></div><div class=\"def\"><num>②</num> 未交尾の.</div><div class=\"def\"><num>③</num> 未開墾の</div><div class=\"ex\"><i>terra</i> ～ (<author>P<small>LIN</small></author>)<span class=\"ext\">処女地.</span></div><div class=\"def\"><num>④</num> 未使用の.</div>\r\n","<div class=\"hw\">viria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">腕輪の一種.</div>\r\n","<div class=\"hw\">viriculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">彫刻刀, ビュラン.</div>\r\n","<div class=\"hw\">viride<SUP>1</SUP></div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[viridis]</div><div class=\"def\"><num>①</num> 緑色(の物).</div><div class=\"def\"><num>②</num> 秣<SUB>まぐさ</SUB>, かいば.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(草木の)緑.</div>\r\n","<div class=\"hw\">viridia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[viridis]</div><div class=\"def\"><num>①</num> 緑の草木.</div><div class=\"def\"><num>②</num> 植え込み.</div>\r\n","<div class=\"hw\">viridicans</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://viridis\">viridis</a>]</div><div class=\"def\">緑がかった.</div>\r\n","<div class=\"hw\">viridis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vireo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 緑の, 青々とした.</div><div class=\"def\"><num>②</num> 新鮮な, 未熟な.</div><div class=\"def\"><num>③</num> 若々しい, 力強い.</div>\r\n","<div class=\"hw\">viriditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://viridis\">viridis</a>]</div><div class=\"def\"><num>①</num> 緑色, 青々としていること;緑の草木.</div><div class=\"def\"><num>②</num> 若々しさ, 活力.</div>\r\n","<div class=\"hw\">viridiārium, viridārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[viridis]</div><div class=\"def\">庭園, 植え込み.</div>\r\n","<div class=\"hw\">Viridomarus, Virdomarus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィリドマルス《Insubres 族の指導者;ローマの執政官 M. Claudius Marcellus との一騎討ちで敗れた(前222)》.</div>\r\n","<div class=\"hw\">viridē<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[viridis]</div><div class=\"def\">緑色に.</div>\r\n","<div class=\"hw\">viridō</div><div class=\"pos\">-āre, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[viridis]</div><div class=\"def\"><num>①</num> (通例 <i>prp</i>)緑色である</div><div class=\"ex\"><i>viridantes herbae</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">緑の草.</span></div><div class=\"def\"><num>②</num> 緑色にする.</div>\r\n","<div class=\"hw\">viriola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[viria]</div><div class=\"def\">(小さな)腕輪.</div>\r\n","<div class=\"hw\">viripotens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[vir/potens]</div><div class=\"def\">〘法〙(少女が男子と)性交可能な, 結婚できる.</div>\r\n","<div class=\"hw\">Viriāt(h)us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィリアートゥス《ローマ軍と戦った(前147‐140)Lusitania 人の指揮者》.</div>\r\n","<div class=\"hw\">Viromanduī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウィロマンドゥイー《Gallia Belgica の一部族》.</div>\r\n","<div class=\"hw\">viror</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vireo<SUP>1</SUP>]</div><div class=\"def\">緑色, 新緑.</div>\r\n","<div class=\"hw\">virtuōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://virtūs\">virtūs</a>]</div><div class=\"def\">有徳の.</div>\r\n","<div class=\"hw\">virtūs</div><div class=\"pos\">-ūtis, <i>f</i></div><div class=\"ori\">[vir]</div><div class=\"def\"><num>①</num> 男らしさ, 雄々しさ.</div><div class=\"def\"><num>②</num> 勇気, 果断;(<i>pl</i>)英雄的行為.</div><div class=\"def\"><num>③</num> 美徳, 高潔;卓越.</div><div class=\"def\"><num>④</num> (V-)(神格化されて)美徳の女神.</div><div class=\"def\"><num>⑤</num> 力;才能.</div><div class=\"def\"><num>⑥</num> 長所, 美点.</div><div class=\"def\"><num>⑦</num> <i>virtute</i> 〈+<i>gen</i> [<i>adj poss</i>]〉 ...のおかげで, ...のために</div><div class=\"ex\"><i>virtute deum et majorum nostrorum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">神々とご先祖さまのおかげで.</span></div>\r\n","<div class=\"hw\">viruī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vireō\">vireo<SUP>1</SUP></a>, <a href=\"entry://virescō\">viresco<SUP>1</SUP></a>, <a href=\"entry://virescō\">viresco<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">virācius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vir]</div><div class=\"def\">男らしい, 男性的な.</div>\r\n","<div class=\"hw\">virāgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[virgo]</div><div class=\"def\"><num>①</num> 男のように頑丈な体の女.</div><div class=\"def\"><num>②</num> 戦を好む女</div><div class=\"ex\"><i>belli metuenda</i> ～ (<author>O<small>V</small></author>)<span class=\"ext\">戦で恐れられる女戦士(=<a href=\"entry://Minerva\">Minerva</a>).</span></div>\r\n","<div class=\"hw\">virīlia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://virīlis\">virīlis</a>]</div><div class=\"def\"><num>①</num> 男性器.</div><div class=\"def\"><num>②</num> 男らしい[勇敢な]行為.</div>\r\n","<div class=\"hw\">virīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vir]</div><div class=\"def\"><num>①</num> 男の, 男性の</div><div class=\"ex\"><i>pars</i> ～ (<author>L<small>UCR</small></author>)<span class=\"ext\">男性器.</span></div><div class=\"def\"><num>②</num> 男系の.</div><div class=\"def\"><num>③</num> 成人男子の</div><div class=\"ex\"><i>toga</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">16歳に達した男子が着用する純白の外衣.</span></div><div class=\"def\"><num>④</num> 男らしい, 勇敢な.</div><div class=\"def\"><num>⑤</num> 各個人の</div><div class=\"ex\"><i>pars</i> ～ (<author>L<small>IV</small></author>)<span class=\"ext\">各人の取り分[分け前]</span></div><div class=\"ex\"><i>pro virili parte</i> (<author>C<small>IC</small></author>)<span class=\"ext\">各人の力の及ぶ限り, 精一杯に.</span></div><div class=\"def\"><num>⑥</num> 〘文〙男性の.</div>\r\n","<div class=\"hw\">virīliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[virilis]</div><div class=\"def\">男らしく, 勇敢に.</div>\r\n","<div class=\"hw\">virīlitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://virīlis\">virīlis</a>]</div><div class=\"def\"><num>①</num> 男として性的に成熟すること.</div><div class=\"def\"><num>②</num> 成年男子であること.</div><div class=\"def\"><num>③</num> 男性器.</div><div class=\"def\"><num>④</num> 男らしさ, 勇気.</div>\r\n","<div class=\"hw\">virītim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vir]</div><div class=\"def\"><num>①</num> 一人ずつ;各人に.</div><div class=\"def\"><num>②</num> 個人として.</div>\r\n","<div class=\"hw\">virōsus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vir]</div><div class=\"def\">(女が)男狂いの.</div>\r\n","<div class=\"hw\">viscellum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[viscus<SUP>2</SUP>]</div><div class=\"def\">〘料理〙(肉の)詰め物.</div>\r\n","<div class=\"hw\">viscellātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://viscellum\">viscellum</a>]</div><div class=\"def\">詰め物をした.</div>\r\n","<div class=\"hw\">viscera</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"def\">⇒<a href=\"entry://viscus\">viscus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">viscereus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[viscera]</div><div class=\"def\">肉から成る.</div>\r\n","<div class=\"hw\">viscerālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://viscera\">viscera</a>]</div><div class=\"def\"><num>①</num> 腸の.</div><div class=\"def\"><num>②</num> 内部[内面の].</div>\r\n","<div class=\"hw\">viscerātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[viscera]</div><div class=\"def\">ばらばらに.</div>\r\n","<div class=\"hw\">viscerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[viscera]</div><div class=\"def\">(公的な)食肉の配給[分配].</div>\r\n","<div class=\"hw\">viscidus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[viscum]</div><div class=\"def\">ねばねばする, 粘着性の.</div>\r\n","<div class=\"hw\">viscum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us<SUP>1</SUP></B> -ī, <i>m</i></div><div class=\"def\"><num>①</num> 〘植〙ヤドリギ.</div><div class=\"def\"><num>②</num> (ヤドリギの実で作った)鳥もち.</div>\r\n","<div class=\"hw\">viscus<SUP>2</SUP></div><div class=\"pos\">-ceris, <i>n</i></div><div class=\"def\">(一般に <i>pl</i> viscera)</div><div class=\"def\"><num>①</num> 肉.</div><div class=\"def\"><num>②</num> 内臓, はらわた.</div><div class=\"def\"><num>③</num> 子宮;睾丸.</div><div class=\"def\"><num>④</num> 実の子, 骨肉.</div><div class=\"def\"><num>⑤</num> 中枢, 中心[心臓]部, 内奥.</div>\r\n","<div class=\"hw\">viscātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[visco]</div><div class=\"def\"><num>①</num> 鳥もちを塗った.</div><div class=\"def\"><num>②</num> 何でもとらえる.</div><div class=\"def\"><num>③</num> からみつく, もつれる.</div>\r\n","<div class=\"hw\">viscō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[viscum]</div><div class=\"def\">(鳥もちなどで)身動きできなくさせる.</div>\r\n","<div class=\"hw\">viscōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://viscum\">viscum</a>]</div><div class=\"def\"><num>①</num> 鳥もちだらけの.</div><div class=\"def\"><num>②</num> ねばねばする.</div>\r\n","<div class=\"hw\">Visigothae</div><div class=\"pos\">-ārum, <b>Visigothī</b> -ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">ウィシゴタエ《西ゴート族の一支族;5世紀前半に Pyrene 山脈の南北にわたる王国を建設した》.</div>\r\n","<div class=\"hw\">vispillō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">=<a href=\"entry://vespillō\">vespillo</a>.</div>\r\n","<div class=\"hw\">Vistula</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ウィストゥラ《Germania と Sarmatia の境の川;現 Wisła》.</div>\r\n","<div class=\"hw\">Visurgis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ウィスルギス《Germania 北部の川;現 Weser》.</div>\r\n","<div class=\"hw\">Vitellia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウィテッリア《Latium の Aequi 族の町》.</div>\r\n","<div class=\"hw\">Vitellius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィテッリウス《ローマ人の氏族名;特に <i>Aulus ～</i>, ローマ皇帝(69年);Vespasianus に殺された》.</div><hr><div class=\"hw\">Vitellius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vitellius の.</div>\r\n","<div class=\"hw\">Vitelliānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vitellius の.</div>\r\n","<div class=\"hw\">Vitelliānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://Vitelliānus\">Vitelliānus</a>]</div><div class=\"def\"><num>①</num> Vitellius 支配下の兵士たち.</div><div class=\"def\"><num>②</num> 一種の書字板.</div>\r\n","<div class=\"hw\">vitellus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[vitulus]</div><div class=\"def\"><num>①</num> 小さな子牛.</div><div class=\"def\"><num>②</num> 卵黄.</div>\r\n","<div class=\"hw\">vitex</div><div class=\"pos\">-ticis, <i>f</i></div><div class=\"def\">〘植〙イタリアニンジンボク.</div>\r\n","<div class=\"hw\">vitilīgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[vitium]</div><div class=\"def\">〘病〙乾癬<SUB>かんせん</SUB>.</div>\r\n","<div class=\"hw\">vitilītigātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://vitilītigō\">vitilītigō</a>]</div><div class=\"def\">あら探し屋, あげ足取り屋.</div>\r\n","<div class=\"hw\">vitilītigō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[vitium/litigo]</div><div class=\"def\">あら探しをする, あげ足を取る.</div>\r\n","<div class=\"hw\">vitium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 欠点, 欠陥</div><div class=\"ex\">～ <i>corporis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">身体の欠陥.</span></div><div class=\"def\"><num>②</num> 過誤, 過失</div><div class=\"ex\"><i>vitio vertere [dare]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">過ちに数える[と見なす].</span></div><div class=\"def\"><num>③</num> 悪徳, 不品行</div><div class=\"ex\"><i>virtus est ～ fugere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">美徳とは悪徳を避けることだ.</span></div><div class=\"def\"><num>④</num> (女性への)暴行, 陵辱.</div><div class=\"def\"><num>⑤</num> 不吉[不十分]な鳥占い</div><div class=\"ex\"><i>vitio navigare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">鳥占いに逆らって航海する.</span></div>\r\n","<div class=\"hw\">vitiātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vitio]</div><div class=\"def\"><num>①</num> 汚染すること.</div><div class=\"def\"><num>②</num> (女性を)陵辱すること.</div>\r\n","<div class=\"hw\">vitiātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vitio]</div><div class=\"def\">(女性を)陵辱する者.</div>\r\n","<div class=\"hw\">vitiō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vitium]</div><div class=\"def\"><num>①</num> 害する, 損傷する;悪化させる.</div><div class=\"def\"><num>②</num> 偽造する.</div><div class=\"def\"><num>③</num> (処女を)陵辱する.</div><div class=\"def\"><num>④</num> 無効にする.</div>\r\n","<div class=\"hw\">vitiōsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vitiōsus\">vitiōsus</a>]</div><div class=\"def\"><num>①</num> 不品行, 悪徳.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 欠陥, 異常.</div>\r\n","<div class=\"hw\">vitiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vitium]</div><div class=\"def\"><num>①</num> 欠陥のある, 不完全な.</div><div class=\"def\"><num>②</num> 邪悪な, 堕落した.</div><div class=\"def\"><num>③</num> 不健康な, 病気の.</div><div class=\"def\"><num>④</num> 鳥占いに反した;(法的に)正規の手続きを踏んでいない</div><div class=\"ex\">～ <i>consul</i> (<author>C<small>IC</small></author>)<span class=\"ext\">鳥占いにそむいて選ばれた執政官.</span></div>\r\n","<div class=\"hw\">vitiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vitiosus]</div><div class=\"def\"><num>①</num> 誤って, 不正確に.</div><div class=\"def\"><num>②</num> (法的に)正規の手続きを踏まずに.</div>\r\n","<div class=\"hw\">vitreum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vitreus\">vitreus</a>]</div><div class=\"def\">ガラス製品.</div>\r\n","<div class=\"hw\">vitreus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vitrum<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> ガラス製の.</div><div class=\"def\"><num>②</num> ガラスのような, 透明な, きらめく</div><div class=\"ex\">～ <i>pontus</i> (<author>H<small>OR</small></author>)<span class=\"ext\">きらきら光る(青緑色の)海.</span></div><div class=\"def\"><num>③</num> 砕けやすい, もろい</div><div class=\"ex\"><i>vitrea fama</i> (<author>H<small>OR</small></author>)<span class=\"ext\">はかない名声.</span></div>\r\n","<div class=\"hw\">vitreārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vitreus]</div><div class=\"def\">ガラス細工師.</div>\r\n","<div class=\"hw\">vitrum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ガラス.</div><div class=\"def\"><num>②</num> ガラス製容器.</div><hr><div class=\"hw\">vitrum<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙タイセイ(大青)属の植物《その葉を青色染料とした》.</div>\r\n","<div class=\"hw\">vitta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vieo]</div><div class=\"def\"><num>①</num> ひも.</div><div class=\"def\"><num>②</num> 髪ひも, リボン.</div><div class=\"def\"><num>③</num> (聖職者・詩人・犠牲に供される人[獣]の)鉢巻き, 頭[額]に巻く帯.</div><div class=\"def\"><num>④</num> (祭壇・聖所・聖木の)注連<SUB>しめ</SUB>飾り, 飾りひも.</div><div class=\"def\"><num>⑤</num> 羊毛の房を巻きつけたオリーブの枝《嘆願者が手にする》.</div>\r\n","<div class=\"hw\">vittātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vitta\">vitta</a>]</div><div class=\"def\">髪ひもで束ねた;鉢巻きをした;注連<SUB>しめ</SUB>で飾られた.</div>\r\n","<div class=\"hw\">vitula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vitulus]</div><div class=\"def\">(雌の)子牛, 若い雌牛.</div>\r\n","<div class=\"hw\">vitulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 子牛.</div><div class=\"def\"><num>②</num> 子馬.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>～ marinus</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">アザラシ.</span></div><div class=\"def\"><num>④</num> (象・鯨の)子.</div>\r\n","<div class=\"hw\">vitulāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>cf. </i> vitulus]</div><div class=\"def\">新芽, 若枝.</div>\r\n","<div class=\"hw\">vitulīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vitulīnus\">vitulīnus</a>]</div><div class=\"def\">(<i>sc. </i> caro)子牛肉.</div>\r\n","<div class=\"hw\">vitulīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vitulus]</div><div class=\"def\">子牛(肉)の.</div>\r\n","<div class=\"hw\">vituperābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vitupero<SUP>1</SUP>]</div><div class=\"def\">非難に値する.</div>\r\n","<div class=\"hw\">vituperābiliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vituperābilis\">vituperābilis</a>]</div><div class=\"def\">非難に値するように.</div>\r\n","<div class=\"hw\">vituperātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vitupero<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 非難, 叱責.</div><div class=\"def\"><num>②</num> 非難に値する行為.</div>\r\n","<div class=\"hw\">vituperātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://vituperō\">vituperō<SUP>1</SUP></a>]</div><div class=\"def\">非難する人</div><div class=\"ex\"><i>philosophiae vituperatores</i> (<author>C<small>IC</small></author>)<span class=\"ext\">哲学の悪口を言う人々.</span></div>\r\n","<div class=\"hw\">vituperātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vitupero<SUP>1</SUP>]</div><div class=\"def\">非難する.</div>\r\n","<div class=\"hw\">vituperō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vitium/paro<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 非難する, けなす, 難癖をつける.</div><div class=\"def\"><num>②</num> 無効にする, 効力を失わせる.</div><hr><div class=\"hw\">vituperō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">=<a href=\"entry://vituperātor\">vituperator</a>.</div>\r\n","<div class=\"hw\">vitus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(車輪の)外縁<SUB>そとぶち</SUB>, 輪縁.</div>\r\n","<div class=\"hw\">vix</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 辛うじて, やっと.</div><div class=\"def\"><num>②</num> いやいや, 気乗りせずに.</div><div class=\"def\"><num>③</num> ほとんど...ない.</div><div class=\"def\"><num>④</num> ～ ... <i>cum [et]</i> ... ...するかしないかのうちに...</div><div class=\"ex\"><i>～ ea fatus erat, geminae cum columbae caelo venere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">彼がそれをほとんど言い終わらぬうちに2羽の鳩が天から舞い下りた.</span></div>\r\n","<div class=\"hw\">vixdum</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">(vix の強意形)</div><div class=\"def\"><num>①</num> 辛うじて, やっと;ほとんど...ない</div><div class=\"ex\"><i>Hannibalem ～ puberem</i> (<author>L<small>IV</small></author>)<span class=\"ext\">まだほんの青二才でしかなかった Hannibal を.</span></div><div class=\"def\"><num>②</num> ～ ... <i>cum [et]</i> ... ...するかしないかのうちに...</div><div class=\"ex\"><i>～ epistulam tuam legeram, cum Curtius venit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">きみの手紙をろくに読み終えないうちに Curtius がやって来た.</span></div>\r\n","<div class=\"hw\">vixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vīvescō\">vivesco</a>, <a href=\"entry://vīvō\">vivo</a>.</div>\r\n","<div class=\"hw\">viālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://via\">via</a>]</div><div class=\"def\">道路の</div><div class=\"ex\"><i>Lares viales</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">四つ辻に安置された Lares 像.</span></div>\r\n","<div class=\"hw\">viārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[via]</div><div class=\"def\">道路に関する</div><div class=\"ex\"><i>lex viaria</i> (<author>C<small>IC</small></author>)<span class=\"ext\">道路(の修繕)に関する法.</span></div>\r\n","<div class=\"hw\">viāticulum</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://viāticum\">viāticum</a>]</div><div class=\"def\">(わずかの)旅費, 路銀.</div>\r\n","<div class=\"hw\">viāticum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://viāticus\">viāticus</a>]</div><div class=\"def\"><num>①</num> 旅費, 路銀;旅行手当.</div><div class=\"def\"><num>②</num> (兵士の)貯金.</div><div class=\"def\"><num>③</num> 機略, 知謀.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(外国で勉強中の学生に親元から送られる)学資.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘カト〙臨終の聖体拝領.</div>\r\n","<div class=\"hw\">viāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[via]</div><div class=\"def\">旅の</div><div class=\"ex\"><i>cena viatica</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">旅行者の無事の帰還を祝う食事.</span></div>\r\n","<div class=\"hw\">viāticātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[viaticum]</div><div class=\"def\">旅費を支給された.</div>\r\n","<div class=\"hw\">viātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[via]</div><div class=\"def\"><num>①</num> 旅人, 旅行者.</div><div class=\"def\"><num>②</num> (高級行政官に仕える)下役人, 伝達吏.</div>\r\n","<div class=\"hw\">viātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://viātor\">viātor</a>]</div><div class=\"def\"><num>①</num> 旅行(者)用の.</div><div class=\"def\"><num>②</num> 《碑》下役人[伝達吏]の.</div>\r\n","<div class=\"hw\">viētus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vieo]</div><div class=\"def\">しなびた, しわの寄った, 縮んだ.</div>\r\n","<div class=\"hw\">viō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[via]</div><div class=\"def\">旅をする.</div>\r\n","<div class=\"hw\">Vocetius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウォケティウス《Helvetia の山》.</div>\r\n","<div class=\"hw\">vocimus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(梨の品種名として)</div><div class=\"ex\"><i>pirum vocimum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">緑色で長円形の梨.</span></div>\r\n","<div class=\"hw\">vocitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr, intr freq</i></div><div class=\"ori\">[voco]</div><div class=\"def\"><num>①</num> 習慣的に...と叫ぶ</div><div class=\"ex\"><i>has Graeci stellas Hyadas vocitare suerunt</i> (<author>C<small>IC</small></author>)<span class=\"ext\">これらの星をギリシア人は Hyades と呼び慣わしていた.</span></div><div class=\"def\"><num>②</num> 大声で呼ぶ.</div>\r\n","<div class=\"hw\">Vocontius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Vocontii 族の.</div>\r\n","<div class=\"hw\">Vocontiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウォコンティイー《Gallia Narbonensis の Rhodanus 川と Alpes 山脈の間(ほぼ現在の Vaucluse 県)にいた一部族》.</div>\r\n","<div class=\"hw\">vocābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[voco]</div><div class=\"def\">響きのよい.</div>\r\n","<div class=\"hw\">vocābulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[voco]</div><div class=\"def\"><num>①</num> 名称, 名前.</div><div class=\"def\"><num>②</num> 〘文〙実(名)詞, 名詞.</div>\r\n","<div class=\"hw\">vocāmen</div><div class=\"pos\">-inis, <i>n</i></div><div class=\"ori\">[voco]</div><div class=\"def\">(物の)名, 名称.</div>\r\n","<div class=\"hw\">vocātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[voco]</div><div class=\"def\"><num>①</num> 〘法〙呼び出し, 召喚.</div><div class=\"def\"><num>②</num> (食事への)招待.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 召命, 天職.</div>\r\n","<div class=\"hw\">vocātor</div><div class=\"pos\">-ōris</div><div class=\"ori\">[voco]</div><div class=\"def\"><num>①</num> 招待状を届ける係.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(神の国へ)呼び招く人.</div>\r\n","<div class=\"hw\">vocātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vocō\">voco</a>.</div><hr><div class=\"hw\">vocātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 呼びかけ.</div><div class=\"def\"><num>②</num> 呼び出し, 召集.</div><div class=\"def\"><num>③</num> 招待.</div>\r\n","<div class=\"hw\">Vocātēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">ウォカーテース《Aquitania にいた一部族》.</div>\r\n","<div class=\"hw\">vocātīvus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[voco]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 呼びかけの.</div><div class=\"def\"><num>②</num> 〘文〙呼格の</div><div class=\"ex\"><i>casus ～</i> (<author>G<small>ELL</small></author>)<span class=\"ext\">呼格.</span></div><hr><div class=\"hw\">vocātīvus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(<i>sc. </i> casus)〘文〙呼格.</div>\r\n","<div class=\"hw\">vocātīvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://vocātīvus\">vocātīvus<SUP>1</SUP></a>]</div><div class=\"def\">〘文〙呼格形で.</div>\r\n","<div class=\"hw\">vocīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《古形》=<a href=\"entry://vacīvus\">vacivus</a>.</div>\r\n","<div class=\"hw\">vocō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vox]</div><div class=\"def\"><num>①</num> 呼ぶ, 呼び寄せる;召集する.</div><div class=\"def\"><num>②</num> (神の名を)唱える, 祈る.</div><div class=\"def\"><num>③</num> (名を呼んで)話しかける.</div><div class=\"def\"><num>④</num> (法廷へ)召喚する.</div><div class=\"def\"><num>⑤</num> 招待する.</div><div class=\"def\"><num>⑥</num> 要求する.</div><div class=\"def\"><num>⑦</num> 挑む;促す, そそのかす</div><div class=\"ex\"><i>quam in spem me vocas?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私にどんな希望を持てとあなたは言われるのですか.</span></div><div class=\"def\"><num>⑧</num> (ある状況[状態]に)導く</div><div class=\"ex\"><i>Italiam totam ad exitium vocas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">おまえは全イタリアを破滅させようとしているのだ.</span></div><div class=\"def\"><num>⑨</num> ...を...と名づける[呼ぶ]</div><div class=\"ex\"><i>sanus tu non es qui furem me vocas</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">あなたは正気じゃない, 私を泥棒呼ばわりするなんて.</span></div>\r\n","<div class=\"hw\">Vocōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウォコーニウス《ローマ人の氏族名;特に <i>Q. ～ Saxa</i>, 前169年の護民官》.</div>\r\n","<div class=\"hw\">voisgra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">未詳の鳥.</div>\r\n","<div class=\"hw\">vola</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 手のひら;手のひらのくぼみ.</div><div class=\"def\"><num>②</num> 足裏のくぼみ, 土踏まず.</div>\r\n","<div class=\"hw\">volaemum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://volēmum\">volemum</a>.</div>\r\n","<div class=\"hw\">volantēs</div><div class=\"pos\">-um, <i>m, f pl</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\">空を飛ぶもの, 鳥類.</div>\r\n","<div class=\"hw\">Volcae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">ウォルカエ《Gallia Narbonensis にいた強力な部族;<i>～ Arecomici</i>(現 Nîmes 付近)と <i>～ Tectosages</i>(現 Toulouse 付近)に分かれていた》.</div>\r\n","<div class=\"hw\">Volcentānī, Vulc-</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\"><num>①</num> Volceii の住民.</div><div class=\"def\"><num>②</num> Etruria 人.</div>\r\n","<div class=\"hw\">Volcientēs, Vulc-</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\"><num>①</num> Volceii の住民.</div><div class=\"def\"><num>②</num> Volci の住民.</div>\r\n","<div class=\"hw\">Volcānius, Vulc-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Volcanus の</div><div class=\"ex\"><i>arma Volcania</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Volcanus が Achilles のために作った武器.</span></div><div class=\"def\"><num>②</num> 火の, 火炎の.</div>\r\n","<div class=\"hw\">Volcānus, Vulc-</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 〘神話〙ウォルカーヌス《火と鍛冶の神;Juppiter と Juno の子で Venus の夫;ギリシア神話の Hephaistos と同一視された》.</div><div class=\"def\"><num>②</num> 火, 火炎.</div>\r\n","<div class=\"hw\">Volcānālia, Vulc-</div><div class=\"pos\">-ium [-iōrum], <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://Volcānālis\">Volcānālis, Vulc-</a>]</div><div class=\"def\">(<i>sc</i>. festa)Volcanus の祭典《毎年8月23日に催された》.</div>\r\n","<div class=\"hw\">Volcānālis, Vulc-</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Volcanus の.</div>\r\n","<div class=\"hw\">Volcēiī, Vulc-</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウォルケーイイー《Lucania の町;現 Buccino》.</div>\r\n","<div class=\"hw\">Volcī, Vulc-</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウォルキー《Etruria の町》.</div>\r\n","<div class=\"hw\">volens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[volo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 望んでいる, 進んでする, 自発的な</div><div class=\"ex\"><i>seu ～ seu invitus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">その気があろうとなかろうと</span></div><div class=\"ex\"><i>volentes parent</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼らは自分の意志で従う</span></div><div class=\"ex\"><i>volenti animo</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">熱意をもって.</span></div><div class=\"def\"><num>②</num> <i>alqd est alci volenti</i> あることがある人に願わしい[好都合だ]</div><div class=\"ex\"><i>quibusdam volentibus novas res fore</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ある人々には政変は歓迎すべき事態であろう.</span></div><div class=\"def\"><num>③</num> (神々が)好意的な, 恵み深い</div><div class=\"ex\"><i>dis volentibus</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">神々のご加護のもとに.</span></div>\r\n","<div class=\"hw\">volenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://volens\">volens</a>]</div><div class=\"def\">自発的に, 進んで.</div>\r\n","<div class=\"hw\">volentia<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[volens]</div><div class=\"def\">意志, 意向.</div><hr><div class=\"hw\">volentia<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">望み通りの[好都合な]事柄 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">volg-</div><div class=\"def\">⇒vulg-.</div>\r\n","<div class=\"hw\">volitātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://volitō\">volitō</a>]</div><div class=\"def\"><num>①</num> あちこち走り[飛び]回ること.</div><div class=\"def\"><num>②</num> (木の葉が)ひらひら舞い落ちること.</div>\r\n","<div class=\"hw\">volitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> あちこち飛び回る</div><div class=\"ex\"><i>volucres volitare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">鳥たちが飛び回る</span></div><div class=\"ex\"><i>umbras inter vivos volitare</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">亡霊が生きている人々の間を飛び交う.</span></div><div class=\"def\"><num>②</num> (物が)空中をすばやく動く;(うわさなどが)急速に広まる.</div><div class=\"def\"><num>③</num> あちこち動き[走り]回る, 徘徊する</div><div class=\"ex\"><i>illa conjuratio palam volitat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あの陰謀が大手をふって闊歩<SUB>かっぽ</SUB>している.</span></div><div class=\"def\"><num>④</num> (気分が)高揚する.</div>\r\n","<div class=\"hw\">voln-</div><div class=\"def\">⇒vuln-.</div>\r\n","<div class=\"hw\">Vologēsus</div><div class=\"pos\">-ī, <B>Vologesēs</B> -is, <i>m</i></div><div class=\"def\">ウォロゲースス《Arsacidae に属する数名の Parthia 王の名;特に ～<i>I</i>(在位51頃‐79)》.</div>\r\n","<div class=\"hw\">volpēs</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://vulpēs\">vulpes</a>.</div>\r\n","<div class=\"hw\">Volscus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Volsci 族の.</div>\r\n","<div class=\"hw\">Volscī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウォルスキー《Latium 南部にいた有力な部族;前5世紀から前4世紀にかけてローマに征服された》.</div>\r\n","<div class=\"hw\">volsella</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(小さな)鉗子<SUB>かんし</SUB>, ピンセット.</div>\r\n","<div class=\"hw\">Volsiniensis, Vuls-</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Volsinii の.</div><div class=\"hw2\"><b>Volsiniensēs, Vuls-</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Volsinii の住民.</div>\r\n","<div class=\"hw\">Volsiniī, Vuls-</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウォルシニイー《Etruria の町;現 Orvieto の近辺》.</div>\r\n","<div class=\"hw\">volsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">=<a href=\"entry://vulsus\">vulsus</a>.</div>\r\n","<div class=\"hw\">volt</div><div class=\"def\">《古形》=<a href=\"entry://vult\">vult</a>(⇒ <a href=\"entry://volō\">volo<SUP>2</SUP></a>).</div>\r\n","<div class=\"hw\">Voltiniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Voltinia tribus に属する.</div><div class=\"hw2\"><b>Voltiniensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Voltinia tribus に属する市民たち.</div>\r\n","<div class=\"hw\">Voltinius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><i>Voltinia tribus</i> (<author>C<small>IC</small></author>) ローマの地縁的部族の一つ《地域不祥》.</div>\r\n","<div class=\"hw\">voltis</div><div class=\"def\">《古形》=vultis(⇒ <a href=\"entry://volō\">volo<SUP>2</SUP></a>).</div>\r\n","<div class=\"hw\">voltu-</div><div class=\"def\">⇒vultu-.</div>\r\n","<div class=\"hw\">Voltu-</div><div class=\"def\">⇒Vultu-.</div>\r\n","<div class=\"hw\">Voltumna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウォルトゥムナ《Etruria 人の女神;その神殿で Etruria 同盟会議が開かれた》.</div>\r\n","<div class=\"hw\">volucer<SUP>1</SUP></div><div class=\"pos\">-cris -cre, <i>adj</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 飛ぶことができる, 翼のある</div><div class=\"ex\"><i>bestiae volucres</i> (<author>C<small>IC</small></author>)<span class=\"ext\">鳥類.</span></div><div class=\"def\"><num>②</num> (飛ぶように)速い, 迅速な.</div><div class=\"def\"><num>③</num> 速やかに過ぎ去る, はかない.</div>\r\n","<div class=\"hw\">volucris</div><div class=\"pos\">-is, <i>f</i>, <B>volucer<SUP>2</SUP></B> -cris, <i>m</i></div><div class=\"ori\">[volucer<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 翼のある動物(=鳥)</div><div class=\"ex\"><i>volucris Junonis [Junonia]</i> (<author>O<small>V</small></author>)<span class=\"ext\">クジャク.</span></div><div class=\"def\"><num>②</num> 〘天〙白鳥座(Cycnus);(<i>pl</i>)白鳥座と鷲座(Aquila).</div><div class=\"def\"><num>③</num> 〘昆〙ハチ(蜂);ハエ(蝿).</div>\r\n","<div class=\"hw\">volucriter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[volucer<SUP>1</SUP>]</div><div class=\"def\">速やかに.</div>\r\n","<div class=\"hw\">volucritās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[volucer<SUP>1</SUP>]</div><div class=\"def\">速やかな飛翔.</div>\r\n","<div class=\"hw\">Volumna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウォルムナ《新生児の守護女神》.</div>\r\n","<div class=\"hw\">Volumnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウォルムニア《Coriolanus の妻》.</div>\r\n","<div class=\"hw\">Volumnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウォルムニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">voluntārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://voluntās\">voluntās</a>]</div><div class=\"def\"><num>①</num> 自由意志で行なう, 自発的な</div><div class=\"ex\"><i>servi voluntarii</i> (<author>C<small>IC</small></author>)<span class=\"ext\">奴隷のように従順な人々.</span></div><div class=\"def\"><num>②</num> 自発的に行なわれた</div><div class=\"ex\"><i>mors voluntaria</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自殺.</span></div>\r\n","<div class=\"hw\">voluntāriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[voluntarius]</div><div class=\"def\">自発的に.</div>\r\n","<div class=\"hw\">voluntāriī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://voluntārius\">voluntārius</a>]</div><div class=\"def\">(<i>sc. </i> milites)志願兵.</div>\r\n","<div class=\"hw\">voluntās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[volo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 意志, 欲求, 願望</div><div class=\"ex\"><i>voluntate(suā)</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自分の意志で, 自発的に</span></div><div class=\"ex\"><i>ex voluntate majoris fili</i> (<author>S<small>UET</small></author>)<span class=\"ext\">長男の意向で</span></div><div class=\"ex\"><i>contra suam voluntatem</i> (<author>C<small>AES</small></author>)<span class=\"ext\">自らの意志に反して.</span></div><div class=\"def\"><num>②</num> (人・物に対する)気持, 心情.</div><div class=\"def\"><num>③</num> 好意, 共感, 愛情</div><div class=\"ex\"><i>mutua ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">相互の好意.</span></div><div class=\"def\"><num>④</num> 同意, 是認</div><div class=\"ex\"><i>ejus voluntate</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼の賛同を得て.</span></div><div class=\"def\"><num>⑤</num> 遺言.</div><div class=\"def\"><num>⑥</num> (演説・文書の)意味, 趣旨.</div>\r\n","<div class=\"hw\">voluntātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://voluntās\">voluntās</a>]</div><div class=\"def\">意志を表わす</div><div class=\"ex\"><i>verba voluntativa</i> (<author>P<small>RISC</small></author>)<span class=\"ext\">〘文〙意志動詞.</span></div>\r\n","<div class=\"hw\">volup</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>cf. </i> voluptas]</div><div class=\"def\">喜んで, 愉快に</div><div class=\"ex\"><i>～ esse</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">楽しい, うれしい.</span></div>\r\n","<div class=\"hw\">Volupia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウォルピア《快楽の女神》.</div>\r\n","<div class=\"hw\">voluptificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://voluptās\">voluptās</a>/facio]</div><div class=\"def\">快楽を与える.</div>\r\n","<div class=\"hw\">voluptuārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://voluptārius\">voluptarius<SUP>1</SUP> 3</a>.</div>\r\n","<div class=\"hw\">voluptuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[voluptas]</div><div class=\"def\">喜び[楽しみ]をもたらす, 喜ばしい.</div>\r\n","<div class=\"hw\">voluptuōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://voluptuōsus\">voluptuōsus</a>]</div><div class=\"def\">喜びとともに, 喜んで.</div>\r\n","<div class=\"hw\">voluptābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[voluptas]</div><div class=\"def\">喜ばしい.</div>\r\n","<div class=\"hw\">voluptārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[voluptas]</div><div class=\"def\"><num>①</num> 快楽を与える, 楽しい.</div><div class=\"def\"><num>②</num> 快楽に関する.</div><div class=\"def\"><num>③</num> 快楽にふける, 快楽を好む</div><div class=\"ex\"><i>Epicurus homo～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">快楽を追究する人である Epicurus.</span></div><hr><div class=\"hw\">voluptārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">快楽[気晴らし]にふける人.</div>\r\n","<div class=\"hw\">voluptāriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://voluptārius\">voluptārius<SUP>1</SUP></a>]</div><div class=\"def\">快楽にふけって.</div>\r\n","<div class=\"hw\">voluptās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[volup]</div><div class=\"def\"><num>①</num> 喜び, 楽しみ, 満足</div><div class=\"ex\"><i>amicitiae ～</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">友情の喜び</span></div><div class=\"ex\"><i>lectionis ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">読書の楽しみ</span></div><div class=\"ex\"><i>potandi ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">盃を傾ける喜び</span></div><div class=\"ex\"><i>corporis ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">肉体的快楽</span></div><div class=\"ex\">(predic dat)<i>quod mihi magnae voluptati fuit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">それは私の大きな喜びであった.</span></div><div class=\"def\"><num>②</num> (V-)(神格化されて)快楽の女神.</div><div class=\"def\"><num>③</num> (親愛の表現として)いとしい人</div><div class=\"ex\"><i>mea ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">私の喜び.</span></div><div class=\"def\"><num>④</num> (<i>pl</i>)見せ物, 催し物.</div><div class=\"def\"><num>⑤</num> 性交;精液.</div>\r\n","<div class=\"hw\">Volusius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウォルシウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">voluī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://volō\">volo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">volva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://vulva\">vulva</a>.</div>\r\n","<div class=\"hw\">volvola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://volvō\">volvō</a>]</div><div class=\"def\">〘植〙サンシキヒルガオ属の植物の総称(=<a href=\"entry://convolvulus\">convolvulus</a>).</div>\r\n","<div class=\"hw\">volvula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://vulvula\">vulvula</a>.</div>\r\n","<div class=\"hw\">volvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://volvō\">volvo</a>.</div>\r\n","<div class=\"hw\">volvō</div><div class=\"pos\">-ere volvī volūtum, <i>tr(intr)</i></div><div class=\"def\"><num>①</num> 転がす, 転がして運ぶ</div><div class=\"ex\"><i>amnis volvit sub undis grandia saxa</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">(増水した)川は水流で巨岩を転がす.</span></div><div class=\"def\"><num>②</num> 転がして作る</div><div class=\"ex\"><i>scarabaeus pilas volvit</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">フンコロガシは(フンを)転がして玉をつくる.</span></div><div class=\"def\"><num>③</num> (<i>pass</i>)転がる, 回転する;(蛇が)くねって進む</div><div class=\"ex\"><i>volvuntur stellarum cursūs sempiterni</i> (<author>C<small>IC</small></author>)<span class=\"ext\">星々の永遠の道が巡っている</span></div><div class=\"ex\"><i>lacrimae volvuntur inanes</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">涙がむなしくこぼれ落ちる.</span></div><div class=\"def\"><num>④</num> (<i>pass</i>)(屈服して)はいつくばる.</div><div class=\"def\"><num>⑤</num> (炎・煙などを)渦巻かせる, 立ち昇らせる</div><div class=\"ex\"><i>Vesuvius volvens incendia</i> (<author>S<small>TAT</small></author>)<span class=\"ext\">渦巻く炎を噴き上げる Vesuvius 火山.</span></div><div class=\"def\"><num>⑥</num> 巻き込む, 包む</div><div class=\"ex\"><i>volvitur in flammis</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">火炎に包まれる.</span></div><div class=\"def\"><num>⑦</num> ひき起こす, なし遂げる</div><div class=\"ex\"><i>volventes frigora fontes</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">冷気を湧き出させる泉</span></div><div class=\"ex\"><i>ubi mille rotam volvēre per annos</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(霊魂たちが)千年の時の輪を巡り終えたとき.</span></div><div class=\"def\"><num>⑧</num> (運命が)定める</div><div class=\"ex\"><i>sic volvere Parcas</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">これが運命の三女神の定めである.</span></div><div class=\"def\"><num>⑨</num> (時を)経過させる</div><div class=\"ex\"><i>luna volvit menses</i> (<author>H<small>OR</small></author>)<span class=\"ext\">月は歳月を流れさせる.</span></div><div class=\"def\"><num>⑩</num> 回転して進む;(時が)経過する</div><div class=\"ex\"><i>tarda volventia plaustra</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">ゆっくり進む荷車</span></div><div class=\"ex\"><i>volventibus annis</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">年が経つうちに.</span></div><div class=\"def\"><num>⑪</num> (目・視線を)さまよわせる</div><div class=\"ex\"><i>huc illuc volvens oculos</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">目をあちらこちらにさまよわせて.</span></div><div class=\"def\"><num>⑫</num> (書巻を)ひもとく</div><div class=\"ex\"><i>volvendi sunt libri Catonis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Cato の書が読まれるべきだ.</span></div><div class=\"def\"><num>⑬</num> </div><div class=\"ex\"><i>orbem volvere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">〘軍〙円陣を組む.</span></div><div class=\"def\"><num>⑭</num> よどみなく語る[弁論する].</div><div class=\"def\"><num>⑮</num> 思いめぐらす, 熟考する.</div>\r\n","<div class=\"hw\">volābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\">飛ぶことができる.</div>\r\n","<div class=\"hw\">Volāterrae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ウォラーテッラエ《Etruria の町;現 Volterra》.</div>\r\n","<div class=\"hw\">Volāterrānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Volaterrae の.</div><div class=\"hw2\"><b>Volāterrānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Volaterrae の住民.</div>\r\n","<div class=\"hw\">volātica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://volāticus\">volāticus</a>]</div><div class=\"def\"><num>①</num> 魔女.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 魔術.</div>\r\n","<div class=\"hw\">volāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 空を飛ぶ, 翼のある.</div><div class=\"def\"><num>②</num> 突然の, 不意をついた.</div><div class=\"def\"><num>③</num> 移り気な, 気まぐれな.</div>\r\n","<div class=\"hw\">volātile</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://volātilis\">volātilis</a>]</div><div class=\"def\">空を飛ぶもの, 鳥.</div>\r\n","<div class=\"hw\">volātilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 空を飛ぶ, 翼のある</div><div class=\"ex\"><i>puer ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">空を飛ぶ少年(=<a href=\"entry://Cupīdō\">Cupido</a>).</span></div><div class=\"def\"><num>②</num> 過ぎて行く, 移ろいやすい.</div>\r\n","<div class=\"hw\">volātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\">飛ぶこと, 飛翔.</div>\r\n","<div class=\"hw\">volātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[volo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 飛ぶこと, 飛翔</div><div class=\"ex\"><i>avium voces volatūsque interrogare</i> (<author>T<small>AC</small></author>)<span class=\"ext\">(神意を)鳥の声や飛び方に問う.</span></div><div class=\"def\"><num>②</num> 急速な動き.</div>\r\n","<div class=\"hw\">volātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 飛ぶこと, 飛翔.</div><div class=\"def\"><num>②</num> 鳥類.</div>\r\n","<div class=\"hw\">volēmum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vola]</div><div class=\"def\">(手のひらにあまるほどの)大ぶりの梨.</div>\r\n","<div class=\"hw\">volō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> 飛ぶ.</div><div class=\"def\"><num>②</num> 飛ぶように走る, 急ぐ.</div><div class=\"def\"><num>③</num> (時が)早く過ぎ去る</div><div class=\"ex\"><i>volat aetas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一生はいつしか過ぎる.</span></div><hr><div class=\"hw\">volō<SUP>2</SUP></div><div class=\"pos\">velle voluī, <i>tr, intr</i></div><div class=\"def\">(volt 《古形》=vult, voltis 《古形》=vultis;vīn=vīsne, sīs=sī vīs, sultis=sī vultis)〈+<i>acc</i>;+<i>inf</i>;+<i>acc c. inf</i>;ut, ne;+<i>juss subj</i>〉</div><div class=\"def\"><num>①</num> 欲する, 望む, 願う</div><div class=\"def\"><num1>⒜</num1> </div><div class=\"ex\"><i>tarde velle nolentis est</i> (<author>S<small>EN</small></author>)<span class=\"ext\">望みを遅らせるのは望まない者のすることだ</span></div><div class=\"ex\"><i>pacem velle</i> (<author>C<small>IC</small></author>)<span class=\"ext\">平和を願う</span></div><div class=\"ex\"><i>hoc volunt persuadere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼らはこの点を説得したいと願っている</span></div><div class=\"ex\">(過去時称で願いが実現しなかったことを表わす)<i>volebam gratiam referre, sed...</i> (<author>S<small>EN</small></author>)<span class=\"ext\">私は恩返しをしようと思ったが, しかし...</span></div><div class=\"ex\"><i>interfici Caesarem voluisse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Caesar の殺害を願ったこと</span></div><div class=\"ex\"><i>～ uti mihi respondeas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなたは私に答えてほしい</span></div><div class=\"ex\"><i>～ ames meam constantiam</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の志操堅固なところをほめて下さい.</span></div><div class=\"def\"><num1>⒝</num1> (...との面談を)望む</div><div class=\"ex\"><i>centuriones me velle</i> (<author>C<small>IC</small></author>)<span class=\"ext\">百人隊長たちが私に会いたがっている.</span></div><div class=\"def\"><num1>⒞</num1> <i>bene [male] velle alci</i> ある人に好意[悪意]をいだく.</div><div class=\"def\"><num1>⒟</num1> <i>velim</i>(おだやかな命令・願望を表わす)...してもらいたいのだが, ...であればいいのだが</div><div class=\"ex\"><i>tu velim saepe ad nos scribas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">どうか私にたびたび手紙を書いて下さい.</span></div><div class=\"def\"><num1>⒠</num1> <i>vellem</i>(実現しなかった願望を表わす)...であればよかったのに</div><div class=\"ex\"><i>abiit? vah</i>, <i>rogasse vellem</i> (<author>T<small>ER</small></author>)<span class=\"ext\">行ってしまったって? ああ, たずねておきたかったのに.</span></div><div class=\"def\"><num1>⒡</num1> (慣用表現)<i>velim nolim [velis nolis, velit nolit</i> etc.] 望もうが望むまいが, いやでも応でも</div><div class=\"ex\"><i>quid vis?</i><span class=\"ext\">どんなご用向きですか</span></div><div class=\"ex\"><i>numquid(aliud)me vis?</i><span class=\"ext\">私に(他に)何かご用がありますか, もうご用はありませんね(暇乞いの決まり文句)</span></div><div class=\"ex\"><i>si vis [vultis]</i><span class=\"ext\">よろしければ, どうかお願いですから.</span></div><div class=\"def\"><num>②</num> 定める, 命じる</div><div class=\"ex\"><i>majores de singulis magistratibus bis vos sententiam ferre voluerunt</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(われらの)祖父たちは諸君が個々の官職につき2度投票すべしと定めた.</span></div><div class=\"def\"><num>③</num> (しかじかの)意見[見解]を持つ, 主張する</div><div class=\"ex\"><i>vultis evenire omnia fato</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すべては運命によって生起すると諸君は主張する.</span></div><div class=\"def\"><num>④</num> むしろ...の方を選ぶ(=<a href=\"entry://mālō\">malo</a>)</div><div class=\"ex\"><i>judicem se quam oratorem vult laudari</i> (<author>A<small>UR</small></author>)<span class=\"ext\">彼の望みは弁士としてより判事として賞賛されることだ.</span></div><div class=\"def\"><num>⑤</num> 意図する;意味する 〈sibi〉</div><div class=\"ex\"><i>quid vult concursus ad amnem?</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(亡霊どもが)流れに殺到しているのは何のためか</span></div><div class=\"ex\"><i>illae quid sibi statuae equestres inauratae volunt?</i><span class=\"ext\">あれらの金めっきした騎馬像は一体何の意味だ.</span></div><hr><div class=\"hw\">volō<SUP>3</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://volō\">volō<SUP>2</SUP></a>]</div><div class=\"def\">奴隷の志願兵《ローマ軍が Cannae の戦い(前216)で惨敗したあと, 国費で身分を解放されて兵卒となった》.</div>\r\n","<div class=\"hw\">volūbilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[volvo]</div><div class=\"def\"><num>①</num> 回転する</div><div class=\"ex\"><i>volubile buxum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">こま(独楽).</span></div><div class=\"def\"><num>②</num> 転がりやすい;変わりやすい.</div><div class=\"def\"><num>③</num> ぐるぐる巻いた.</div><div class=\"def\"><num>④</num> 流れる;流暢な.</div>\r\n","<div class=\"hw\">volūbiliter</div><div class=\"pos\"><i>adj</i></div><div class=\"ori\">[volubilis]</div><div class=\"def\">流暢に, よどみなく.</div>\r\n","<div class=\"hw\">volūbilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://volūbilis\">volūbilis</a>]</div><div class=\"def\"><num>①</num> 回転していること, 回転.</div><div class=\"def\"><num>②</num> 丸いこと, 丸み.</div><div class=\"def\"><num>③</num> 変わりやすいこと.</div><div class=\"def\"><num>④</num> 流暢.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>(時の)流れ.</div>\r\n","<div class=\"hw\">volūcra</div><div class=\"pos\">-ae, <i>f</i>, <B>volūcre</B> -is, <i>n</i></div><div class=\"ori\">[volvo]</div><div class=\"def\">〘昆〙ハマキガ(葉巻き蛾)《その幼虫がブドウの葉を巻くので嫌われる》.</div>\r\n","<div class=\"hw\">volūmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[volvo]</div><div class=\"def\"><num>①</num> パピルス紙の巻き物, 書物</div><div class=\"ex\">～ <i>explicare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">巻き物を広げる[ひもとく].</span></div><div class=\"def\"><num>②</num> (著作の)一部, 巻<SUB>かん</SUB>.</div><div class=\"def\"><num>③</num> (水・煙などの)渦;(蛇の)とぐろ.</div><div class=\"def\"><num>④</num> 回転(運動);変転.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>(時の)流れ.</div>\r\n","<div class=\"hw\">volūminōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://volūmen\">volūmen</a>]</div><div class=\"def\">とぐろを巻く.</div>\r\n","<div class=\"hw\">volūta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[volvo]</div><div class=\"def\">〘建〙(イオニア式・コリント式柱頭装飾の)渦形, 渦巻き.</div>\r\n","<div class=\"hw\">volūtim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[volvo]</div><div class=\"def\">転げ回って.</div>\r\n","<div class=\"hw\">volūtus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://volvō\">volvo</a>.</div><hr><div class=\"hw\">volūtus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">(ヘビが)体をくねらせて進むこと.</div>\r\n","<div class=\"hw\">volūtābrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[voluto]</div><div class=\"def\">(豚が好んで転げ回る)ぬかるみ.</div>\r\n","<div class=\"hw\">volūtābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[voluto]</div><div class=\"def\">転げ回る.</div>\r\n","<div class=\"hw\">volūtātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[voluto]</div><div class=\"def\"><num>①</num> 転げ回ること;回転運動.</div><div class=\"def\"><num>②</num> 落ちつきのなさ;不安定.</div>\r\n","<div class=\"hw\">volūtātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://volūtō\">voluto</a>.</div><hr><div class=\"hw\">volūtātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">転げ回ること.</div>\r\n","<div class=\"hw\">volūtō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr, intr freq</i></div><div class=\"ori\">[volvo]</div><div class=\"def\"><num>①</num> 転がす</div><div class=\"ex\"><i>toto monte volutare difficile onus</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">(Sisyphus が)大石を山頂まで転がし[押し]上げる.</span></div><div class=\"def\"><num>②</num> (<i>refl, pass</i>)転がる, 転げ回る, のたくる.</div><div class=\"def\"><num>③</num> (<i>pass</i>)もがく, あがく.</div><div class=\"def\"><num>④</num> (声・音などを)鳴り響かせる;(ことばを)広める.</div><div class=\"def\"><num>⑤</num> 没頭させる 〈in re〉.</div><div class=\"def\"><num>⑥</num> 考えをめぐらす, 熟考する.</div><div class=\"def\"><num>⑦</num> 転がる</div><div class=\"ex\"><i>leone obvio suppliciter volutante</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ライオンは(彼の)前に嘆願するかのように寝転がって.</span></div>\r\n","<div class=\"hw\">vomax</div><div class=\"pos\">-ācis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vomo]</div><div class=\"def\">吐き癖のある.</div>\r\n","<div class=\"hw\">vomica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vomo]</div><div class=\"def\"><num>①</num> 〘病〙膿瘍<SUB>のうよう</SUB>;おでき.</div><div class=\"def\"><num>②</num> (水銀のように)鉱石中に閉じこめられた液体.</div><div class=\"def\"><num>③</num> 災厄, 禍根.</div>\r\n","<div class=\"hw\">vomicōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vomica\">vomica</a>]</div><div class=\"def\">膿瘍の多い.</div>\r\n","<div class=\"hw\">vomificus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vomo/facio]</div><div class=\"def\">吐き気を催させる.</div>\r\n","<div class=\"hw\">vomifluus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vomo/fluo]</div><div class=\"def\">膿<SUB>うみ</SUB>を出す</div><div class=\"ex\"><i>vomiflua passio</i> (<author>C<small>AEL</small> A<small>UR</small></author>)<span class=\"ext\">〘病〙膿瘍.</span></div>\r\n","<div class=\"hw\">vomitiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vomo]</div><div class=\"def\">〘病〙嘔吐;吐物<SUB>とぶつ</SUB>.</div>\r\n","<div class=\"hw\">vomitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vomo]</div><div class=\"def\">嘔吐する人.</div>\r\n","<div class=\"hw\">vomitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vomō\">vomo</a>.</div><hr><div class=\"hw\">vomitus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 〘医〙嘔吐</div><div class=\"ex\"><SUP>◇</SUP><i>～ gravidarum</i><span class=\"ext\">妊婦嘔吐, つわり.</span></div><div class=\"def\"><num>②</num> 吐物.</div>\r\n","<div class=\"hw\">vomitīvum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘薬〙催吐<SUB>さいと</SUB>剤.</div>\r\n","<div class=\"hw\">vomitō</div><div class=\"pos\">-āre, <i>intr freq</i></div><div class=\"ori\">[vomo]</div><div class=\"def\">頻繁に吐く.</div>\r\n","<div class=\"hw\">vomitōria</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[vomitorius]</div><div class=\"def\">(円形競技場・劇場の)出入口.</div>\r\n","<div class=\"hw\">vomitōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vomitōrius\">vomitōrius</a>]</div><div class=\"def\">催吐剤.</div>\r\n","<div class=\"hw\">vomitōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vomo]</div><div class=\"def\">吐き気を催させる.</div>\r\n","<div class=\"hw\">vomuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vomō\">vomo</a>.</div>\r\n","<div class=\"hw\">vomō</div><div class=\"pos\">-mere -muī -mitum, <i>intr, tr</i></div><div class=\"def\"><num>①</num> 吐き気がする;嘔吐する.</div><div class=\"def\"><num>②</num> (食べた物を)吐き戻す.</div><div class=\"def\"><num>③</num> (水・炎・煙などを)吐く, 吐き出す.</div>\r\n","<div class=\"hw\">Vonōnēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ウォノーネース《1世紀の二人の Parthia 王の名》.</div>\r\n","<div class=\"hw\">vopiscus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">双生児の一方が早産か流産で死んだあと無事に生まれた残りの子.</div>\r\n","<div class=\"hw\">Vopiscus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウォピスクス《ローマ人の家名;特に (1) <i>Julius</i> ～, 前473年の統領.(2) <SUP>◇</SUP><i>Flavius</i> ～, <i>Historia Augusta</i> 「ローマ皇帝列伝」 の著者と伝えられる六人のうちの一人(4世紀)》.</div>\r\n","<div class=\"hw\">vorax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vorō\">vorō</a>]</div><div class=\"def\"><num>①</num> がつがつ食う;飽くことを知らない.</div><div class=\"def\"><num>②</num> 破壊的な;猛烈な.</div>\r\n","<div class=\"hw\">vors-</div><div class=\"def\">⇒vers-.</div>\r\n","<div class=\"hw\">vort-</div><div class=\"def\">⇒vert-.</div>\r\n","<div class=\"hw\">vorāciter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[vorax]</div><div class=\"def\">むさぼり食うように.</div>\r\n","<div class=\"hw\">vorācitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vorax]</div><div class=\"def\">大食, 暴食.</div>\r\n","<div class=\"hw\">vorāginōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vorāgō\">vorāgō</a>]</div><div class=\"def\"><num>①</num> 穴[窪み]の多い, 割れ目[亀裂]の入った.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 渦を巻いている.</div>\r\n","<div class=\"hw\">vorāgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[voro]</div><div class=\"def\"><num>①</num> (地面・河床などの)深い穴, 割れ目, 亀裂.</div><div class=\"def\"><num>②</num> 淵, 渦(巻き).</div><div class=\"def\"><num>③</num> 飽くことを知らぬ物欲[食欲](の持ち主), (悪徳などの)極み.</div>\r\n","<div class=\"hw\">vorātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[voro]</div><div class=\"def\">むさぼり食う人.</div>\r\n","<div class=\"hw\">vorātrīna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[voro]</div><div class=\"def\"><num>①</num> 居酒屋.</div><div class=\"def\"><num>②</num> (地面の)深い割れ目.</div>\r\n","<div class=\"hw\">vorātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vorō\">voro</a>.</div>\r\n","<div class=\"hw\">vorō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> (丸ごと)のみ下す[込む];がつがつ[むさぼり]食う.</div><div class=\"def\"><num>②</num> 急いで終わらせる.</div><div class=\"def\"><num>③</num> 破滅させる;(病気が)むしばむ.</div>\r\n","<div class=\"hw\">Vosegus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウォセグス《Gallia の山脈;現 Vosges》.</div>\r\n","<div class=\"hw\">voster<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://vester\">vester<SUP>1</SUP></a>, <a href=\"entry://vester\">vester<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">voveō</div><div class=\"pos\">-ēre vōvī vōtum, <i>tr</i></div><div class=\"def\"><num>①</num> (神に)誓約する 〈+<i>acc c. inf fut</i>〉</div><div class=\"ex\"><i>tibi decimam partem praedae ～</i> (<author>L<small>IV</small></author>)<span class=\"ext\">私はあなた(Apollo)に戦利品の10分の1を献げる</span></div><div class=\"ex\"><i>vovere maximam uvam se deo daturum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">神にいちばん大きな房のブドウを奉納すると誓う.</span></div><div class=\"def\"><num>②</num> 願う, 希求する 〈ut〉</div><div class=\"ex\"><i>elige, quid voveas</i> (<author>O<small>V</small></author>)<span class=\"ext\">おまえの願いを選びなさい</span></div><div class=\"ex\"><i>ut tua sim ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">私はあなたに思いを寄せられる女になりたい.</span></div>\r\n","<div class=\"hw\">vox</div><div class=\"pos\">vōcis, <i>f</i></div><div class=\"def\"><num>①</num> 声</div><div class=\"ex\"><i>magna voce</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大声で</span></div><div class=\"ex\"><i>una voce</i> (<author>C<small>IC</small></author>)<span class=\"ext\">異口同音に</span></div><div class=\"ex\"><i>～ viva</i> (<author>S<small>EN</small></author>)<span class=\"ext\">肉声.</span></div><div class=\"def\"><num>②</num> (声の)調子, 響き;アクセント</div><div class=\"ex\"><i>rustica ～ et agrestis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">田舎風で粗野な発音.</span></div><div class=\"def\"><num>③</num> (楽器・動物などが発する)音, 音色</div><div class=\"ex\"><i>septem discrimina vocum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">七絃琴.</span></div><div class=\"def\"><num>④</num> ことば, 発言, 話.</div><div class=\"def\"><num>⑤</num> ことわざ, 格言, 金言.</div><div class=\"def\"><num>⑥</num> おまじないの文句, 呪文.</div><div class=\"def\"><num>⑦</num> 言語.</div><div class=\"def\"><num>⑧</num> 〘文〙語, 単語.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP>〘文〙態.</div>\r\n","<div class=\"hw\">Vulc-</div><div class=\"def\">⇒Volc-.</div>\r\n","<div class=\"hw\">vulgivagus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vulgus/vagus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 方々をさまよい歩く.</div><div class=\"def\"><num>②</num> 行き当たりばったりの.</div>\r\n","<div class=\"hw\">vulgus, volg-</div><div class=\"pos\">-ī, <i>n</i>(<i>m</i>)</div><div class=\"def\"><num>①</num> 民衆, 大衆</div><div class=\"ex\"><i>in ～ [vulgum]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大衆に, 一般に.</span></div><div class=\"def\"><num>②</num> 群集, 大勢.</div><div class=\"def\"><num>③</num> (動物の)群れ.</div>\r\n","<div class=\"hw\">vulgāria, volg-</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://vulgāris\">vulgāris, volg-</a>]</div><div class=\"def\"><num>①</num> 日常茶飯事.</div><div class=\"def\"><num>②</num> ありふれた食物[料理].</div>\r\n","<div class=\"hw\">vulgāris, volg-</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vulgus]</div><div class=\"def\"><num>①</num> 一般大衆の, 俗な</div><div class=\"ex\"><i>～ liberalitas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">万人に行きわたる施し.</span></div><div class=\"def\"><num>②</num> ありふれた, 平凡な.</div><div class=\"def\"><num>③</num> (手続き・取引などが)通例[正規]の.</div>\r\n","<div class=\"hw\">vulgāriter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vulgaris]</div><div class=\"def\">一般に, 普通に.</div>\r\n","<div class=\"hw\">vulgāritās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vulgāris\">vulgāris, volg-</a>]</div><div class=\"def\"><num>①</num> 一般大衆.</div><div class=\"def\"><num>②</num> ありふれていること.</div>\r\n","<div class=\"hw\">vulgārius, volg-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vulgaris]</div><div class=\"def\"><num>①</num> 一般大衆の.</div><div class=\"def\"><num>②</num> ありふれた, 平凡な.</div>\r\n","<div class=\"hw\">Vulgāta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vulgatus<SUP>1</SUP>]</div><div class=\"def\">(<i>sc. </i> editio)</div><div class=\"def\"><num>①</num> ギリシア語訳旧約聖書及び外典(=<a href=\"entry://Septuāgintā\">Septuaginta</a>).</div><div class=\"def\"><num>②</num> ラテン語訳聖書《Hieronymus が4世紀末に翻訳した》.</div>\r\n","<div class=\"hw\">vulgātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vulgo<SUP>2</SUP>]</div><div class=\"def\">(秘密を)漏らす人.</div>\r\n","<div class=\"hw\">vulgātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[vulgo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 広く知られた, 周知の.</div><div class=\"def\"><num>②</num> 通常の, 一般の.</div><div class=\"def\"><num>③</num> 陳腐な, ありふれた.</div><div class=\"def\"><num>④</num> 卑しい.</div><hr><div class=\"hw\">vulgātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">(著作の)公刊.</div>\r\n","<div class=\"hw\">vulgō<SUP>1</SUP>, volg-</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[vulgus]</div><div class=\"def\"><num>①</num> 多勢で, 一勢に.</div><div class=\"def\"><num>②</num> 公然と.</div><div class=\"def\"><num>③</num> 一般に, 普通に.</div><div class=\"def\"><num>④</num> 至る所で.</div><hr><div class=\"hw\">vulgō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vulgus\">vulgus, volg-</a>]</div><div class=\"def\"><num>①</num> 一般大衆に行きわたらせる, 普及させる 〈alqd in alqm;alqd cum alqo〉</div><div class=\"ex\"><i>contagium etiam in alios vulgatum est</i> (<author>C<small>URT</small></author>)<span class=\"ext\">感染が他の者どもにまで及んだ</span></div><div class=\"ex\"><i>se vulgari cum privatis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">私人たちと親しくつきあう.</span></div><div class=\"def\"><num>②</num> (体を)売る, 売春する.</div><div class=\"def\"><num>③</num> 公表する, 広める;(著作を)公刊する.</div><div class=\"def\"><num>④</num> 有名にする.</div>\r\n","<div class=\"hw\">vulnerābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vulnero]</div><div class=\"def\"><num>①</num> 傷つけられる.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 傷つける.</div>\r\n","<div class=\"hw\">vulnerārius<SUP>1</SUP>, voln-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vulnus]</div><div class=\"def\">傷に効く.</div><hr><div class=\"hw\">vulnerārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(傷専門の)医者.</div>\r\n","<div class=\"hw\">vulnerātiō, voln-</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vulnerō\">vulnerō, voln-</a>]</div><div class=\"def\">傷つけること, 傷害.</div>\r\n","<div class=\"hw\">vulnerō, voln-</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[vulnus]</div><div class=\"def\"><num>①</num> 傷つける, 負傷させる.</div><div class=\"def\"><num>②</num> (物を)損傷する.</div><div class=\"def\"><num>③</num> (感情を)傷つける, 侮辱する.</div>\r\n","<div class=\"hw\">vulnifer</div><div class=\"pos\">-fera -ferum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vulnus/fero]</div><div class=\"def\">=<a href=\"entry://vulnificus\">vulnificus</a>.</div>\r\n","<div class=\"hw\">vulnificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vulnus\">vulnus, voln-</a>/facio]</div><div class=\"def\">傷つける, 傷を負わせる.</div>\r\n","<div class=\"hw\">vulnus, voln-</div><div class=\"pos\">-neris, <i>n</i></div><div class=\"def\"><num>①</num> (人・動物・植物・土地などに負わせる)傷</div><div class=\"ex\"><i>multis et illatis et acceptis vulneribus</i> (<author>C<small>AES</small></author>)<span class=\"ext\">(敵味方で)多くの傷を与えたり受けたりして</span></div><div class=\"ex\"><i>longis dat vulnera ramis</i> (<author>O<small>V</small></author>)<span class=\"ext\">(キツツキがくちばしでつついて)長い枝に傷を与える</span></div><div class=\"ex\"><i>vulnera aratri rastorumque fero</i> (<author>O<small>V</small></author>)<span class=\"ext\">私(大地)は犁と鍬による傷に耐えている.</span></div><div class=\"def\"><num>②</num> 《詩》(傷を負わせる)槍, 矢</div><div class=\"ex\"><i>haesit sub gutture ～</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">矢は喉につき刺さったままだ.</span></div><div class=\"def\"><num>③</num> 心の傷;恋の痛手</div><div class=\"ex\"><i>inconsolabile ～ mente gerere</i> (<author>O<small>V</small></author>)<span class=\"ext\">心に慰めようもない傷を負う.</span></div><div class=\"def\"><num>④</num> 危害, 損害, 災厄</div><div class=\"ex\"><i>vulnera imposita provincia sanare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">属州に加えられた傷を癒やす.</span></div>\r\n","<div class=\"hw\">vulnusculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://vulnus\">vulnus, voln-</a>]</div><div class=\"def\">軽傷.</div>\r\n","<div class=\"hw\">vulpis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://vulpēs\">vulpes</a>.</div>\r\n","<div class=\"hw\">vulpiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[vulpes]</div><div class=\"def\">(狐のように)悪賢い者.</div>\r\n","<div class=\"hw\">vulpēcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://vulpēs\">vulpēs, volp-</a>]</div><div class=\"def\">〘動〙子ギツネ.</div>\r\n","<div class=\"hw\">vulpēs, volp-</div><div class=\"pos\">-pis, <i>f</i></div><div class=\"def\"><num>①</num> 〘動〙キツネ(狐)</div><div class=\"ex\">～ <i>jungere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">狐を軛<SUB>くびき</SUB>にかける(=不可能なことを企てる)</span></div><div class=\"ex\"><i>populus est domi leones, foras ～</i> (<author>P<small>ETR</small></author>)<span class=\"ext\">民衆は家ではライオン, 外では狐だ.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>～ marina</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">〘魚〙オナガザメ属の魚.</span></div>\r\n","<div class=\"hw\">vulpīnor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[↑<a href=\"entry://vulpēs\">vulpēs, volp-</a>]</div><div class=\"def\">狐のように狡猾にふるまう.</div>\r\n","<div class=\"hw\">vulpīnus, volp-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vulpes]</div><div class=\"def\">キツネの.</div>\r\n","<div class=\"hw\">Vuls-</div><div class=\"def\">⇒Vols-.</div>\r\n","<div class=\"hw\">vulsella</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://volsella\">volsella</a>.</div>\r\n","<div class=\"hw\">vulsiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vello]</div><div class=\"def\"><num>①</num> 引き抜かれたもの.</div><div class=\"def\"><num>②</num> (馬の)喘息<SUB>ぜんそく</SUB>.</div>\r\n","<div class=\"hw\">vulsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vellō\">vello</a>.</div>\r\n","<div class=\"hw\">vulsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://vellī\">velli</a>(⇒ <a href=\"entry://vellō\">vello</a>).</div>\r\n","<div class=\"hw\">vulsō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[vello]</div><div class=\"def\">(馬が)喘息で苦しむ, 痙攣<SUB>けいれん</SUB>する.</div>\r\n","<div class=\"hw\">vulsūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vello]</div><div class=\"def\">引き抜く[むしる]こと.</div>\r\n","<div class=\"hw\">vult</div><div class=\"pos\">3 <i>sg ind pr</i></div><div class=\"def\">⇒<a href=\"entry://volō\">volo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">vulticulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[vultus]</div><div class=\"def\">しかめつら, 渋面.</div>\r\n","<div class=\"hw\">vultur, volt-</div><div class=\"pos\">-uris, <i>m</i></div><div class=\"def\"><num>①</num> 〘鳥〙ハゲワシ(禿鷲).</div><div class=\"def\"><num>②</num> 強欲な人.</div>\r\n","<div class=\"hw\">Vultur, Volt-</div><div class=\"pos\">-uris, <i>m</i></div><div class=\"def\">ウゥルトゥル《Apulia の Venusia 近くの山》.</div>\r\n","<div class=\"hw\">vulturius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vultur]</div><div class=\"def\"><num>①</num> 〘鳥〙ハゲワシ.</div><div class=\"def\"><num>②</num> 強欲な人.</div><div class=\"def\"><num>③</num> (さいころ遊びの)悪い目.</div>\r\n","<div class=\"hw\">Vulturnum, Volt-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ウゥルトゥルヌム《Campania の Vulturnus 川の河口近くの町》.</div>\r\n","<div class=\"hw\">Vulturnus, Volt-</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ウゥルトゥルヌス《Campania の川;現 Volturno》.</div><div class=\"def\"><num>②</num> 〘神話〙ウゥルトゥルヌス《ローマで崇拝された河神》.</div><div class=\"def\"><num>③</num> 南東の風.</div>\r\n","<div class=\"hw\">vulturīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vultur]</div><div class=\"def\">ハゲワシの.</div>\r\n","<div class=\"hw\">vultus, volt-</div><div class=\"pos\">-ūs, <i>m</i>(別形 <i>n pl</i> vulta, volta)</div><div class=\"def\"><num>①</num> 顔つき, 表情, 容貌</div><div class=\"ex\"><i>imago animi ～ est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">心を映し出すものが表情だ.</span></div><div class=\"def\"><num>②</num> まなざし, 視線</div><div class=\"ex\"><i>vultu in virgine fixo</i> (<author>O<small>V</small></author>)<span class=\"ext\">じっと乙女を見つめて.</span></div><div class=\"def\"><num>③</num> 顔(=<a href=\"entry://faciēs\">facies</a>, <a href=\"entry://ōs\">os</a>).</div><div class=\"def\"><num>④</num> 肖像(画).</div><div class=\"def\"><num>⑤</num> 外観;様相</div><div class=\"ex\"><i>salis placidi ～</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">穏やかな海の面<SUB>おもて</SUB>.</span></div>\r\n","<div class=\"hw\">vultuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vultus]</div><div class=\"def\">しかめつらの;大げさな表情の.</div>\r\n","<div class=\"hw\">vultuōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://vultuōsus\">vultuōsus</a>]</div><div class=\"def\">深刻な顔つきで.</div>\r\n","<div class=\"hw\">vulva, volv-</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 子宮.</div><div class=\"def\"><num>②</num> 豚の子宮《食材として愛好された》.</div><div class=\"def\"><num>③</num> 女性器;〘解〙陰門, 外陰(部).</div>\r\n","<div class=\"hw\">vulvula, volv-</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"def\">小さな vulva (2) .</div>\r\n","<div class=\"hw\">vulvītis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vulva\">vulva, volv-</a>]</div><div class=\"def\">〘病〙陰門[外陰]炎.</div>\r\n","<div class=\"hw\">vādō<SUP>1</SUP></div><div class=\"pos\">-ere vāsī vāsum, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> vadum]</div><div class=\"def\"><num>①</num> 行く, 進む, 歩く.</div><div class=\"def\"><num>②</num> 急いで行く, 突進する</div><div class=\"ex\"><i>in sententiam alcis cursu vadere</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ある人の意見の側に駆け足でつく.</span></div>\r\n","<div class=\"hw\">vāgiō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i></div><div class=\"def\"><num>①</num> (赤児が)産声をあげる;(幼児が)泣く.</div><div class=\"def\"><num>②</num> (ヤギなどが)鳴く.</div><div class=\"def\"><num>③</num> 《詩》鳴り響く.</div>\r\n","<div class=\"hw\">vāgor<SUP>2</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vagio]</div><div class=\"def\">大きな叫び声;(赤児の)産声.</div>\r\n","<div class=\"hw\">vāgulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vagio]</div><div class=\"def\">大声での訴え.</div>\r\n","<div class=\"hw\">vāgīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> vas<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (剣の)鞘<SUB>さや</SUB></div><div class=\"ex\"><i>gladium e vaginā educere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">剣を鞘から抜く.</span></div><div class=\"def\"><num>②</num> (一般に鞘状の)包む[おおう・入れる]もの.</div><div class=\"def\"><num>③</num> (穀物の)外皮, 殻.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙膣.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙鞘<SUB>しょう</SUB>.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘植〙葉鞘.</div>\r\n","<div class=\"hw\">vāgīnismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘医〙腟痙<SUB>ちつけい</SUB>.</div>\r\n","<div class=\"hw\">vāgīnula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vagina]</div><div class=\"def\">(麦の)殻.</div>\r\n","<div class=\"hw\">vāgīnālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\"><num>①</num> 〘解〙腟の.</div><div class=\"def\"><num>②</num> 〘植〙葉鞘の.</div>\r\n","<div class=\"hw\">vāgīnītis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙</div><div class=\"def\"><num>①</num> 腟炎.</div><div class=\"def\"><num>②</num> 腱鞘炎.</div>\r\n","<div class=\"hw\">vāgītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://vāgiō\">vāgiō</a>]</div><div class=\"def\">(赤児の)産声, (幼児の)泣き声;(大人の)苦痛のうめき[悲鳴].</div>\r\n","<div class=\"hw\">vāh, vaha</div><div class=\"pos\"><i>int</i></div><div class=\"def\">(喜び・驚き・苦痛・怒り・軽蔑などを表わす)ああ, おお.</div>\r\n","<div class=\"hw\">vānescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[vanus]</div><div class=\"def\"><num>①</num> 消える, なくなる, 消滅する.</div><div class=\"def\"><num>②</num> 効果がなくなる.</div>\r\n","<div class=\"hw\">vānidicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vanus/dico<SUP>2</SUP>]</div><div class=\"def\">うそをつく, ほら吹きの.</div>\r\n","<div class=\"hw\">vāniloquax</div><div class=\"pos\">-ācis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vanus/loquor]</div><div class=\"def\">うその, 偽りの.</div>\r\n","<div class=\"hw\">vāniloquentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vaniloquus]</div><div class=\"def\"><num>①</num> むだ話.</div><div class=\"def\"><num>②</num> 大言, ほら.</div><div class=\"def\"><num>③</num> 虚栄.</div>\r\n","<div class=\"hw\">vāniloquium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">むだ話, たわいもないおしゃべり.</div>\r\n","<div class=\"hw\">vāniloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vanus/loquor]</div><div class=\"def\"><num>①</num> むだ話をする.</div><div class=\"def\"><num>②</num> 大言壮語する, 大口をたたく.</div>\r\n","<div class=\"hw\">vānitiēs</div><div class=\"pos\">-ēī, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vanus]</div><div class=\"def\"><num>①</num> 虚栄(心).</div><div class=\"def\"><num>②</num> 愚かさ.</div>\r\n","<div class=\"hw\">vānitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vanus]</div><div class=\"def\"><num>①</num> 実体のないこと, 空虚.</div><div class=\"def\"><num>②</num> 不誠実;虚偽, でたらめ.</div><div class=\"def\"><num>③</num> 無益, むだ.</div><div class=\"def\"><num>④</num> 軽薄, だまされやすいこと;愚かさ.</div><div class=\"def\"><num>⑤</num> 見栄, 虚栄心, うぬぼれ.</div>\r\n","<div class=\"hw\">vānitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[vanus]</div><div class=\"def\"><num>①</num> うそ.</div><div class=\"def\"><num>②</num> 虚栄(心).</div>\r\n","<div class=\"hw\">vānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vānus\">vānus</a>]</div><div class=\"def\"><num>①</num> 空虚, 無</div><div class=\"ex\"><i>ad</i> ～ <i>redacta victoria</i> (<author>L<small>IV</small></author>)<span class=\"ext\">無に帰した勝利</span></div><div class=\"ex\"><i>vana rumoris</i> (<author>T<small>AC</small></author>)<span class=\"ext\">根も葉もない噂.</span></div><div class=\"def\"><num>②</num> 無益</div><div class=\"ex\"><i>in</i> ～ (<author>S<small>EN</small></author>)<span class=\"ext\">無益に, むなしく.</span></div><div class=\"def\"><num>③</num> うぬぼれ.</div>\r\n","<div class=\"hw\">vānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 空<SUB>から</SUB>の, 実体のない, うつろな.</div><div class=\"def\"><num>②</num> 無益な, むだな;無効の.</div><div class=\"def\"><num>③</num> 根拠のない, 偽りの.</div><div class=\"def\"><num>④</num> (人が)うわべだけの, 信頼できない;見栄っぱりの.</div>\r\n","<div class=\"hw\">vānē</div><div class=\"pos\">(<i>comp</i> vānius, <i>superl</i> vānissimē)<i>adv</i></div><div class=\"ori\">[vanus]</div><div class=\"def\">むなしく, いたずらに.</div>\r\n","<div class=\"hw\">vāpulāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vāpulō\">vāpulō</a>]</div><div class=\"def\">(さんざん)ぶたれる</div><div class=\"ex\"><i>tribunus ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">「ぶったたかれ長官」《しょっちゅう鞭で打たれている奴隷の自称;tribunus militaris のもじり》.</span></div>\r\n","<div class=\"hw\">vāpulō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> ぶたれる, (鞭で)打たれる.</div><div class=\"def\"><num>②</num> (嵐などに)痛めつけられる;被害をこうむる.</div><div class=\"def\"><num>③</num> 酷評される.</div>\r\n","<div class=\"hw\">vāra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[varus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (破城槌<SUB>つち</SUB>をつるす)木組.</div><div class=\"def\"><num>②</num> (支えにするための)二叉のさお.</div>\r\n","<div class=\"hw\">vāricus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[varus<SUP>1</SUP>]</div><div class=\"def\">大股に歩く.</div><hr><div class=\"hw\">vāricus<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">大股を開いて.</div>\r\n","<div class=\"hw\">vāricātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[varico]</div><div class=\"def\">大股で歩く人.</div>\r\n","<div class=\"hw\">vāricātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vāricō\">varico</a>.</div>\r\n","<div class=\"hw\">vāricō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[varicus<SUP>1</SUP>]</div><div class=\"def\">両足を大きく開く, 大股に歩く.</div>\r\n","<div class=\"hw\">vāricōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[varicus]</div><div class=\"def\">大股歩きで.</div>\r\n","<div class=\"hw\">Vāriānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Varus<SUP>1</SUP> の.</div>\r\n","<div class=\"hw\">Vārus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァールス《ローマ人の家名;特に <i>P. Quintilius ～</i>, Augustus 帝時代の将軍;その軍勢は Teutoburgiensis saltus で Arminius に全滅させられた》.</div><hr><div class=\"hw\">Vārus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウァールス《Liguria と Gallia Narbonensis の境をなす川;現 Var》.</div>\r\n","<div class=\"hw\">vārātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[varo]</div><div class=\"def\">(川が)曲がりくねっていること.</div>\r\n","<div class=\"hw\">vārō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[varus<SUP>1</SUP>]</div><div class=\"def\">(曲がりくねった川などを)測量する.</div>\r\n","<div class=\"hw\">vās<SUP>2</SUP></div><div class=\"pos\">vāsis, <i>n</i>(<i>pl</i><b>vāsa</b> -ōrum)</div><div class=\"def\"><num>①</num> 容器, 入れ物</div><div class=\"ex\">～ <i>vinarium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(ぶどう酒を汲む)ひしゃく.</span></div><div class=\"def\"><num>②</num> (<i>pl</i>)道具, 用具.</div><div class=\"def\"><num>③</num> (<i>pl</i>)(兵士の)携行物</div><div class=\"ex\">～ <i>colligere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(陣地撤収にそなえて)携行物をまとめる.</span></div><div class=\"def\"><num>④</num> ミツバチの巣.</div><div class=\"def\"><num>⑤</num> (<i>pl</i>)睾丸.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘解・生物〙管.</div>\r\n","<div class=\"hw\">vāsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">《古形》=<a href=\"entry://vās\">vas<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">vāsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vādō\">vado<SUP>1</SUP></a>.</div><hr><div class=\"hw\">vāsus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://vās\">vas<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">vāsārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://vās\">vās<SUP>2</SUP></a>]</div><div class=\"def\"><num>①</num> (属州に赴任する総督に与えられる)支度金.</div><div class=\"def\"><num>②</num> 搾油機賃借料.</div><div class=\"def\"><num>③</num> (浴場の)タンク.</div><div class=\"def\"><num>④</num> 文書庫.</div>\r\n","<div class=\"hw\">vāsārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vas<SUP>2</SUP>]</div><div class=\"def\">容器[酒杯]の.</div>\r\n","<div class=\"hw\">Vāsātēs</div><div class=\"pos\">-um [-ium], <B>Vāsātae</B> -ārum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">ウァーサーテース《Aquitania の一部族》.</div>\r\n","<div class=\"hw\">vāsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vādō\">vado<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">vāticinium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vates]</div><div class=\"def\">占い, 予言.</div>\r\n","<div class=\"hw\">vāticinor</div><div class=\"pos\">-ārī -ātus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"ori\">[vates/cano]</div><div class=\"def\"><num>①</num> (霊感を得て)予言[警告]する, (予言者として)教えさとす 〈+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>furor vera vaticinatur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">狂気は真実を語る</span></div><div class=\"ex\"><i>saevam laesi fore numinis iram vaticinatus est</i> (<author>O<small>V</small></author>)<span class=\"ext\">侮辱された神の怒りは激しいだろうと彼は警告した.</span></div><div class=\"def\"><num>②</num> 取りとめのないこと[うわごと]を言う.</div>\r\n","<div class=\"hw\">vāticinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vāticinor\">vāticinor</a>]</div><div class=\"def\">予言(者)の.</div>\r\n","<div class=\"hw\">vāticinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vaticinor]</div><div class=\"def\">予言, 神託.</div>\r\n","<div class=\"hw\">vāticinātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vaticinor]</div><div class=\"def\">占い師, 予言者.</div>\r\n","<div class=\"hw\">vāticinātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vāticinātor\">vāticinātor</a>]</div><div class=\"def\">占い師, 予言者《女性》.</div>\r\n","<div class=\"hw\">vāticinō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i>, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">=<a href=\"entry://vāticinor\">vaticinor</a>.</div>\r\n","<div class=\"hw\">Vāticānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (Tiberis 川の西岸, Janiculum の丘北の)ウァーティカーヌス[バチカン]丘とその周辺.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> バチカン宮殿;教皇庁.</div>\r\n","<div class=\"hw\">Vāticānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">ウァーティカーヌス丘[地区]の</div><div class=\"ex\"><SUP>◇</SUP><i>Vaticana civitas</i><span class=\"ext\">バチカン市国.</span></div><hr><div class=\"hw\">Vāticānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://Vāticānus\">Vāticānus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> ウァーティカーヌス丘の守護神.</div><div class=\"def\"><num>②</num> ウァーティカーヌス地区.</div>\r\n","<div class=\"hw\">vātis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">=<a href=\"entry://vātēs\">vates</a>.</div>\r\n","<div class=\"hw\">vātēs</div><div class=\"pos\">-is, <i>m</i>, <i>f</i></div><div class=\"def\"><num>①</num> 占い師, 予言者.</div><div class=\"def\"><num>②</num> (神の霊感を受けた)詩人</div><div class=\"ex\"><i>Maeonius</i> ～ (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Homērus\">Homerus</a></span></div><div class=\"ex\">～ <i>Lesbia</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Sapphō\">Sappho</a>.</span></div>\r\n","<div class=\"hw\">vē-, vae-</div><div class=\"pos\"><i>pref</i></div><div class=\"def\">語頭に付けて意味を否定したり強めたりする</div><div class=\"ex\"><i>vegrandis</i><span class=\"ext\">(大きいどころか)小さい</span></div><div class=\"ex\"><i>vecors</i><span class=\"ext\">精神が錯乱した.</span></div>\r\n","<div class=\"hw\">vēcordia, vae-</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vēcors\">vēcors, vae-</a>]</div><div class=\"def\">乱心, 狂気, 気ちがい沙汰.</div>\r\n","<div class=\"hw\">vēcors, vae-</div><div class=\"pos\">-cordis, <i>adj</i></div><div class=\"ori\">[ve-/cor]</div><div class=\"def\"><num>①</num> 乱心した, 狂気の.</div><div class=\"def\"><num>②</num> 気違いじみた, 常規を逸した.</div>\r\n","<div class=\"hw\">Vēdiovis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">=<a href=\"entry://Vējovis\">Vejovis</a>.</div>\r\n","<div class=\"hw\">Vēdius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェーディウス《ローマ人の氏族名;特に <i>P</i>. ～ <i>Pollio</i>, Augustus 帝の友人;奴隷への残酷な仕打ちで悪名高かった》.</div>\r\n","<div class=\"hw\">vēgrandis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[ve-/grandis]</div><div class=\"def\"><num>①</num> 大きくない, (異常に)小さい.</div><div class=\"def\"><num>②</num> 異常に大きい.</div>\r\n","<div class=\"hw\">Vēiens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"def\">Veii の.</div><div class=\"hw2\"><b>Vēientēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Veii の住民.</div>\r\n","<div class=\"hw\">Vēientānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://Vēiens\">Vēiens</a>]</div><div class=\"def\">Veii の.</div><div class=\"hw2\"><b>Vēientānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Veii の住民.</div><div class=\"hw2\"><b>Vēientānum</b></div><div class=\"pos2\">-ī, <i>n</i></div><div class=\"def\"><b>1</b> Veii の地所[領地].</div><div class=\"def\"><b>2</b>(<i>sc. </i> vinum)Veii 産の低級なぶどう酒.</div>\r\n","<div class=\"hw\">Vēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Veii の.</div>\r\n","<div class=\"hw\">Vēiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ウェーイイー《Etruria の町;ローマ市の北16km(現 Isola 付近)にあり, Camillus に攻略された(前396)》.</div>\r\n","<div class=\"hw\">Vējovis, Vēdiovis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[ve-/Jovis]</div><div class=\"def\">ウェイヨウィス《ローマの古い神;下界の Juppiter と考えられた》.</div>\r\n","<div class=\"hw\">vēles</div><div class=\"pos\">-litis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> velox]</div><div class=\"def\">(通例 <i>pl</i> vēlitēs で)軽装兵, 散兵.</div>\r\n","<div class=\"hw\">vēlifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[velum/fero]</div><div class=\"def\"><num>①</num> 帆のある, 帆の付いた.</div><div class=\"def\"><num>②</num> (風が)帆をふくらませる.</div>\r\n","<div class=\"hw\">vēlificium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vēlificō\">vēlificō</a>]</div><div class=\"def\">帆を用いること.</div>\r\n","<div class=\"hw\">vēlificor</div><div class=\"pos\">-cārī -cātus sum, <i>intr dep</i></div><div class=\"ori\">[velum/facio]</div><div class=\"def\"><num>①</num> 帆を揚げる, 航行する.</div><div class=\"def\"><num>②</num> ...に努力する, ...を得ようとする 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">vēlificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[velum/facio]</div><div class=\"def\">帆を用いた.</div>\r\n","<div class=\"hw\">vēlificātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[velifico]</div><div class=\"def\"><num>①</num> 〘海〙開き《風向きに対する帆の位置》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 繁栄.</div>\r\n","<div class=\"hw\">vēlificātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vēlificō\">velifico</a>.</div>\r\n","<div class=\"hw\">vēlificō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[velum/facio]</div><div class=\"def\"><num>①</num> 帆走する, 航行する.</div><div class=\"def\"><num>②</num> (船で)通過する.</div>\r\n","<div class=\"hw\">vēliger</div><div class=\"pos\">-gera -gerum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[velum/gero]</div><div class=\"def\">帆(=船)を運ぶ.</div>\r\n","<div class=\"hw\">vēlitor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[veles]</div><div class=\"def\"><num>①</num> (velites が)小競り合いする.</div><div class=\"def\"><num>②</num> 口げんかする, ののしり合う.</div>\r\n","<div class=\"hw\">vēlitāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[veles]</div><div class=\"def\">軽装兵の, 散兵の.</div>\r\n","<div class=\"hw\">vēlitātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[velitor]</div><div class=\"def\"><num>①</num> velites の戦い方;小競り合い.</div><div class=\"def\"><num>②</num> 口げんか.</div>\r\n","<div class=\"hw\">vēlitātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vēlitor\">velitor</a>.</div>\r\n","<div class=\"hw\">vēlitēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">⇒<a href=\"entry://vēles\">veles</a>.</div>\r\n","<div class=\"hw\">vēlivolans</div><div class=\"pos\">-antis, <i>adj</i></div><div class=\"ori\">[velum/volo<SUP>1</SUP>]</div><div class=\"def\">《詩》帆で走る.</div>\r\n","<div class=\"hw\">vēlivolus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》</div><div class=\"def\"><num>①</num> 帆で走る.</div><div class=\"def\"><num>②</num> (海が)帆(=船)を浮かべた.</div>\r\n","<div class=\"hw\">vēlox</div><div class=\"pos\">-ōcis, <i>adj</i></div><div class=\"def\"><num>①</num> 速い, 迅速な.</div><div class=\"def\"><num>②</num> 機敏な, すばやい.</div>\r\n","<div class=\"hw\">vēlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 帆</div><div class=\"ex\"><i>ventis vela dare</i> (<author>N<small>EP</small></author>)<span class=\"ext\">帆を張る, 出帆する.</span></div><div class=\"def\"><num>②</num> 《詩》船.</div><div class=\"def\"><num>③</num> 日よけ;幕, カーテン.</div><div class=\"def\"><num>④</num> 織物, 布.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙帆, ベール状のもの.</div>\r\n","<div class=\"hw\">vēlābrum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> ventus<SUP>3</SUP>]</div><div class=\"def\">=<a href=\"entry://ventilābrum\">ventilabrum</a>.</div><hr><div class=\"hw\">vēlābrum<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[velo]</div><div class=\"def\">=<a href=\"entry://vēlārium\">velarium</a>.</div>\r\n","<div class=\"hw\">Vēlābrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ウェーラーブルム《ローマ市の Capitolinus 丘と Palatinus 丘の間の市場があった地区》.</div>\r\n","<div class=\"hw\">vēlāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[velo]</div><div class=\"def\"><num>①</num> おおうもの《衣服・ベール・毛皮・掛け布など》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙被膜, 卵膜.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘植〙根被.</div>\r\n","<div class=\"hw\">vēlāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[velo]</div><div class=\"def\"><num>①</num> 膜, 被膜.</div><div class=\"def\"><num>②</num> おおうもの《衣服・ベール・目隠し布など》.</div><div class=\"def\"><num>③</num> (<i>pl</i>)(嘆願者が手にする)羊毛を巻いたオリーブの小枝.</div><div class=\"def\"><num>④</num> (ある行為・事実を)言いつくろうこと, 口実.</div>\r\n","<div class=\"hw\">vēlāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[velum]</div><div class=\"def\">日よけ[カーテン]の.</div>\r\n","<div class=\"hw\">vēlārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[velum]</div><div class=\"def\">(劇場の観覧席の上に張られた)日よけ.</div>\r\n","<div class=\"hw\">vēlārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[velum]</div><div class=\"def\">《碑》日よけ・帆などの製作・修繕業者.</div>\r\n","<div class=\"hw\">vēlātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[velo]</div><div class=\"def\">(修道女が)ベールをかぶること.</div>\r\n","<div class=\"hw\">vēlātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vēlō\">velo</a>.</div>\r\n","<div class=\"hw\">vēlātō</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[velo]</div><div class=\"def\">ベールを通して, ぼんやりと.</div>\r\n","<div class=\"hw\">vēlātūra<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[veho]</div><div class=\"def\">運搬[運送]業.</div><hr><div class=\"hw\">vēlātūra<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[velo]</div><div class=\"def\">(修道女の)ベール.</div>\r\n","<div class=\"hw\">vēlō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[velum]</div><div class=\"def\"><num>①</num> おおう, 包む;着せる.</div><div class=\"def\"><num>②</num> 巻き付ける.</div><div class=\"def\"><num>③</num> 飾る.</div><div class=\"def\"><num>④</num> 隠す.</div>\r\n","<div class=\"hw\">vēlōciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://vēlox\">vēlox</a>]</div><div class=\"def\">早く, 速やかに.</div>\r\n","<div class=\"hw\">vēlōcitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[velox]</div><div class=\"def\"><num>①</num> 迅速, 敏捷.</div><div class=\"def\"><num>②</num> (文体の)速度.</div>\r\n","<div class=\"hw\">vēmen-</div><div class=\"def\">⇒vehemen-.</div>\r\n","<div class=\"hw\">vēna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 血管;静脈.</div><div class=\"def\"><num>②</num> 動脈;(<i>pl</i>)脈拍</div><div class=\"ex\"><i>venas tangere</i> (<author>P<small>ERS</small></author>)<span class=\"ext\">脈を取る.</span></div><div class=\"def\"><num>③</num> 水脈, 水路.</div><div class=\"def\"><num>④</num> 鉱脈;鉱石.</div><div class=\"def\"><num>⑤</num> 木目;石目.</div><div class=\"def\"><num>⑥</num> (樹液の)導管;葉脈.</div><div class=\"def\"><num>⑦</num> 割れ目, 裂け目.</div><div class=\"def\"><num>⑧</num> 毛穴.</div><div class=\"def\"><num>⑨</num> 並木.</div><div class=\"def\"><num>⑩</num> 尿管.</div><div class=\"def\"><num>⑪</num> 陰茎.</div><div class=\"def\"><num>⑫</num> 内奥, 中心.</div><div class=\"def\"><num>⑬</num> 天分, 才能.</div>\r\n","<div class=\"hw\">vēnantēs</div><div class=\"pos\">-um, <i>m pl</i>(<i>prp</i>)</div><div class=\"ori\">[venor]</div><div class=\"def\">《詩》狩人たち.</div>\r\n","<div class=\"hw\">vēneō</div><div class=\"pos\">-īre -iī -itum, <i>intr</i></div><div class=\"ori\">[venum/eo<SUP>2</SUP>]</div><div class=\"def\">(<a href=\"entry://vendō\">vendo</a> の <i>pass</i> として用いられる)</div><div class=\"def\"><num>①</num> 売られる;奴隷として売られる.</div><div class=\"def\"><num>②</num> 買収される, (利益に目がくらんで)不正な取引をする</div><div class=\"ex\"><i>venisse libertatem plebis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">平民の自由が売り渡された.</span></div>\r\n","<div class=\"hw\">vēniī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vēneō\">veneo</a>.</div>\r\n","<div class=\"hw\">vēnor</div><div class=\"pos\">-ārī -ātus sum, <i>intr, tr dep</i></div><div class=\"def\"><num>①</num> 狩りに行く</div><div class=\"ex\"><i>venatum in nemus ire</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">森へ狩猟に行く.</span></div><div class=\"def\"><num>②</num> 狩る</div><div class=\"ex\"><i>canibus dammas venari</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">犬を使って鹿を狩る.</span></div><div class=\"def\"><num>③</num> 獲得しようと努める</div><div class=\"ex\"><i>ventosae plebis suffragia venari</i> (<author>H<small>OR</small></author>)<span class=\"ext\">気まぐれな大衆の票をねらう.</span></div>\r\n","<div class=\"hw\">vēnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[venus<SUP>1</SUP>]</div><div class=\"def\">売却, 販売.</div>\r\n","<div class=\"hw\">vēnumdatus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vēnumdō\">venumdo</a>.</div>\r\n","<div class=\"hw\">vēnumdedī</div><div class=\"pos\"><i>pp</i></div><div class=\"def\">⇒<a href=\"entry://vēnumdō\">venumdo</a>.</div>\r\n","<div class=\"hw\">vēnumdō, vēnundō</div><div class=\"pos\">-are -dedī -datum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vēnus\"><SUP>*</SUP>vēnus<SUP>1</SUP></a>/do]</div><div class=\"def\">売りに出す, 売る.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>vēnus<SUP>1</SUP></div><div class=\"pos\">-ī [-ūs], <i>m</i></div><div class=\"def\">(用例は <i>acc</i> vēnum, <i>dat</i> vēnō, vēnuī のみ)売ること, 売却</div><div class=\"ex\"><i>venum dare</i> (<author>S<small>ALL</small></author>) =<i>veno dare [ponere]</i> (<author>T<small>AC</small></author>)<span class=\"ext\">売る</span></div><div class=\"ex\"><i>venum ire</i> (<author>L<small>IV</small></author>)<span class=\"ext\">売られる.</span></div>\r\n","<div class=\"hw\">vēnābulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[venor]</div><div class=\"def\">狩猟用の槍.</div>\r\n","<div class=\"hw\">vēnālicium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vēnālicius\">vēnālicius<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 奴隷市場.</div><div class=\"def\"><num>②</num> (<i>pl</i>)(一群の)奴隷.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 物品税.</div>\r\n","<div class=\"hw\">vēnālicius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[venalis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 売りものの, 売買できる.</div><div class=\"def\"><num>②</num> 売りに出されている奴隷の.</div><hr><div class=\"hw\">vēnālicius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">奴隷商人.</div>\r\n","<div class=\"hw\">vēnāliciārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[venalicius<SUP>2</SUP>]</div><div class=\"def\">奴隷売買の.</div><hr><div class=\"hw\">vēnāliciārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">奴隷商人.</div>\r\n","<div class=\"hw\">vēnālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[venus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 売りものの, 売買できる.</div><div class=\"def\"><num>②</num> 金銭で自由になる;賄賂[買収]の利く.</div><hr><div class=\"hw\">vēnālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">(売りものの若い)奴隷.</div>\r\n","<div class=\"hw\">vēnāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[venatus]</div><div class=\"def\">狩りの</div><div class=\"ex\"><i>～ canis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">猟犬.</span></div>\r\n","<div class=\"hw\">vēnātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[venor]</div><div class=\"def\"><num>①</num> 狩猟.</div><div class=\"def\"><num>②</num> (狩りの)獲物.</div><div class=\"def\"><num>③</num> (見世物としての)野獣狩り;(闘技場で)狩りたてられる野獣.</div>\r\n","<div class=\"hw\">vēnātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[venor]</div><div class=\"def\"><num>①</num> 狩人.</div><div class=\"def\"><num>②</num> (見世物として)野獣と格闘する者.</div><div class=\"def\"><num>③</num> 探究者.</div>\r\n","<div class=\"hw\">vēnātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[venator]</div><div class=\"def\">狩人《女性》.</div>\r\n","<div class=\"hw\">vēnātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[venor]</div><div class=\"def\"><num>①</num> 狩猟.</div><div class=\"def\"><num>②</num> (狩りの)獲物.</div><div class=\"def\"><num>③</num> 漁捕り.</div>\r\n","<div class=\"hw\">vēnātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vēnātor\">vēnātor</a>]</div><div class=\"def\">狩猟の, 狩人が用いる.</div>\r\n","<div class=\"hw\">vēnātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[venor]</div><div class=\"def\">狩り, 狩猟.</div>\r\n","<div class=\"hw\">vēnī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://veniō\">venio</a>.</div>\r\n","<div class=\"hw\">vēnīre<SUP>2</SUP></div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://vēneō\">veneo</a>.</div>\r\n","<div class=\"hw\">vēnōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vena]</div><div class=\"def\"><num>①</num> 血管の多い.</div><div class=\"def\"><num>②</num> 葉脈の多い.</div><div class=\"def\"><num>③</num> 石目の多い.</div><div class=\"def\"><num>④</num> (老齢のために)血管が浮き出た;古い, ひからびた.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘生理〙静脈の.</div>\r\n","<div class=\"hw\">vēnūculus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://vennūculus\">vennuculus</a>.</div>\r\n","<div class=\"hw\">vēpallidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ve-/pallidus]</div><div class=\"def\">(死人のように)青白い.</div>\r\n","<div class=\"hw\">vēr</div><div class=\"pos\">vēris, <i>n</i></div><div class=\"def\"><num>①</num> 春, 春季</div><div class=\"ex\"><i>～ sacrum</i> (<author>L<small>IV</small></author>)<span class=\"ext\">聖春《非常時に春の初穂を奉納する習俗;Sabelli 族に由来する》.</span></div><div class=\"def\"><num>②</num> 人生の春, 青春.</div>\r\n","<div class=\"hw\">vērax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[verus]</div><div class=\"def\">真実を語る[伝える].</div>\r\n","<div class=\"hw\">vēridicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[verus/dico<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 真実を告げる.</div><div class=\"def\"><num>②</num> 正しく予言された.</div>\r\n","<div class=\"hw\">vēridicē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://vēridicus\">vēridicus</a>]</div><div class=\"def\">真実に, 本当に.</div>\r\n","<div class=\"hw\">vērificō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[verus/facio]</div><div class=\"def\">真実として提示する.</div>\r\n","<div class=\"hw\">vēriloquium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[verus/loquor]</div><div class=\"def\"><num>①</num> (語の)原義, 語源(=<a href=\"entry://etymologia\">etymologia</a>).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 真実を語ること.</div>\r\n","<div class=\"hw\">vēritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[verus]</div><div class=\"def\"><num>①</num> 真実, 事実.</div><div class=\"def\"><num>②</num> 現実, 実態, 実相.</div><div class=\"def\"><num>③</num> 本性, 本質.</div><div class=\"def\"><num>④</num> 公正, 誠実, 率直</div><div class=\"ex\"><i>obsequium amicos</i>, ～ <i>odium parit</i> (<author>T<small>ER</small></author>)<span class=\"ext\">追従は友を, 正直は憎しみを生む.</span></div><div class=\"def\"><num>⑤</num> 本来の語源[語形];厳格な規則, 規則の遵守.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 実際の価値[価格].</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘キ教〙福音.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘カト〙(正統)教義.</div>\r\n","<div class=\"hw\">vēriverbium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[verus/verbum]</div><div class=\"def\">真実を語ること, 誠実.</div>\r\n","<div class=\"hw\">vērum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[verus]</div><div class=\"def\"><num>①</num> 真実, 事実</div><div class=\"ex\"><i>vero similis</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">本当らしい</span></div><div class=\"ex\"><span class=\"ext\">⇒ <a href=\"entry://vērīsimilis\">verisimilis</a>.</span></div><div class=\"def\"><num>②</num> 正義.</div><hr><div class=\"hw\">vērum<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">本当に.</div><hr><div class=\"hw\">vērum<SUP>3</SUP></div><div class=\"pos\"><i>conj</i></div><div class=\"def\"><num>①</num> (相手の言い分に一度同意した上で)しかし実際は, とはいえ, しかしながら(しばしば vero, enim, enimvero で強調される).</div><div class=\"def\"><num>②</num> しかし</div><div class=\"ex\"><i>non solum [modo]</i> ... ～ <i>etiam</i><span class=\"ext\">...ばかりでなく...もまた.</span></div><div class=\"def\"><num>③</num> (新しい話題・視点を導入して)ところで.</div><div class=\"def\"><num>④</num> (脇道にそれた話題を元に戻して)それはさておき.</div>\r\n","<div class=\"hw\">vērumtamen, vērum tamen</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">それにしても, とはいえ, それにもかかわらず.</div>\r\n","<div class=\"hw\">vērus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 真実の, 事実の;真実を語る.</div><div class=\"def\"><num>②</num> 真正の, 本物の</div><div class=\"ex\"><i>timor</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">根拠のある恐怖.</span></div><div class=\"def\"><num>③</num> 正当な, 合理的な.</div><div class=\"def\"><num>④</num> 公正な, 誠実な.</div>\r\n","<div class=\"hw\">Vērus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウェールス《ローマ人の家名;特に <i>L. Aurelius</i> ～, 皇帝(在位161‐169);Marcus Aurelius 帝と共同統治した》.</div>\r\n","<div class=\"hw\">vērāciter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[verax]</div><div class=\"def\">誠実に, 真実に.</div>\r\n","<div class=\"hw\">vērācitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[verax]</div><div class=\"def\"><num>①</num> 誠実, 正直.</div><div class=\"def\"><num>②</num> 事実との一致, 真実.</div>\r\n","<div class=\"hw\">vērātrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> (キンポウゲ科)クリスマスローズ属の植物.</div><div class=\"def\"><num>②</num> (ユリ科)バイケイソウ属の植物.《いずれも有毒》.</div>\r\n","<div class=\"hw\">vērē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[verus]</div><div class=\"def\">本当に, 実際に, 正しく.</div>\r\n","<div class=\"hw\">vērīsimilis, vērī similis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[verus/similis]</div><div class=\"def\">真実らしい[らしく見える], もっともらしい, ありそうな</div><div class=\"ex\"><i>nec veri simile loquere nec verum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">おまえは本当らしいことも本当のことも話していない.</span></div>\r\n","<div class=\"hw\">vērīsimiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vērīsimilis\">vērīsimilis, vērī similis</a>]</div><div class=\"def\">真実らしく, もっともらしく.</div>\r\n","<div class=\"hw\">vērīsimilitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[verisimilis]</div><div class=\"def\">真実らしいこと, もっともらしさ.</div>\r\n","<div class=\"hw\">vērō<SUP>1</SUP></div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[verus]</div><div class=\"def\"><num>①</num> 本当に, 実際に.</div><div class=\"def\"><num>②</num> (肯定の答えとして)確かに, その通り.</div><div class=\"def\"><num>③</num> まったく, ...でさえ.</div><div class=\"def\"><num>④</num> さらに.</div><div class=\"def\"><num>⑤</num> その一方で, 他方;しかしながら.</div><hr><div class=\"hw\">vērō<SUP>2</SUP></div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[verus]</div><div class=\"def\">真実を語る.</div>\r\n","<div class=\"hw\">Vērōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウェーローナ《Italia 北部, Gallia Transpadana の町;詩人 Catullus の生地》.</div>\r\n","<div class=\"hw\">Vērōnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Verona の.</div><div class=\"hw2\"><b>Vērōnensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Verona の住民.</div>\r\n","<div class=\"hw\">vēsānia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vesanus]</div><div class=\"def\">狂気, 錯乱.</div>\r\n","<div class=\"hw\">vēsāniō</div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://vēsānus\">vēsānus</a>]</div><div class=\"def\">荒れ狂う.</div>\r\n","<div class=\"hw\">vēsānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ve-/sanus]</div><div class=\"def\"><num>①</num> 気の狂った, 理性を失った.</div><div class=\"def\"><num>②</num> 狂暴な, 激しい.</div>\r\n","<div class=\"hw\">vēsīca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> (人・動物の)膀胱<SUB>ぼうこう</SUB>.</div><div class=\"def\"><num>②</num> (動物の膀胱でつくった)財布, 袋, おおい, ランタン(など).</div><div class=\"def\"><num>③</num> 水ぶくれ, 水疱.</div><div class=\"def\"><num>④</num> 膣.</div><div class=\"def\"><num>⑤</num> 誇大な表現, 誇張.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘解〙嚢<SUB>のう</SUB></div><div class=\"ex\"><i>～ urinaria</i><span class=\"ext\">膀胱.</span></div>\r\n","<div class=\"hw\">vēsīcans</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[vesica]</div><div class=\"def\">〘薬〙発疱剤.</div>\r\n","<div class=\"hw\">vēsīcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vesica]</div><div class=\"def\"><num>①</num> 小さな膀胱.</div><div class=\"def\"><num>②</num> (豆の)莢<SUB>さや</SUB>.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙小嚢<SUB>しょうのう</SUB>, 小胞</div><div class=\"ex\">～ <i>seminalis</i><span class=\"ext\">精嚢.</span></div>\r\n","<div class=\"hw\">vēsīcālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vēsīca\">vēsīca</a>]</div><div class=\"def\">膀胱の.</div>\r\n","<div class=\"hw\">vēsīcārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vesica]</div><div class=\"def\">膀胱の疾患に効く.</div>\r\n","<div class=\"hw\">vēsīcō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[vesica]</div><div class=\"def\">(膀胱のように)ふくれる, 水疱ができる.</div>\r\n","<div class=\"hw\">Vēī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Vēiī\">Veii</a>.</div>\r\n","<div class=\"hw\">vībex</div><div class=\"pos\">-bīcis, <i>f</i></div><div class=\"def\">鞭で打たれた跡, みみずばれ.</div>\r\n","<div class=\"hw\">Vībidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィービディウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Vībius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ウィービウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">vīburnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙ガマズミ《スイカズラ科ガマズミ属の低木》.</div>\r\n","<div class=\"hw\">Vībō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">⇒<a href=\"entry://Valentia\">Valentia (4)</a> .</div>\r\n","<div class=\"hw\">Vībōnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Vibo の.</div>\r\n","<div class=\"hw\">vīcennium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[viciens/annus]</div><div class=\"def\">20年の期間.</div>\r\n","<div class=\"hw\">vīcens-</div><div class=\"def\">⇒vices-.</div>\r\n","<div class=\"hw\">vīciens, vīciēs</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[viginti]</div><div class=\"def\">20回[倍].</div>\r\n","<div class=\"hw\">vīculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://vīcus\">vīcus</a>]</div><div class=\"def\">小さな村.</div>\r\n","<div class=\"hw\">vīcus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 村落, 村.</div><div class=\"def\"><num>②</num> (田舎の)別荘, 地所.</div><div class=\"def\"><num>③</num> (町の)一画;通り, 街.</div>\r\n","<div class=\"hw\">vīcānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vicus]</div><div class=\"def\">村の, 村に住む.</div><hr><div class=\"hw\">vīcānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">村人.</div>\r\n","<div class=\"hw\">vīcātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vicus]</div><div class=\"def\"><num>①</num> 街区ごとに, 街[通り]から街[通り]へ.</div><div class=\"def\"><num>②</num> 村ごとに, 村から村へ.</div>\r\n","<div class=\"hw\">vīcēnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vīcēnī\">vīcēnī</a>]</div><div class=\"def\">20(単位)から成る.</div>\r\n","<div class=\"hw\">vīcēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[viginti]</div><div class=\"def\">20ずつの, 一度に20の.</div>\r\n","<div class=\"hw\">vīcēsima</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vicesimus]</div><div class=\"def\">(<i>sc. </i> pars)20分の1(税).</div>\r\n","<div class=\"hw\">vīcēsimus, vīcens-</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[viginti]</div><div class=\"def\"><num>①</num> 第20の, 20番目の.</div><div class=\"def\"><num>②</num> 20分の1の.</div>\r\n","<div class=\"hw\">vīcēsimānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vicesimus]</div><div class=\"def\">第20軍団の.</div>\r\n","<div class=\"hw\">vīcēsimānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://vīcēsimānus\">vīcēsimānus</a>]</div><div class=\"def\">第20軍団の兵士たち.</div>\r\n","<div class=\"hw\">vīcēsimārius, vīcens-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vīcēsimus\">vīcēsimus, vīcens-</a>]</div><div class=\"def\">20分の1税の.</div>\r\n","<div class=\"hw\">Vīcētia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ウィーケーティア《Venetia の町;Verona と Patavium の間に位置する;現 Vicenza》.</div>\r\n","<div class=\"hw\">Vīcētīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Vicetia の住民.</div>\r\n","<div class=\"hw\">vīcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vincō\">vinco</a>.</div>\r\n","<div class=\"hw\">vīcīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vicinus<SUP>2</SUP>]</div><div class=\"def\">隣人, 近隣の人《女性》.</div>\r\n","<div class=\"hw\">vīcīnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vicinus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 近所, 近辺.</div><div class=\"def\"><num>②</num> 近隣の人々.</div><div class=\"def\"><num>③</num> (時間的な)接近.</div><div class=\"def\"><num>④</num> 類似.</div>\r\n","<div class=\"hw\">vīcīnitus</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[vicinus<SUP>1</SUP>]</div><div class=\"def\">近くで, 近所で.</div>\r\n","<div class=\"hw\">vīcīnitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vicinus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 隣人であること;隣接, 近接.</div><div class=\"def\"><num>②</num> 近隣(地方).</div><div class=\"def\"><num>③</num> 近隣の人々.</div><div class=\"def\"><num>④</num> 類似性.</div>\r\n","<div class=\"hw\">vīcīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vīcīnus\">vīcīnus<SUP>1</SUP></a>]</div><div class=\"def\">付近, 近隣(地方).</div>\r\n","<div class=\"hw\">vīcīnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vicus]</div><div class=\"def\"><num>①</num> 近くの, 近隣の 〈+<i>dat</i> [<i>gen</i>]〉</div><div class=\"ex\"><i>montis vicina cacumina caelo</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">天に近い山の尾根.</span></div><div class=\"def\"><num>②</num> (時間的に)近い, 差し迫った.</div><div class=\"def\"><num>③</num> 似た, 類縁の 〈+<i>gen</i> [<i>dat</i>]〉</div><div class=\"ex\"><i>dialecticorum scientia vicina et finitima eloquentia</i> (<author>C<small>IC</small></author>)<span class=\"ext\">雄弁術と類縁関係にある論理学.</span></div><hr><div class=\"hw\">vīcīnus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">隣人, 近隣の人.</div>\r\n","<div class=\"hw\">vīcīnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vicinus<SUP>1</SUP>]</div><div class=\"def\">その土地の住民が利用[使用]する.</div>\r\n","<div class=\"hw\">vīdulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(旅行)かばん, 行李<SUB>こうり</SUB></div>\r\n","<div class=\"hw\">vīdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://videō\">video</a>.</div>\r\n","<div class=\"hw\">vīgintiangulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vīgintī\">vīgintī</a>/angulus]</div><div class=\"def\">20の角を有する</div><div class=\"ex\"><i>vigintiangula sphaera</i> (<author>A<small>PUL</small></author>)<span class=\"ext\">二十面体.</span></div>\r\n","<div class=\"hw\">vīgintī</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"def\">20(の).</div>\r\n","<div class=\"hw\">vīgintīvir</div><div class=\"pos\">-virī, <i>m</i></div><div class=\"ori\">[viginti/vir]</div><div class=\"def\"><num>①</num> 二十人委員《Campania の農地を平民に分配するために Caesar によって任命された》.</div><div class=\"def\"><num>②</num> 《碑》二十人官(4種の下級官吏の総称)の一人.</div>\r\n","<div class=\"hw\">vīgintīvirātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://vīgintīvir\">vīgintīvir</a>]</div><div class=\"def\">二十人委員[官]の職務.</div>\r\n","<div class=\"hw\">vīgēsimus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://vīcēsimus\">vicesimus</a>.</div>\r\n","<div class=\"hw\">vīlescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr inch</i></div><div class=\"ori\">[vilis]</div><div class=\"def\">(値段が)安くなる, 価値が減る.</div>\r\n","<div class=\"hw\">vīlica, villica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vilicus<SUP>2</SUP>]</div><div class=\"def\">(<i>sc. </i> mulier)農場管理者《女性》;農場管理人の妻.</div>\r\n","<div class=\"hw\">vīlicor, villicor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"ori\">[vilicus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 農場の管理人である.</div><div class=\"def\"><num>②</num> 田舎暮らしをする.</div>\r\n","<div class=\"hw\">vīlicus<SUP>1</SUP>, villicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[villa]</div><div class=\"def\">田舎の.</div><hr><div class=\"hw\">vīlicus<SUP>2</SUP>, villicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 農場管理人.</div><div class=\"def\"><num>②</num> (一般に)管理人, 監督.</div>\r\n","<div class=\"hw\">vīlicātiō, villicātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vīlicō\">vīlicō<SUP>1</SUP>, villicō<SUP>1</SUP></a>]</div><div class=\"def\">農場管理人の職務.</div>\r\n","<div class=\"hw\">vīlicō<SUP>1</SUP>, villicō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[vilicus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 農場の管理人である[として働く].</div><div class=\"def\"><num>②</num> (農場以外の建物・施設を)管理する.</div><hr><div class=\"hw\">vīlicō<SUP>2</SUP>, villicō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">農場管理人.</div>\r\n","<div class=\"hw\">vīlificō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vīlis\">vīlis</a>/facio]</div><div class=\"def\">軽んずる, あなどる.</div>\r\n","<div class=\"hw\">vīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 安価な;安っぽい</div><div class=\"ex\"><i>vili emere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">安く買う</span></div><div class=\"ex\"><i>vili vendere</i> (<author>M<small>ART</small></author>)<span class=\"ext\">安く売る.</span></div><div class=\"def\"><num>②</num> 価値の低い, 尊敬に値しない, つまらない</div><div class=\"ex\"><i>pericula vilia habere</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">危険を物ともしない.</span></div><div class=\"def\"><num>③</num> 身分の低い, 卑賤な.</div><div class=\"def\"><num>④</num> 普通の, ありふれた.</div>\r\n","<div class=\"hw\">vīliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vilis]</div><div class=\"def\"><num>①</num> 安価に.</div><div class=\"def\"><num>②</num> 低く評価して.</div>\r\n","<div class=\"hw\">vīlitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vīlis\">vīlis</a>]</div><div class=\"def\"><num>①</num> 安価.</div><div class=\"def\"><num>②</num> 価値の乏しいこと, 低く評価されること;軽視.</div><div class=\"def\"><num>③</num> 卑しさ, 低劣.</div><div class=\"def\"><num>④</num> 平凡, ありふれていること.</div>\r\n","<div class=\"hw\">vīlitō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[vilis]</div><div class=\"def\">評価を下げる, 卑しくする.</div>\r\n","<div class=\"hw\">vīmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[vieo]</div><div class=\"def\"><num>①</num> (ヤナギなどの)しなやかな細枝.</div><div class=\"def\"><num>②</num> 柳の苗木.</div><div class=\"def\"><num>③</num> Mercurius の杖.</div><div class=\"def\"><num>④</num> 柳細工;籠<SUB>かご</SUB>.</div>\r\n","<div class=\"hw\">vīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://vīmen\">vīmen</a>]</div><div class=\"def\">柳細工.</div>\r\n","<div class=\"hw\">vīmineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vimen]</div><div class=\"def\">柳細工の.</div>\r\n","<div class=\"hw\">vīminālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vimen]</div><div class=\"def\">柳細工に適した</div><div class=\"ex\"><i>Viminalis collis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ウィーミナーリス丘《ローマ市七丘の一つ;市の北東部にあり, 柳の木が多かったことからその名があるという》</span></div><div class=\"ex\"><i>porta Viminalis</i> (<author>F<small>RONTIN</small></author>)<span class=\"ext\">ウィーミナーリス門《porta Collina と porta Esquilina の間にあった》.</span></div>\r\n","<div class=\"hw\">vīminārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》柳細工商人.</div>\r\n","<div class=\"hw\">vīminētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vimen]</div><div class=\"def\">柳園, 柳畑.</div>\r\n","<div class=\"hw\">vīn</div><div class=\"def\">=visne(⇒ <a href=\"entry://volō\">volo<SUP>2</SUP></a>, <a href=\"entry://-ne\">-ne</a>).</div>\r\n","<div class=\"hw\">vīnea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vinum]</div><div class=\"def\"><num>①</num> ブドウの株.</div><div class=\"def\"><num>②</num> ブドウ畑.</div><div class=\"def\"><num>③</num> 〘軍〙木製の移動小屋《中の工兵を敵の矢玉から守る》.</div>\r\n","<div class=\"hw\">vīneus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vinum]</div><div class=\"def\">ぶどう酒の.</div>\r\n","<div class=\"hw\">vīneālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vīnea\">vīnea</a>]</div><div class=\"def\">ブドウ栽培に適した.</div>\r\n","<div class=\"hw\">vīneārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vinea]</div><div class=\"def\">ブドウ栽培の[に適した].</div>\r\n","<div class=\"hw\">vīneāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://vīneārius\">vinearius</a>.</div>\r\n","<div class=\"hw\">vīnitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vinum]</div><div class=\"def\">ブドウ畑で働く人;ブドウを摘む人.</div>\r\n","<div class=\"hw\">vīnolentia, vīnul-</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vīnolentus\">vīnolentus<SUP>1</SUP>, vīnul-<SUP>1</SUP></a>]</div><div class=\"def\">酒びたり, 酩酊.</div>\r\n","<div class=\"hw\">vīnolentus<SUP>1</SUP>, vīnul-<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vinum]</div><div class=\"def\"><num>①</num> 酒びたりの, 酔っぱらった.</div><div class=\"def\"><num>②</num> ぶどう酒の味[匂い]のする.</div><hr><div class=\"hw\">vīnolentus<SUP>2</SUP>, vīnul-<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">酔っぱらい.</div>\r\n","<div class=\"hw\">vīnul-</div><div class=\"def\">⇒vinol-.</div>\r\n","<div class=\"hw\">vīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ぶどう酒.</div><div class=\"def\"><num>②</num> (<i>pl</i>)ぶどう酒の容器[つぼ・杯].</div><div class=\"def\"><num>③</num> (特定の)ブドウ(の実).</div><div class=\"def\"><num>④</num> (ブドウ以外の)果実酒.</div>\r\n","<div class=\"hw\">vīnācea</div><div class=\"pos\">-ae, <i>f</i>, <B>-a</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://vīnāceus\">vīnāceus</a>]</div><div class=\"def\">ブドウのしぼりかす.</div>\r\n","<div class=\"hw\">vīnāceus</div><div class=\"pos\">-ī, <i>m</i>, <B>-ceum</B> -ī, <i>n</i></div><div class=\"ori\">[vinum]</div><div class=\"def\"><num>①</num> ブドウの種子.</div><div class=\"def\"><num>②</num> ブドウのしぼりかす.</div>\r\n","<div class=\"hw\">Vīnālia</div><div class=\"pos\">-ium [-iōrum], <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://vīnālis\">vīnālis</a>]</div><div class=\"def\">ウィーナーリア《年2度行なわれたぶどう酒祭り;～ <i>priora</i> (<author>O<small>V</small></author>) 4月23日に前年収穫のブドウから造られたぶどう酒を Juppiter に捧げた;～ <i>rustica</i> (<author>V<small>ARR</small></author>) 8月19日にその年のブドウの収穫を祝った》.</div>\r\n","<div class=\"hw\">vīnālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vinum]</div><div class=\"def\">ぶどう酒の.</div>\r\n","<div class=\"hw\">vīnārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vīnārius\">vīnārius<SUP>1</SUP></a>]</div><div class=\"def\">ぶどう酒つぼ.</div>\r\n","<div class=\"hw\">vīnārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vinum]</div><div class=\"def\"><num>①</num> ぶどう酒の, ぶどう酒に関する</div><div class=\"ex\"><i>cella vinaria</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">ぶどう酒貯蔵室.</span></div><div class=\"def\"><num>②</num> 《碑》ぶどう酒を商う.</div><hr><div class=\"hw\">vīnārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ぶどう酒商人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 常習的酒飲み.</div>\r\n","<div class=\"hw\">vīnāriārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[vinarius<SUP>1</SUP>]</div><div class=\"def\">《碑》ぶどう酒商人.</div>\r\n","<div class=\"hw\">vīnētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vinum]</div><div class=\"def\">ブドウ畑[園].</div>\r\n","<div class=\"hw\">vīnōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vinum]</div><div class=\"def\"><num>①</num> 酒びたりの, 酩酊した.</div><div class=\"def\"><num>②</num> ぶどう酒の味[匂い]のする.</div>\r\n","<div class=\"hw\">vīpera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vivus/pario<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 〘動〙マムシ.</div><div class=\"def\"><num>②</num> (一般に)ヘビ(蛇).</div><div class=\"def\"><num>③</num> (ヘビのように)陰険な人.</div>\r\n","<div class=\"hw\">vīpereus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vīpera\">vīpera</a>]</div><div class=\"def\"><num>①</num> マムシ[ヘビ]の</div><div class=\"ex\"><i>viperei dentes</i> (<author>O<small>V</small></author>)<span class=\"ext\">(Cadmus が蒔<SUB>ま</SUB>いた)蛇の歯</span></div><div class=\"ex\"><i>viperea anima</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">マムシの(有毒な)息.</span></div><div class=\"def\"><num>②</num> ヘビの髪をした</div><div class=\"ex\"><i>vipereum monstrum</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Medūsa\">Medusa</a></span></div><div class=\"ex\"><i>vipereae sorores</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://furia\">Furiae</a></span></div><div class=\"ex\"><i>～ canis</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Cerberus\">Cerberus</a>.</span></div>\r\n","<div class=\"hw\">vīperīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vipera]</div><div class=\"def\">マムシ[ヘビ]の.</div>\r\n","<div class=\"hw\">vīriculae</div><div class=\"pos\">-ārum, <i>f pl dim</i></div><div class=\"ori\">[vires]</div><div class=\"def\">乏しい財力.</div>\r\n","<div class=\"hw\">vīripotens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[vis/potens]</div><div class=\"def\">(Juppiter が)全能の.</div>\r\n","<div class=\"hw\">vīrulentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vīrulentus\">vīrulentus</a>]</div><div class=\"def\">悪臭.</div>\r\n","<div class=\"hw\">vīrulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vīrus\">vīrus</a>]</div><div class=\"def\"><num>①</num> 有毒な.</div><div class=\"def\"><num>②</num> (言辞が)辛辣な, 毒気を含んだ.</div>\r\n","<div class=\"hw\">vīrus</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ぬめり, 粘液;分泌物.</div><div class=\"def\"><num>②</num> 毒, (蛇の)毒液.</div><div class=\"def\"><num>③</num> 悪臭.</div><div class=\"def\"><num>④</num> 辛み, 苦み.</div><div class=\"def\"><num>⑤</num> (語調・気質の)毒気, 辛辣さ.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘医〙ウィルス, 病原体.</div>\r\n","<div class=\"hw\">vīrēs</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\">⇒<a href=\"entry://vīs\">vis</a>.</div>\r\n","<div class=\"hw\">vīrōsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[virus]</div><div class=\"def\"><num>①</num> 悪臭を放つ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 有毒の.</div>\r\n","<div class=\"hw\">vīs</div><div class=\"pos\">(<i>gen</i> vīs(まれ), <i>dat</i> vī(まれ), <i>acc</i> vim, <i>abl</i> vī;<i>pl nom</i>, <i>acc</i> vīrēs(まれな別形 vīs), <i>gen</i> vīrium), <i>f</i></div><div class=\"def\"><num>①</num> (人・動物・自然の物理的な)力, 強さ, 勢い</div><div class=\"ex\"><i>pro viribus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">力の限り.</span></div><div class=\"def\"><num>②</num> 暴力</div><div class=\"ex\"><i>P. Africano vim attulisse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">P. Africanus に暴力をふるった(=殺害した).</span></div><div class=\"def\"><num>③</num> 性的暴力, 陵辱.</div><div class=\"def\"><num>④</num> 多数, 大量</div><div class=\"ex\"><i>magna ～ jumentorum</i> (<author>C<small>AES</small></author>)<span class=\"ext\">駄獣の大群.</span></div><div class=\"def\"><num>⑤</num> (<i>pl</i>)軍事力, 武力;軍勢</div><div class=\"ex\"><i>satis virium ad certamen</i> (<author>L<small>IV</small></author>)<span class=\"ext\">交戦に充分な兵力.</span></div><div class=\"def\"><num>⑥</num> 精液;(<i>pl</i>)睾丸.</div><div class=\"def\"><num>⑦</num> (薬草などの)効能, 効き目.</div><div class=\"def\"><num>⑧</num> (精神的な)力;能力, 才能.</div><div class=\"def\"><num>⑨</num> (抽象的なものの)影響力, 効果</div><div class=\"ex\">～ <i>conscientiae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">良心の力.</span></div><div class=\"def\"><num>⑩</num> (<i>pl</i>)資産, 財力.</div><div class=\"def\"><num>⑪</num> 拘束力, (法的)有効性.</div><div class=\"def\"><num>⑫</num> (ことばの)意味;価値, 本質</div><div class=\"ex\">～ <i>virtutis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">美徳の本義.</span></div>\r\n","<div class=\"hw\">vīsendus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>gerundiv</i>)</div><div class=\"ori\">[viso]</div><div class=\"def\">見に行く価値のある.</div>\r\n","<div class=\"hw\">vīsibilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[video]</div><div class=\"def\"><num>①</num> 見る能力のある.</div><div class=\"def\"><num>②</num> 見られうる, 可視的な.</div>\r\n","<div class=\"hw\">vīsibiliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://vīsibilis\">vīsibilis</a>]</div><div class=\"def\">目に見えて, 明白に.</div>\r\n","<div class=\"hw\">vīsitātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[visito]</div><div class=\"def\"><num>①</num> 姿を見せること, 出現.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 訪問.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 試練を与えること.</div>\r\n","<div class=\"hw\">vīsitātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://vīsitō\">vīsitō</a>]</div><div class=\"def\"><num>①</num> (頻繁に来る)見物人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 視察に訪れる人.</div>\r\n","<div class=\"hw\">vīsitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://vīsō\">vīsō</a>]</div><div class=\"def\"><num>①</num> しばしば見る[会う].</div><div class=\"def\"><num>②</num> 訪問する.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 視察する.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 罰する;復讐する.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 送る, 遣わす.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>(病気を)治療する.</div>\r\n","<div class=\"hw\">vīsiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[video]</div><div class=\"def\"><num>①</num> 見ること;視力, 視覚.</div><div class=\"def\"><num>②</num> 見えるもの;像, 幻影.</div><div class=\"def\"><num>③</num> 心象, 観念.</div><div class=\"def\"><num>④</num> 洞察, 理解.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘法〙(研究用の)判例.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 見物に行くこと.</div>\r\n","<div class=\"hw\">vīsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[video]</div><div class=\"def\"><num>①</num> 見られるもの, 光景;幻視, 幻像.</div><div class=\"def\"><num>②</num> 〘哲〙表象(<i>Gk</i>▷φαντασ<img class=\"font\" src=\"img/A14E.png\">α◁ の訳語).</div>\r\n","<div class=\"hw\">vīsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://videō\">video</a>.</div><hr><div class=\"hw\">vīsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 見ること, 一瞥<SUB>いちべつ</SUB>.</div><div class=\"def\"><num>②</num> 見られるもの;光景, 外観</div><div class=\"ex\"><i>inopino territa visu</i> (<author>O<small>V</small></author>)<span class=\"ext\">(彼女は)思いもかけぬ姿に驚いて.</span></div><div class=\"def\"><num>③</num> 視力, 視覚.</div>\r\n","<div class=\"hw\">vīsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://vīsō\">viso</a>.</div>\r\n","<div class=\"hw\">vīsō</div><div class=\"pos\">-ere -sī, <i>tr</i>, <i>intr freq</i></div><div class=\"ori\">[video]</div><div class=\"def\"><num>①</num> 注意深く見る[眺める]</div><div class=\"ex\"><i>visere longas pompas</i> (<author>O<small>V</small></author>)<span class=\"ext\">(凱旋の)長い行進を眺める.</span></div><div class=\"def\"><num>②</num> 見に行く[来る]</div><div class=\"ex\"><i>visent quid agam</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">彼らは私がどんな具合か見に来るだろう.</span></div><div class=\"def\"><num>③</num> 訪問する, (病人を)見舞う.</div>\r\n","<div class=\"hw\">vīta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[vivo]</div><div class=\"def\"><num>①</num> 生きていること, 生存;生命</div><div class=\"ex\"><i>in vita esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">生きている</span></div><div class=\"ex\"><i>pro patria vitam profundere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">祖国のために生命を捧げる.</span></div><div class=\"def\"><num>②</num> 人生, 生涯;経歴.</div><div class=\"def\"><num>③</num> 生活, 暮らしぶり;生活の手段</div><div class=\"ex\"><i>～ rustica</i> (<author>C<small>IC</small></author>)<span class=\"ext\">田舎暮らし.</span></div><div class=\"def\"><num>④</num> 伝記.</div><div class=\"def\"><num>⑤</num> (親愛の表現として)いとしい人</div><div class=\"ex\"><i>mea</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">わが命よ.</span></div><div class=\"def\"><num>⑥</num> 人類, 人間.</div><div class=\"def\"><num>⑦</num> 亡霊.</div>\r\n","<div class=\"hw\">vītecula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://vīticula\">viticula</a>.</div>\r\n","<div class=\"hw\">vīteus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vitis]</div><div class=\"def\"><num>①</num> ブドウの.</div><div class=\"def\"><num>②</num> ぶどう酒の.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> ブドウが植えられた.</div>\r\n","<div class=\"hw\">vīticula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vitis]</div><div class=\"def\"><num>①</num> ブドウの株.</div><div class=\"def\"><num>②</num> (つる植物の)茎.</div>\r\n","<div class=\"hw\">vītifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[vitis/fero]</div><div class=\"def\">ブドウを産する.</div>\r\n","<div class=\"hw\">vītigenus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vitis/gigno]</div><div class=\"def\">ブドウから作られた.</div>\r\n","<div class=\"hw\">vītigineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vitis/gigno]</div><div class=\"def\">ブドウの(木の).</div>\r\n","<div class=\"hw\">vītilia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[vitilis]</div><div class=\"def\">柳細工のかご.</div>\r\n","<div class=\"hw\">vītilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vieo]</div><div class=\"def\">柳[小枝]細工の.</div>\r\n","<div class=\"hw\">vītis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> ブドウのつる[木・株].</div><div class=\"def\"><num>②</num> ぶどう酒.</div><div class=\"def\"><num>③</num> ブドウの木の杖(=百人隊長の職杖).</div><div class=\"def\"><num>④</num> 〘軍〙木製の移動小屋(=<a href=\"entry://vīnea\">vinea</a>).</div><div class=\"def\"><num>⑤</num> 〘植〙ブリオニア《ウリ科のつる植物》.</div>\r\n","<div class=\"hw\">vītisator</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://vītis\">vītis</a>/sator]</div><div class=\"def\">ブドウを植える人.</div>\r\n","<div class=\"hw\">vītiārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vitis]</div><div class=\"def\">ブドウの苗床.</div>\r\n","<div class=\"hw\">vītor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[vieo]</div><div class=\"def\">柳[小枝]細工師.</div>\r\n","<div class=\"hw\">vītricus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">義父.</div>\r\n","<div class=\"hw\">Vītula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ウィートゥラ《ローマの勝利と歓喜の女神》.</div>\r\n","<div class=\"hw\">vītulor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"def\">大いに喜ぶ, 歓喜の声をあげる.</div>\r\n","<div class=\"hw\">vītābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vito]</div><div class=\"def\">避けるべき.</div>\r\n","<div class=\"hw\">vītābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vito]</div><div class=\"def\">避けようとしている</div><div class=\"ex\"><i>solus inter tela hostium ～ erumpit</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">ただ一人で敵の矢玉の間をかいくぐりながら突進する</span></div><div class=\"ex\">(+<i>acc</i>)～ <i>classem hostium</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">敵の艦隊を避けて.</span></div>\r\n","<div class=\"hw\">vītālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://vītālis\">vītālis</a>]</div><div class=\"def\"><num>①</num> 生命維持に不可欠な器官[力].</div><div class=\"def\"><num>②</num> 死者に着せる衣, 経帷子<SUB>きょうかたびら</SUB>.</div>\r\n","<div class=\"hw\">vītālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vita]</div><div class=\"def\"><num>①</num> 生命の, 生命を維持する</div><div class=\"ex\"><i>viae vitales</i> (<author>O<small>V</small></author>)<span class=\"ext\">のど笛, 気管.</span></div><div class=\"def\"><num>②</num> 生きている, 生きながらえる</div><div class=\"ex\"><i>lectus</i> ～ (<author>P<small>ETR</small></author>)<span class=\"ext\">棺架(婉曲表現).</span></div><div class=\"def\"><num>③</num> 生きるに値する.</div>\r\n","<div class=\"hw\">vītāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vitalis]</div><div class=\"def\">生命力を伴って.</div>\r\n","<div class=\"hw\">vītālitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vītālis\">vītālis</a>]</div><div class=\"def\">生命力, 活力.</div>\r\n","<div class=\"hw\">vītātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vito]</div><div class=\"def\">避けること, 回避.</div>\r\n","<div class=\"hw\">vītō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\">避ける, のがれる, 免れる 〈+<i>acc</i>;+<i>dat</i>;ne;+<i>inf</i>〉</div><div class=\"ex\"><i>tela vitare</i> (<author>C<small>AES</small></author>)<span class=\"ext\">矢玉を避ける</span></div><div class=\"ex\"><i>vitare ancipiti infortunio</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">二重の災難を免れる</span></div><div class=\"ex\"><i>fratrem vitavi ne viderem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は弟に会うことを避けた</span></div><div class=\"ex\"><i>novo et improbo verbo uti vitaverat</i> (<author>G<small>EL</small></author>)<span class=\"ext\">彼は新しい, 好ましくないことばの使用を避けていた.</span></div>\r\n","<div class=\"hw\">vīvax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[vivo]</div><div class=\"def\"><num>①</num> 生命力のある;長命の, 長持ちする.</div><div class=\"def\"><num>②</num> 生命を与える</div><div class=\"ex\">～ <i>solum</i> (<author>O<small>V</small></author>)<span class=\"ext\">命をはぐくむ土壌.</span></div><div class=\"def\"><num>③</num> 活発な, 元気のある</div><div class=\"ex\"><i>vivacia sulfura</i> (<author>O<small>V</small></author>)<span class=\"ext\">勢いよく燃える硫黄.</span></div>\r\n","<div class=\"hw\">vīverra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘動〙フェレット《イタチ科》.</div>\r\n","<div class=\"hw\">vīverādix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"def\">=<a href=\"entry://vīvirādix\">viviradix</a>.</div>\r\n","<div class=\"hw\">vīvescō</div><div class=\"pos\">-ere vixī, <i>intr inch</i></div><div class=\"ori\">[vivo]</div><div class=\"def\"><num>①</num> 生命を得る.</div><div class=\"def\"><num>②</num> 生きている, 活発になる.</div>\r\n","<div class=\"hw\">vīvicombūrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[vivus<SUP>1</SUP>/comburo]</div><div class=\"def\">火刑.</div>\r\n","<div class=\"hw\">vīvidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vivo]</div><div class=\"def\"><num>①</num> 生命(力)に満ちた.</div><div class=\"def\"><num>②</num> 活発な, 元気な, 力強い</div><div class=\"ex\"><i>vivida senectus</i> (<author>T<small>AC</small></author>)<span class=\"ext\">矍鑠<SUB>かくしゃく</SUB>とした老年.</span></div><div class=\"def\"><num>③</num> 生き写しの, 迫真的な.</div>\r\n","<div class=\"hw\">vīvidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vividus]</div><div class=\"def\">活発に, 意気盛んに.</div>\r\n","<div class=\"hw\">vīvidō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vīvidus\">vīvidus</a>]</div><div class=\"def\">元気づける.</div>\r\n","<div class=\"hw\">vīvificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vivus<SUP>1</SUP>/facio]</div><div class=\"def\">蘇生させる, 生命を与える;活気づける.</div>\r\n","<div class=\"hw\">vīvificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vivifico]</div><div class=\"def\">生気を与えること;蘇生.</div>\r\n","<div class=\"hw\">vīvificātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vivifico]</div><div class=\"def\">蘇生させる人.</div>\r\n","<div class=\"hw\">vīvificātrix</div><div class=\"pos\">-īcis, <i>adj f</i></div><div class=\"ori\">[vivificator]</div><div class=\"def\">蘇生させる.</div>\r\n","<div class=\"hw\">vīvificātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://vīvificātor\">vīvificātor</a>]</div><div class=\"def\">蘇生させる.</div>\r\n","<div class=\"hw\">vīvificō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://vīvificus\">vīvificus</a>]</div><div class=\"def\">蘇生させる, よみがえらせる.</div>\r\n","<div class=\"hw\">vīviparus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vivus<SUP>1</SUP>/pario<SUP>2</SUP>]</div><div class=\"def\">〘生物〙胎生の.</div>\r\n","<div class=\"hw\">vīvirādix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[vivus<SUP>1</SUP>/radix]</div><div class=\"def\">(根の付いた)挿し木.</div>\r\n","<div class=\"hw\">vīviscō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">=<a href=\"entry://vīvescō\">vivesco</a>.</div>\r\n","<div class=\"hw\">vīvisectiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[vivus<SUP>1</SUP>/sectio]</div><div class=\"def\">生体解剖.</div>\r\n","<div class=\"hw\">vīvum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://vīvus\">vīvus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 生きているもの;生身, 急所</div><div class=\"ex\"><i>frigidus imber altius ad ～ persedit</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">冷たい雨が体の心<SUB>しん</SUB>にまで滲み通った.</span></div><div class=\"def\"><num>②</num> 元金, 資本</div><div class=\"ex\"><i>dat de lucro</i>, <i>nihil detrahit de vivo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は儲けから支払いをして, 決して元手には手をつけない.</span></div>\r\n","<div class=\"hw\">vīvus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vivo]</div><div class=\"def\"><num>①</num> 生命のある, 生きている</div><div class=\"ex\"><i>patre vivo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">父の存命中</span></div><div class=\"ex\"><i>vox viva</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(生きている人の)肉声.</span></div><div class=\"def\"><num>②</num> 活発な, 元気な.</div><div class=\"def\"><num>③</num> 自然のままの, 未加工の</div><div class=\"ex\"><i>argentum vivum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">水銀.</span></div><div class=\"def\"><num>④</num> 生き写しの, 迫真的な</div><div class=\"ex\"><i>vivos ducere de marmore vultūs</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">大理石から生きているような面貌を導き出す.</span></div><hr><div class=\"hw\">vīvus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">生命を有する人, 生者</div><div class=\"ex\"><i>pacem et vivis concedere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">生き残った者たちにも平和を許し与える.</span></div>\r\n","<div class=\"hw\">vīvāciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vivax]</div><div class=\"def\">活発に, 精力的に.</div>\r\n","<div class=\"hw\">vīvācitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vivax]</div><div class=\"def\"><num>①</num> 活力, 生命力;長命.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 活発, 敏捷.</div>\r\n","<div class=\"hw\">vīvārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[vivus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 狩猟鳥獣の飼育場.</div><div class=\"def\"><num>②</num> 養魚池.</div>\r\n","<div class=\"hw\">vīvārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[vivus<SUP>1</SUP>]</div><div class=\"def\">生きものの</div><div class=\"ex\"><i>vivariae naves</i> (<author>M<small>ACR</small></author>)<span class=\"ext\">生簀<SUB>いけす</SUB>を備えた漁船.</span></div>\r\n","<div class=\"hw\">vīvātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[vivus<SUP>1</SUP>]</div><div class=\"def\">活気づけられた, 生きいきした.</div>\r\n","<div class=\"hw\">vīvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vivus<SUP>1</SUP>]</div><div class=\"def\">活発に;非常に.</div>\r\n","<div class=\"hw\">vīvō</div><div class=\"pos\">-ere vixī victum, <i>intr</i></div><div class=\"def\"><num>①</num> 生きている, 生きる</div><div class=\"ex\"><i>cum vivere ipsum turpe sit nobis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私には生きていること自体が恥なのに</span></div><div class=\"ex\"><i>vixit annis viginti novem</i> (<author>S<small>UET</small></author>)<span class=\"ext\">享年29であった</span></div><div class=\"ex\">(誓言)<i>ita vivam, putavi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">命を賭けてもいいが, 私は(そう)考えていた</span></div><div class=\"ex\">(+<i>adj</i>)<i>ego ～ miserrimus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はと言えば, この上なくみじめな日々を送っている.</span></div><div class=\"def\"><num>②</num> 生きながらえる, 存続する</div><div class=\"ex\"><i>mea semper gloria vivet</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の名誉は永遠に生き続けるだろう.</span></div><div class=\"def\"><num>③</num> 人生を享受する, 満足して暮らす</div><div class=\"ex\"><i>quando vivemus?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一体いつ私に暇ができるのだろう</span></div><div class=\"ex\">(別れの挨拶)<i>(sg)vive, valeque</i> (<author>H<small>OR</small></author>)<span class=\"ext\">さようなら, お元気で</span></div><div class=\"ex\"><i>(pl)vivite, silvae</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">さらば, 森の木々よ.</span></div><div class=\"def\"><num>④</num> 生命[生活]を支える 〈+<i>abl</i>〉</div><div class=\"ex\"><i>lacte atque pecore vivere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">乳と肉を常食とする.</span></div><div class=\"def\"><num>⑤</num> (特定の)生き方[暮らし方]をする</div><div class=\"ex\"><i>in litteris vivere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">学問に生きる</span></div><div class=\"ex\"><i>cum Pansa vixi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は Pansa と一緒に日々を過ごした.</span></div><div class=\"def\"><num>⑥</num> (絵・彫刻などが)生きているように見える, 真に迫っている.</div>\r\n","<div class=\"hw\">vōbīs</div><div class=\"pos\"><i>dat</i>, <i>abl</i></div><div class=\"def\">⇒<a href=\"entry://vōs\">vos</a>.</div>\r\n","<div class=\"hw\">vōciferor</div><div class=\"pos\">-ārī -ātus sum, <i>intr, tr dep</i></div><div class=\"ori\">[vox/fero]</div><div class=\"def\">大声で叫ぶ[鳴く], 絶叫する 〈+<i>acc c. inf</i>;ne, ut;+間接疑問〉</div><div class=\"ex\"><i>pauca in senatu vociferatus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">元老院で二三, 大声で発言してから</span></div><div class=\"ex\"><i>vociferantur jure rem judicari oportere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼らはこの問題は法に則って裁かれるべきだとわめいている</span></div><div class=\"ex\"><i>ne reciperetur praesidium palam vociferatus est</i> (<author>L<small>IV</small></author>)<span class=\"ext\">援軍は受け入れるなと彼は公然と叫んだ</span></div><div class=\"ex\"><i>vociferatur quo fugiant</i> (<author>L<small>IV</small></author>)<span class=\"ext\">われわれはどこへ逃げればよいのだと彼は絶叫する.</span></div>\r\n","<div class=\"hw\">vōciferātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[vociferor]</div><div class=\"def\"><num>①</num> 大声で叫ぶこと, 絶叫.</div><div class=\"def\"><num>②</num> 熱弁.</div>\r\n","<div class=\"hw\">vōciferātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[vociferor]</div><div class=\"def\">大声で叫ぶ人.</div>\r\n","<div class=\"hw\">vōciferātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[vociferor]</div><div class=\"def\">大きな叫び声.</div>\r\n","<div class=\"hw\">vōciferō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">=<a href=\"entry://vōciferor\">vociferor</a>.</div>\r\n","<div class=\"hw\">vōcificō</div><div class=\"pos\">-āre, <i>intr, tr</i></div><div class=\"ori\">[vox/facio]</div><div class=\"def\"><num>①</num> (ハチが)大きな羽音を立てる.</div><div class=\"def\"><num>②</num> 大声で告知する.</div>\r\n","<div class=\"hw\">vōcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[vox]</div><div class=\"def\"><num>①</num> 小さな[弱い]声.</div><div class=\"def\"><num>②</num> 声の調子, 音調.</div><div class=\"def\"><num>③</num> (<i>pl</i>)陰口, あざけり.</div><div class=\"def\"><num>④</num> 語, ことば.</div><div class=\"def\"><num>⑤</num> 〘文〙母音.</div>\r\n","<div class=\"hw\">vōculātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://vōcula\">vōcula</a>]</div><div class=\"def\">(声の)抑揚, アクセント.</div>\r\n","<div class=\"hw\">vōcālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[vox]</div><div class=\"def\"><num>①</num> 話すことができる;音を発する</div><div class=\"ex\"><i>instrumenti genus vocale</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">口を利く道具(=奴隷).</span></div><div class=\"def\"><num>②</num> 美声の, 響きの豊かな;(楽器が)妙なる調べをかなでる.</div><div class=\"def\"><num>③</num> (詩人に)歌心<SUB>うたごころ</SUB>を催させる.</div><div class=\"def\"><num>④</num> 〘文〙母音の.</div><hr><div class=\"hw\">vōcālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">〘文〙(<i>sc. </i> littera)母音.</div>\r\n","<div class=\"hw\">vōcāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[vocalis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 名前を呼んで.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 声[ことば]で.</div>\r\n","<div class=\"hw\">vōcālitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[vocalis<SUP>1</SUP>]</div><div class=\"def\">(ことばの)快い響き(<i>Gk</i>▷ε<img class=\"font\" src=\"img/A154.png\">φων<img class=\"font\" src=\"img/A14E.png\">α◁ の訳語).</div>\r\n","<div class=\"hw\">vōcālēs</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://vōcālis\">vōcālis<SUP>1</SUP></a>]</div><div class=\"def\">歌手, 音楽家.</div>\r\n","<div class=\"hw\">vōmer</div><div class=\"pos\">-eris, <i>m</i></div><div class=\"def\"><num>①</num> 犂の刃, 犂先<SUB>すきさき</SUB>.</div><div class=\"def\"><num>②</num> 陰茎.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 尖筆.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙鼻の鋤骨<SUB>じょこつ</SUB>.</div>\r\n","<div class=\"hw\">vōmis</div><div class=\"pos\">-meris, <i>m</i></div><div class=\"def\">=<a href=\"entry://vōmer\">vomer</a>.</div>\r\n","<div class=\"hw\">vōs</div><div class=\"pos\"><i>pron pers</i> 2 <i>pl</i></div><div class=\"def\">あなた方, きみたち, おまえら(⇒ <a href=\"entry://tū\">tu</a>).</div>\r\n","<div class=\"hw\">vōsmet</div><div class=\"pos\"><i>pron pers</i></div><div class=\"ori\">[vos/-met]</div><div class=\"def\">《強意形》あなた方自身.</div>\r\n","<div class=\"hw\">vōtifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[votum/fero]</div><div class=\"def\">奉納品を吊り下げる[掛ける].</div>\r\n","<div class=\"hw\">vōtiger</div><div class=\"pos\">-gera -gerum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[votum/gero]</div><div class=\"def\">=<a href=\"entry://vōtifer\">votifer</a>.</div>\r\n","<div class=\"hw\">vōtum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[voveo]</div><div class=\"def\"><num>①</num> (神への)誓約</div><div class=\"ex\"><i>vota facere [nuncupare, suscipere, concipere]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">誓いを立てる</span></div><div class=\"ex\"><i>vota solvere [reddere]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">誓約を実行する</span></div><div class=\"ex\"><i>voti liberari</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(約束を実行して)誓いから解放される.</span></div><div class=\"def\"><num>②</num> (満願成就のお礼としての)奉納物, 供物<SUB>くもつ</SUB>.</div><div class=\"def\"><num>③</num> 祈願;願望, 欲求</div><div class=\"ex\"><i>hoc erat in votis</i> (<author>H<small>OR</small></author>)<span class=\"ext\">これが(私の)願いだった.</span></div><div class=\"def\"><num>④</num> 結婚の誓い, 結婚.</div>\r\n","<div class=\"hw\">vōtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://voveō\">voveo</a>.</div>\r\n","<div class=\"hw\">vōtīvitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://vōtīvus\">vōtīvus</a>]</div><div class=\"def\">誓約, 祈誓.</div>\r\n","<div class=\"hw\">vōtīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://vōtum\">vōtum</a>]</div><div class=\"def\"><num>①</num> (神々に)奉納を誓った, (満願成就のお礼に)奉納される</div><div class=\"ex\"><i>tabula votiva</i> (<author>H<small>OR</small></author>)<span class=\"ext\">奉納額面《難破をまぬがれた船乗りがその時の様子を描いた額を海神に奉納した》</span></div><div class=\"ex\"><i>votiva legatio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">満願成就のお礼参りのために元老院議員が国費による特使の資格で出かけた旅行.</span></div><div class=\"def\"><num>②</num> (願いにこたえて)与えられる, 望みどおりの.</div>\r\n","<div class=\"hw\">vōtīvē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[votivus]</div><div class=\"def\">誓いに従って.</div>\r\n","<div class=\"hw\">vōvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://voveō\">voveo</a>.</div>\r\n"]);
